# --------------------------------------------------------------------------- errors


class Issue:
    """One validation finding, always naming where (ticket id, meta, ...) and the field, plus
    how to fix it: commands to run, or "ask the user: ..." when a person has to decide."""

    __slots__ = ("where", "field", "message", "fix", "optional")

    def __init__(self, where: str, field: str, message: str, fix: Optional[Sequence[str]] = None,
                 optional: bool = False) -> None:
        self.where = where
        self.field = field
        self.message = message
        self.fix: List[str] = list(fix or [])
        self.optional = optional  # an optional-field warning (hidden by check --quiet-optional)

    def __str__(self) -> str:
        if not self.message and not self.field:
            return self.where
        if self.field:
            return f"{self.where} {self.field}: {self.message}"
        return f"{self.where}: {self.message}"

    def as_dict(self) -> Dict[str, Any]:
        return {"id": self.where, "field": self.field, "message": self.message, "fix": list(self.fix)}


class Refused(Exception):
    """Validation error or refused action: exit 1."""

    def __init__(self, message: str, issues: Sequence[Issue] = (), fix: Sequence[str] = ()) -> None:
        super().__init__(message)
        self.message = message
        self.issues = list(issues)
        self.fix = list(fix)


class UsageError(Exception):
    """Bad arguments: exit 2."""

    def __init__(self, message: str, fix: Sequence[str] = ()) -> None:
        super().__init__(message)
        self.message = message
        self.fix = list(fix)



def fix_lines(fixes: Iterable[str], indent: str = "  ") -> List[str]:
    """`fix: <command>` lines; entries that start with "ask the user:" are printed as they are."""
    return [indent + (f if f.startswith(ASK) else "fix: " + f) for f in fixes]


def emit_error(message: str, fixes: Iterable[str] = (), issues: Iterable[Issue] = ()) -> None:
    print(f"error: {message}", file=sys.stderr)
    for ln in fix_lines(fixes):
        print(ln, file=sys.stderr)
    for issue in issues:
        print(f"  {issue}", file=sys.stderr)
        for ln in fix_lines(issue.fix, "    "):
            print(ln, file=sys.stderr)


# --------------------------------------------------------------------------- small helpers


def today() -> str:
    return date.today().isoformat()


def is_int(v: Any) -> bool:
    return isinstance(v, int) and not isinstance(v, bool)


def is_str_list(v: Any) -> bool:
    return isinstance(v, list) and all(isinstance(x, str) for x in v)


def present(t: Dict[str, Any], field: str) -> bool:
    """A required field counts as present when it exists and is not empty."""
    if field not in t or t[field] is None:
        return False
    v = t[field]
    if isinstance(v, str):
        return bool(v.strip())
    if isinstance(v, (list, dict)):
        return len(v) > 0
    return True


def is_legacy(t: Dict[str, Any]) -> bool:
    """Older-format ticket: has neither summary nor story."""
    return "summary" not in t and "story" not in t


def rank_of(t: Dict[str, Any]) -> int:
    r = t.get("rank")
    return r if is_int(r) else 10 ** 9


def by_rank(tickets: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
    return sorted(tickets, key=lambda t: (rank_of(t), str(t.get("id", ""))))


def tickets_of(doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    ts = doc.get("tickets") if isinstance(doc, dict) else None
    return [t for t in ts if isinstance(t, dict)] if isinstance(ts, list) else []


def by_id(doc: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    return {t["id"]: t for t in tickets_of(doc) if isinstance(t.get("id"), str)}


def deps_of(t: Dict[str, Any]) -> List[str]:
    d = t.get("depends_on")
    return [x for x in d if isinstance(x, str)] if isinstance(d, list) else []


def user_tests_of(t: Dict[str, Any]) -> List[Dict[str, Any]]:
    u = t.get("user_tests")
    return [x if isinstance(x, dict) else {} for x in u] if isinstance(u, list) else []


def checks_of(t: Dict[str, Any]) -> Dict[str, Any]:
    c = t.get("user_checks")
    return c if isinstance(c, dict) else {}


def check_result(t: Dict[str, Any], index: int) -> Optional[str]:
    c = checks_of(t).get(str(index))
    return c.get("result") if isinstance(c, dict) else None


def short(s: str, n: int = 50) -> str:
    s = " ".join(str(s).split())
    return s if len(s) <= n else s[: n - 1] + "…"


def vtuple(v: Any) -> Tuple[int, int, int]:
    nums = [int(x) for x in re.findall(r"\d+", str(v))[:3]]
    while len(nums) < 3:
        nums.append(0)
    return (nums[0], nums[1], nums[2])


def ordered_set(t: Dict[str, Any], key: str, value: Any, order: Sequence[str] = TICKET_ORDER) -> None:
    """Set t[key] = value; a new key is inserted at its canonical position (key order is kept)."""
    if key in t or key not in order:
        t[key] = value
        return
    pos = order.index(key)
    items = list(t.items())
    insert_at = 0
    for i, (k, _) in enumerate(items):
        if k in order and order.index(k) < pos:
            insert_at = i + 1
    items.insert(insert_at, (key, value))
    t.clear()
    t.update(items)


def canonical(fields: Dict[str, Any]) -> Dict[str, Any]:
    """New ticket dict in canonical key order; unknown keys go last in their given order."""
    out = {k: fields[k] for k in TICKET_ORDER if k in fields}
    for k, v in fields.items():
        if k not in out:
            out[k] = v
    return out


def recompute_unlocks(doc: Dict[str, Any]) -> None:
    ts = tickets_of(doc)
    for t in ts:
        tid = t.get("id")
        unlocks = sorted(str(u["id"]) for u in ts if isinstance(u.get("id"), str) and tid in deps_of(u))
        ordered_set(t, "unlocks", unlocks)


def expected_unlocks(doc: Dict[str, Any], tid: str) -> List[str]:
    return sorted(str(u["id"]) for u in tickets_of(doc) if isinstance(u.get("id"), str) and tid in deps_of(u))


ROLE_OF: Dict[str, Optional[str]] = {}  # status -> role for the board in use (set by use_roles)
LABEL_OF: Dict[str, str] = {}            # status -> display label


def roles_of(doc: Any) -> Dict[str, Optional[str]]:
    m = meta_of(doc)
    sr = m.get("status_roles") if isinstance(m.get("status_roles"), dict) else {}
    out: Dict[str, Optional[str]] = {}
    for s in list(statuses_of(doc)) + [x for x in sr if isinstance(x, str)]:
        r = sr.get(s)
        out[s] = r if r in ROLES else (s if s in ROLES else None)
    return out


def use_roles(doc: Any) -> None:
    """Make role() / slabel() answer for this board."""
    global ROLE_OF, LABEL_OF
    ROLE_OF = roles_of(doc)
    sl = meta_of(doc).get("status_labels")
    LABEL_OF = {k: v for k, v in sl.items() if isinstance(k, str) and isinstance(v, str) and v.strip()} \
        if isinstance(sl, dict) else {}


def role(status: Any) -> Optional[str]:
    if not isinstance(status, str):
        return None
    if status in ROLE_OF:
        return ROLE_OF[status]
    return status if status in ROLES else None


def slabel(status: Any) -> str:
    return LABEL_OF.get(status, str(status)) if isinstance(status, str) else str(status)


def status_for_role(doc: Dict[str, Any], *wanted: str) -> Optional[str]:
    """The first status (in meta.statuses order) with the first of these roles that has one."""
    rm = roles_of(doc)
    for r in wanted:
        for s in statuses_of(doc):
            if rm.get(s) == r:
                return s
    return None


def names_with_role(doc: Dict[str, Any], roles: Sequence[str]) -> List[str]:
    rm = roles_of(doc)
    return [s for s in statuses_of(doc) if rm.get(s) in roles]


def meta_of(doc: Dict[str, Any]) -> Dict[str, Any]:
    m = doc.get("meta") if isinstance(doc, dict) else None
    return m if isinstance(m, dict) else {}


def statuses_of(doc: Dict[str, Any]) -> List[str]:
    s = meta_of(doc).get("statuses")
    return list(s) if is_str_list(s) else []


def user_test_areas_of(doc: Dict[str, Any]) -> List[str]:
    u = meta_of(doc).get("user_test_areas", DEFAULT_USER_TEST_AREAS)
    return list(u) if is_str_list(u) else []


def parse_csv(s: Optional[str]) -> List[str]:
    if not s:
        return []
    return [x.strip() for x in s.split(",") if x.strip()]


def parse_multi(values: Optional[Sequence[str]]) -> List[str]:
    """Repeated flag values, each of which may also be a comma list; duplicates dropped."""
    out: List[str] = []
    for v in values or []:
        out.extend(parse_csv(v))
    return list(dict.fromkeys(out))


def phases_of(doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    ps = doc.get("phases") if isinstance(doc, dict) else None
    return [p for p in ps if isinstance(p, dict)] if isinstance(ps, list) else []


def unscheduled_ids(doc: Dict[str, Any]) -> Set[str]:
    return {str(p.get("id")) for p in phases_of(doc) if p.get("unscheduled") is True}


def phases_display_order(doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Phases in array order, unscheduled ones last."""
    ps = phases_of(doc)
    return [p for p in ps if p.get("unscheduled") is not True] + [p for p in ps if p.get("unscheduled") is True]


def item_checks_of(t: Dict[str, Any]) -> Dict[str, Any]:
    c = t.get("item_checks")
    return c if isinstance(c, dict) else {}


def item_sort_key(k: str) -> Tuple[int, int, str]:
    m = ITEM_KEY_RE.match(k)
    return (0 if m.group(1) == "acceptance" else 1, int(m.group(2)), k) if m else (2, 0, k)


# --------------------------------------------------------------------------- file I/O


def dumps(doc: Any) -> str:
    return json.dumps(doc, indent=2, ensure_ascii=False) + "\n"


def atomic_write(path: Path, text: str) -> None:
    """Write text to a temp file in the same folder, then os.replace it into place."""
    mode = (path.stat().st_mode & 0o777) if path.exists() else 0o644
    fd, tmp = tempfile.mkstemp(prefix="." + path.name + ".", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, str(path))
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def read_json(path: Path, what: str, retry: str = "") -> Any:
    """retry: the command to run once the file is fixed (added to the fix line)."""
    again = f", then run: {retry}" if retry else ", then run the command again"
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        raise Refused(f"{what} not found: {path}",
                      fix=[f"ls {shlex.quote(str(path.parent))}   (find the right file{again})"])
    except OSError as e:
        raise Refused(f"can't read {what} ({path}): {e}",
                      fix=[ASK + f"board.py can't read {path} ({e.strerror or e}); can you fix its permissions?"])
    try:
        return json.loads(text)
    except json.JSONDecodeError as e:
        if path == TICKETS:
            fix = [ASK + f"kanban/tickets.json isn't valid JSON at line {e.lineno}; was it edited by hand? "
                         "Restore it (git checkout -- kanban/tickets.json) or fix that line?",
                   "git diff -- kanban/tickets.json   (see what changed)"]
        else:
            fix = [f"fix line {e.lineno}, column {e.colno} of {path} so it is valid JSON{again}"]
        raise Refused(f"{what} is not valid JSON (line {e.lineno}, column {e.colno}): {e.msg}", fix=fix)


def read_board() -> Dict[str, Any]:
    if not TICKETS.exists():
        raise Refused(f"no tickets.json next to board.py ({TICKETS})",
                      fix=[f"{CMD} init --project NAME --prefix PFX   (or run /slate:init)",
                           ASK + "what is the project called, and which short id prefix (like ACME) should tickets use?"])
    doc = read_json(TICKETS, "kanban/tickets.json")
    if not isinstance(doc, dict):
        raise Refused("kanban/tickets.json must be a JSON object with meta, phases and tickets",
                      fix=[restore_fix("the whole file")])
    use_roles(doc)
    return doc


def refuse_if_newer(doc: Dict[str, Any]) -> None:
    sv = meta_of(doc).get("schema_version")
    if is_int(sv) and sv > SCHEMA_VERSION:
        raise Refused(NEWER_MSG, fix=[NEWER_FIX])


# Errors the board on disk had when this write started (set by load_for_write). A board that is
# already invalid may still be written when the change repairs it: no new errors and strictly fewer
# errors than before (compared by ticket, field and message). Writes that add errors are refused.
BASE_ERRORS: List[Issue] = []
HAS_ERRORS = "kanban/tickets.json has errors, so nothing was changed. Fix these first:"
ADDS_ERRORS = ("kanban/tickets.json already has errors, and this change would add new ones, so nothing "
               "was changed. New errors:")


def issue_key(i: Issue) -> Tuple[str, str, str]:
    return (i.where, i.field, i.message)


def load_for_write() -> Dict[str, Any]:
    """Load the board for a write: refuse if newer schema. Errors already on disk are remembered in
    BASE_ERRORS; the write then goes through only if it repairs some of them (see write_blockers)."""
    global BASE_ERRORS
    doc = read_board()
    refuse_if_newer(doc)
    BASE_ERRORS = validate(doc)[0]
    return doc


def write_blockers(errors: Sequence[Issue], need_fewer: bool = True) -> Optional[Tuple[str, List[Issue]]]:
    """None when a board with these errors may be written; else (header, issues) to refuse with.
    header "" means "the caller's own header". need_fewer=False: no new errors is enough (sync, logs)."""
    if not errors:
        return None
    if not BASE_ERRORS:
        return ("", list(errors))
    known = {issue_key(e) for e in BASE_ERRORS}
    new = [e for e in errors if issue_key(e) not in known]
    if new:
        return (ADDS_ERRORS, new)
    if need_fewer and len(errors) >= len(BASE_ERRORS):
        return (HAS_ERRORS, list(BASE_ERRORS))
    return None


def refuse_blocked(blocked: Tuple[str, List[Issue]], header: str) -> Refused:
    if blocked[0]:
        return Refused(blocked[0], blocked[1], fix=[f"{CMD} check   (after each fix, until it says ok)"])
    return Refused(header, blocked[1])


def commit(doc: Dict[str, Any], strict: Iterable[str] = (), created: Iterable[str] = (),
           header: str = "not saved: the change would leave the board invalid:", write: bool = True,
           need_fewer: bool = True) -> None:
    """Validate the whole board, then write it atomically (write=False: validate only)."""
    errors, _ = validate(doc, strict=strict, created=created)
    blocked = write_blockers(errors, need_fewer)
    if blocked:
        raise refuse_blocked(blocked, header)
    if write:
        write_board(doc, errors)


def write_board(doc: Dict[str, Any], errors: Optional[Sequence[Issue]] = None, report: bool = True,
                cleanup: Optional[List[Path]] = None) -> None:
    """The one place tickets.json is written: folds finished unlock records into meta.unlock_log
    (unless the caller already did: cleanup), writes atomically, says how many errors a repair left,
    and warns about the board of record."""
    if cleanup is None:
        cleanup = fold_unlock_records(doc)
    atomic_write(TICKETS, dumps(doc))
    for path in cleanup:
        try:
            path.unlink()
        except OSError:
            pass
    if report and BASE_ERRORS:
        left = len(errors) if errors is not None else len(validate(doc)[0])
        print(f"repair: {left} error{'s' if left != 1 else ''} left"
              + (f" (see them: {CMD} check)" if left else " (the board is valid again)"))
    if report:
        warn_board_of_record(doc)


def remove_preview() -> bool:
    try:
        PREVIEW.unlink()
        return True
    except FileNotFoundError:
        return False


# --------------------------------------------------------------------------- fix suggestions


def jq(v: Any) -> str:
    """Shell-quoted JSON, for key:=JSON in a suggested command."""
    return shlex.quote(json.dumps(v, ensure_ascii=False))


def restore_fix(what: str) -> str:
    return (ASK + f"{what} in kanban/tickets.json looks hand-edited and board.py has no command for it; "
            "restore the file (git checkout -- kanban/tickets.json) or correct it by hand?")


FIELD_EXAMPLE = {
    "acceptance": ["The thing works"],
    "test_scenarios": ["When X happens, then Y"],
    "areas": ["backend"],
    "labels": [],
    "depends_on": [],
    "user_tests": [{"title": "Try it", "steps": ["Open the page", "Click the button"],
                    "expect": "What the person should see", "required": True}],
}


def base_field(field: str) -> str:
    return re.split(r"[\[.]", field, maxsplit=1)[0]


def ticket_fix(doc: Dict[str, Any], tid: str, field: str) -> List[str]:
    """Generic fix for a ticket field that board.py can change."""
    t = by_id(doc).get(tid, {})
    out: List[str] = []
    for f in [x.strip() for x in field.split(",")]:
        b = base_field(f)
        if b in FIELD_EXAMPLE:
            out.append(f"{CMD} edit {tid} {b}:={jq(FIELD_EXAMPLE[b])}")
        elif b in STRING_FIELDS or b in ("title", "summary", "story", "description"):
            out.append(f'{CMD} edit {tid} {b}="..."')
        elif b == "status":
            out.append(f"{CMD} set {tid} backlog")
        elif b == "rank":
            out.append(f"{CMD} rerank {tid} --after OTHER_ID   (or --first)")
        elif b == "user_checks":
            out.append(ASK + f"did the user tests on {tid} pass? then: {CMD} usertest {tid} INDEX pass|fail")
        elif b == "commits":
            out.append(restore_fix(f"{tid} {f}"))
            out.append(f"{CMD} link {tid} --commit SHA   (links a commit; it can't repair a broken entry)")
        elif b == "pr":
            url = t.get("pr", {}).get("url") if isinstance(t.get("pr"), dict) else None
            out.append(f"{CMD} link {tid} --pr {shlex.quote(url) if isinstance(url, str) and URL_RE.match(url) else 'URL'} "
                       "--pr-state draft|open|merged|closed")
        else:
            out.append(restore_fix(f"{tid} {f}"))
    return list(dict.fromkeys(out))


def meta_fix(field: str) -> List[str]:
    if field == "project":
        return [f"{CMD} set-meta project=" + shlex.quote("Project name")]
    if field == "repo_url":
        return [f"{CMD} set-meta repo_url=https://github.com/OWNER/REPO",
                f"{CMD} set-meta repo_url:=null   (to remove it)"]
    if field in ("areas", "user_test_areas"):
        return [f"{CMD} set-meta {field}:={jq(DEFAULT_AREAS if field == 'areas' else DEFAULT_USER_TEST_AREAS)}"]
    if field in ("schema_version", "slate_version"):
        return [f"{CMD} migrate"]
    if field == "check_quiet_optional":
        return [f"{CMD} set-meta check_quiet_optional:=true   (or :=false)"]
    return [restore_fix(f"meta.{field}")]


def default_fix(doc: Any, issue: Issue) -> List[str]:
    where = issue.where
    if where == "meta":
        return meta_fix(issue.field)
    d = doc if isinstance(doc, dict) else {}
    if where in by_id(d):
        return ticket_fix(d, where, issue.field)
    return [restore_fix(f"{where} {issue.field}".strip())]


def unknown_id_fix(doc: Dict[str, Any], tid: str) -> List[str]:
    close = get_close_matches(tid, list(by_id(doc)), n=1)
    out = [f"{CMD} show {close[0]}   (did you mean {close[0]}?)"] if close else []
    out.append(f"{CMD} list 20   (or: {CMD} status) to see the ticket ids")
    return out


# --------------------------------------------------------------------------- validation


def validate_user_tests(tid: str, t: Dict[str, Any], err: Any) -> None:
    uts = t.get("user_tests")
    if uts is None:
        return
    if not isinstance(uts, list):
        err(tid, "user_tests", "must be a list of user tests")
        return
    for j, u in enumerate(uts):
        f = f"user_tests[{j}]"
        if not isinstance(u, dict):
            err(tid, f, "must be an object with title, setup, steps, expect, required")
            continue
        if not (isinstance(u.get("title"), str) and u["title"].strip()):
            err(tid, f + ".title", "missing (required)")
        steps = u.get("steps")
        if not (is_str_list(steps) and steps):
            err(tid, f + ".steps", "must be a non-empty list of steps")
        if not (isinstance(u.get("expect"), str) and u["expect"].strip()):
            err(tid, f + ".expect", "missing (say what the person should see)")
        if "setup" in u and not isinstance(u["setup"], str):
            err(tid, f + ".setup", "must be text")
        if "required" in u and not isinstance(u["required"], bool):
            err(tid, f + ".required", "must be true or false")


def validate_code_links(tid: str, t: Dict[str, Any], err: Any) -> None:
    """commits and pr: optional, written by `link`."""
    if "commits" in t:
        cs = t["commits"]
        if not isinstance(cs, list):
            err(tid, "commits", "must be a list of {sha, date, message, branch?}")
        else:
            seen: Set[str] = set()
            for j, c in enumerate(cs):
                f = f"commits[{j}]"
                if not isinstance(c, dict):
                    err(tid, f, "must be an object with sha, date, message")
                    continue
                sha = c.get("sha")
                if not (isinstance(sha, str) and SHA_RE.match(sha)):
                    err(tid, f + ".sha", "must be 7 to 40 hex characters")
                elif sha.lower() in seen:
                    err(tid, f + ".sha", f"{sha} is listed twice")
                else:
                    seen.add(sha.lower())
                d = c.get("date")
                if not (isinstance(d, str) and DATE_RE.match(d)):
                    err(tid, f + ".date", "must be a date like 2026-09-26")
                if "message" in c and not isinstance(c["message"], str):
                    err(tid, f + ".message", "must be text")
                if "branch" in c and not isinstance(c["branch"], str):
                    err(tid, f + ".branch", "must be text")
    if "pr" in t:
        pr = t["pr"]
        if not isinstance(pr, dict):
            err(tid, "pr", "must be an object with url and state")
            return
        url = pr.get("url")
        if not (isinstance(url, str) and URL_RE.match(url)):
            err(tid, "pr.url", "must be an http:// or https:// link")
        if pr.get("state") not in PR_STATES:
            err(tid, "pr.state", f"'{pr.get('state')}' must be one of {', '.join(PR_STATES)}")
        if "number" in pr and not (is_int(pr["number"]) and pr["number"] >= 1):
            err(tid, "pr.number", "must be a whole number, 1 or more")
        if "title" in pr and not isinstance(pr["title"], str):
            err(tid, "pr.title", "must be text")


def validate_item_checks(tid: str, t: Dict[str, Any], err: Any) -> None:
    """item_checks: optional, written by check-item / uncheck-item."""
    if "item_checks" not in t:
        return
    ic = t["item_checks"]
    if not isinstance(ic, dict):
        err(tid, "item_checks", "must be an object like {\"acceptance:0\": {\"date\": \"2026-09-26\", "
                                "\"evidence\": \"...\"}}", [restore_fix(f"{tid} item_checks")])
        return
    for k, v in ic.items():
        f = f"item_checks[{k}]"
        m = ITEM_KEY_RE.match(k)
        if not m:
            err(tid, f, "key must be acceptance:N or test:N", [restore_fix(f"{tid} {f}")])
            continue
        kind, idx = m.group(1), int(m.group(2))
        items = t.get(ITEM_KINDS[kind])
        n = len(items) if isinstance(items, list) else 0
        if idx >= n:
            err(tid, f, f"no {ITEM_KINDS[kind]} item at index {idx} (it has {n})",
                [f"{CMD} uncheck-item {tid} {kind} {idx}"])
        if not (isinstance(v, dict) and isinstance(v.get("date"), str) and DATE_RE.match(v["date"])
                and isinstance(v.get("evidence", ""), str)):
            err(tid, f, "must be {\"date\": \"YYYY-MM-DD\", \"evidence\": \"...\"}",
                [restore_fix(f"{tid} {f}"), f"{CMD} check-item {tid} {kind} {idx} --evidence \"...\"   "
                                            "(re-ticks it with a correct entry)"])


def validate_done_without(tid: str, t: Dict[str, Any], err: Any) -> None:
    if "done_without" not in t:
        return
    dw = t["done_without"]
    if not (isinstance(dw, dict) and dw and all(k in ("code", "pr") and isinstance(v, str) for k, v in dw.items())):
        err(tid, "done_without", "must be {\"code\": \"reason\"} and/or {\"pr\": \"reason\"}")


def validate(doc: Any, strict: Iterable[str] = (), created: Iterable[str] = ()) -> Tuple[List[Issue], List[Issue]]:
    """Validate the whole board; every issue carries at least one fix line (see validate_raw)."""
    errors, warnings = validate_raw(doc, strict=strict, created=created)
    for issue in errors + warnings:
        if not issue.fix:
            issue.fix = default_fix(doc, issue)
    return errors, warnings


def validate_raw(doc: Any, strict: Iterable[str] = (), created: Iterable[str] = ()) -> Tuple[List[Issue], List[Issue]]:
    """Validate the whole board (spec §6.2 + Contract 1). Returns (errors, warnings).

    strict: ticket ids validated without the legacy exemption (e.g. a ticket leaving draft).
    created: ids of tickets being created now (strict, and titles over 80 chars are errors).
    """
    errors: List[Issue] = []
    warnings: List[Issue] = []
    created_set = set(created)
    strict_set = set(strict) | created_set

    def err(where: str, field: str, message: str, fix: Optional[Sequence[str]] = None) -> None:
        errors.append(Issue(where, field, message, fix))

    def warn(where: str, field: str, message: str, fix: Optional[Sequence[str]] = None) -> None:
        warnings.append(Issue(where, field, message, fix))

    if not isinstance(doc, dict):
        err("board", "", "tickets.json must be a JSON object with meta, phases and tickets")
        return errors, warnings
    use_roles(doc)

    # ---- meta
    meta = doc.get("meta")
    if not isinstance(meta, dict):
        err("meta", "", "missing or not an object")
        meta = {}
    if not (isinstance(meta.get("project"), str) and meta["project"].strip()):
        err("meta", "project", "missing (required)")
    prefix = meta.get("prefix")
    if not (isinstance(prefix, str) and prefix.strip()):
        err("meta", "prefix", "missing (required)")
        prefix = None
    elif not PREFIX_RE.match(prefix):
        err("meta", "prefix", f"'{prefix}' must be 2-10 capital letters or digits, starting with a letter")
    statuses = meta.get("statuses")
    if not (is_str_list(statuses) and statuses):
        err("meta", "statuses", "missing or empty (required)")
        statuses = []
    sv = meta.get("schema_version")
    if sv is None:
        warn("meta", "schema_version", "missing (older board)")
    elif not is_int(sv):
        err("meta", "schema_version", "must be a whole number")
    elif sv > SCHEMA_VERSION:
        warn("meta", "schema_version",
             f"{sv} is newer than this board.py ({SCHEMA_VERSION}); {NEWER_MSG}", [NEWER_FIX])
    if "slate_version" not in meta:
        warn("meta", "slate_version", "missing (older board)")
    elif not isinstance(meta["slate_version"], str):
        err("meta", "slate_version", "must be text like \"0.1.0\"")
    uta = meta.get("user_test_areas", DEFAULT_USER_TEST_AREAS)
    if not is_str_list(uta):
        err("meta", "user_test_areas", "must be a list of area names")
        uta = []
    meta_areas = meta.get("areas") if is_str_list(meta.get("areas")) else None
    meta_prios = meta.get("priorities") if is_str_list(meta.get("priorities")) else None
    for k in ("areas", "priorities"):
        if k in meta and not is_str_list(meta[k]):
            err("meta", k, "must be a list of names")
    if "repo_url" in meta and not (isinstance(meta["repo_url"], str) and URL_RE.match(meta["repo_url"])):
        err("meta", "repo_url", "must be an http:// or https:// link to the repository")
    if "check_quiet_optional" in meta and not isinstance(meta["check_quiet_optional"], bool):
        err("meta", "check_quiet_optional", "must be true or false")
    validate_status_meta(meta, statuses, err, warn)
    if "removed" in meta and not (isinstance(meta["removed"], list) and all(
            isinstance(x, dict) and isinstance(x.get("ticket"), dict) and isinstance(x["ticket"].get("id"), str)
            for x in meta["removed"])):
        err("meta", "removed", "must be a list of {ticket, removed, reason} entries", [restore_fix("meta.removed")])
    if "unlock_log" in meta and not (isinstance(meta["unlock_log"], list)
                                     and all(isinstance(x, dict) for x in meta["unlock_log"])):
        err("meta", "unlock_log", "must be a list of {date, event, reason, ...} entries",
            [restore_fix("meta.unlock_log")])

    # ---- phases
    phases = doc.get("phases")
    phase_ids: Set[str] = set()
    if not isinstance(phases, list):
        err("phases", "", "missing or not a list (use [] for none)")
        phases = []
    for i, p in enumerate(phases):
        if not isinstance(p, dict) or not (isinstance(p.get("id"), str) and p["id"].strip()):
            err("phases", f"[{i}].id", "each phase needs an id")
            continue
        pid = p["id"]
        if pid in phase_ids:
            err(f"phase {pid}", "id", "duplicate phase id")
        phase_ids.add(pid)
        if not (isinstance(p.get("name"), str) and p["name"].strip()):
            err(f"phase {pid}", "name", "missing (required)",
                [f"{CMD} edit-phase {shlex.quote(pid)} name=" + shlex.quote("Phase name")])
        if "unscheduled" in p and not isinstance(p["unscheduled"], bool):
            err(f"phase {pid}", "unscheduled", "must be true or false",
                [f"{CMD} edit-phase {shlex.quote(pid)} unscheduled:=true   (or :=false)"])

    # ---- tickets
    raw = doc.get("tickets")
    if not isinstance(raw, list):
        err("tickets", "", "missing or not a list (use [] for none)")
        return errors, warnings
    id_re = re.compile(r"^" + re.escape(prefix) + r"-\d{3,}$") if prefix else None
    by: Dict[str, Dict[str, Any]] = {}
    for i, t in enumerate(raw):
        if not isinstance(t, dict):
            err(f"ticket #{i + 1}", "", "each ticket must be a JSON object")
            continue
        tid = t.get("id")
        if not (isinstance(tid, str) and tid.strip()):
            err(f"ticket #{i + 1}", "id", "missing (required)")
            continue
        if tid in by:
            err(tid, "id", "duplicate id (used by more than one ticket)")
            continue
        by[tid] = t
        if id_re and not id_re.match(tid):
            err(tid, "id", f"must look like {prefix}-001 (the board prefix, a dash, 3+ digits)")

    ranks: Dict[int, str] = {}
    for tid, t in by.items():
        status = t.get("status")
        draft = role(status) == "draft"
        legacy = is_legacy(t) and tid not in strict_set

        # structure that holds for every ticket, drafts included
        if not (isinstance(status, str) and status):
            err(tid, "status", "missing (required)")
        elif status not in statuses:
            err(tid, "status", f"'{status}' is not one of meta.statuses ({', '.join(statuses)})",
                [f"{CMD} set {tid} STATUS   (STATUS one of: {', '.join(statuses)})"])
        if "rank" not in t:
            err(tid, "rank", "missing (required)")
        elif not is_int(t["rank"]) or t["rank"] < 1:
            err(tid, "rank", "must be a whole number, 1 or more")
        elif t["rank"] in ranks:
            err(tid, "rank", f"{t['rank']} is also used by {ranks[t['rank']]} (ranks must be unique)",
                [f"{CMD} rerank {tid} --after {ranks[t['rank']]}"])
        else:
            ranks[t["rank"]] = tid
        phase = t.get("phase")
        if isinstance(phase, str) and phase and phase not in phase_ids:
            err(tid, "phase", f"'{phase}' is not a phase in phases",
                [f"{CMD} add-phase --id {shlex.quote(phase)} --name \"...\" --goal \"...\" --demo \"...\"",
                 f"{CMD} edit {tid} phase=PHASE   (PHASE one of: {', '.join(sorted(phase_ids)) or 'none yet'})"])
        for f in STRING_FIELDS:
            if f in t and t[f] is not None and not isinstance(t[f], str):
                err(tid, f, "must be text")
        for f in LIST_FIELDS:
            if f in t and not is_str_list(t[f]):
                err(tid, f, "must be a list of text values")
        deps = deps_of(t)
        for d in deps:
            without = f"{CMD} edit {tid} depends_on:={jq([x for x in deps if x != d])}"
            if d == tid:
                err(tid, "depends_on", "a ticket can't depend on itself", [without])
            elif d not in by:
                err(tid, "depends_on", f"'{d}' does not exist", [without])
            elif role(by[d].get("status")) == "draft" and not draft:
                err(tid, "depends_on", f"{d} is a draft; promote {d} first or make {tid} a draft too",
                    [f"{CMD} promote {d}", without])
        validate_code_links(tid, t, err)
        validate_done_without(tid, t, err)
        validate_item_checks(tid, t, err)
        if "claimed_by" in t:
            c = t["claimed_by"]
            if not (isinstance(c, dict) and isinstance(c.get("by"), str) and c["by"].strip()
                    and isinstance(c.get("since"), str) and MINUTE_RE.match(c["since"])):
                err(tid, "claimed_by", "must be {\"by\": \"branch or name\", \"since\": \"YYYY-MM-DD HH:MM\"}",
                    [f"{CMD} release {tid} --take-over \"broken claim\"", f"{CMD} claim {tid} --take-over \"broken claim\""])

        if draft:
            for f in DRAFT_REQUIRED:
                if not present(t, f):
                    err(tid, f, "missing (required, even for a draft)")
            continue

        # required fields
        for f in BASE_REQUIRED:
            if f not in t:
                err(tid, f, "missing (required)")
            elif isinstance(t[f], str) and not t[f].strip():
                err(tid, f, "empty (required)")
        missing_new: List[str] = []
        for f in CONTENT_REQUIRED:
            if not present(t, f):
                if legacy:
                    missing_new.append(f)
                else:
                    err(tid, f, "missing (required)")
        if missing_new:
            warn(tid, ", ".join(missing_new),
                 "missing (older-format ticket (no summary/story); fill these in when you next edit it)")

        title = t.get("title")
        if isinstance(title, str):
            if not title.strip():
                err(tid, "title", "missing (required)")
            elif len(title) > TITLE_MAX:
                msg = f"is {len(title)} characters; keep it to {TITLE_MAX} or fewer"
                (err if tid in created_set else warn)(tid, "title", msg,
                                                      [f"{CMD} edit {tid} title=" + shlex.quote("a shorter title")])

        areas = t.get("areas") if is_str_list(t.get("areas")) else []
        if meta_areas is not None:
            for a in areas:
                if a not in meta_areas:
                    warn(tid, "areas", f"'{a}' is not in meta.areas ({', '.join(meta_areas)})",
                         [f"{CMD} set-meta areas:={jq(meta_areas + [a])}",
                          f"{CMD} edit {tid} areas:={jq([x for x in areas if x in meta_areas] or meta_areas[:1])}"])
        prio = t.get("priority")
        if meta_prios is not None and isinstance(prio, str) and prio not in meta_prios:
            warn(tid, "priority", f"'{prio}' is not in meta.priorities ({', '.join(meta_prios)})",
                 [f"{CMD} edit {tid} priority=PRIORITY   (one of: {', '.join(meta_prios)})"])

        if not legacy and is_str_list(t.get("test_scenarios")):
            for s in t["test_scenarios"]:
                if "when" not in s.lower():
                    warn(tid, "test_scenarios", f"'{short(s)}' should read \"When ..., then ...\"",
                         [f"{CMD} edit {tid} test_scenarios:={jq(['When ..., then ...'])}"])

        # user tests
        validate_user_tests(tid, t, err)
        uts = user_tests_of(t)
        ut_hits = [a for a in areas if a in uta]
        if ut_hits and not any(u.get("required") is True for u in uts):
            msg = (f"area '{ut_hits[0]}' is in meta.user_test_areas, so the ticket needs at least "
                   "one user test with \"required\": true")
            (warn if legacy else err)(tid, "user_tests", msg,
                                      [f"{CMD} edit {tid} user_tests:={jq(FIELD_EXAMPLE['user_tests'])}"])
        if "user_checks" in t:
            uc = t["user_checks"]
            if not isinstance(uc, dict):
                err(tid, "user_checks", "must be an object keyed by user test index",
                    [restore_fix(f"{tid} user_checks")])
            else:
                for k, v in uc.items():
                    if not (k.isdigit() and int(k) < len(uts)):
                        err(tid, f"user_checks[{k}]", "no user test at that index",
                            [restore_fix(f"{tid} user_checks[{k}]")])
                    if not (isinstance(v, dict) and v.get("result") in ("pass", "fail")):
                        err(tid, f"user_checks[{k}]", "must be {\"result\": \"pass\"|\"fail\", ...}",
                            [ASK + f"did {tid} user test {k} pass?",
                             f"{CMD} usertest {tid} {k} pass|fail   (after the user answers)"])
        if "handoff" in t:
            h = t["handoff"]
            if not (isinstance(h, list) and all(isinstance(x, dict) for x in h)):
                err(tid, "handoff", "must be a list of {date, status, note}")

        if not legacy:
            if not present(t, "visual") and any(len(u.get("steps") or []) >= 3 for u in uts):
                warnings.append(Issue(tid, "visual", "missing; a picture helps readers follow a multi-step flow",
                                      optional=True))
            if not present(t, "technical"):
                warnings.append(Issue(tid, "technical", "missing (optional; where file names and risks go)",
                                      [f"{CMD} edit {tid} technical=" + shlex.quote("Files: ...; risks: ...")],
                                      optional=True))

        # done / merge_ready gating
        if role(status) in FINISHED:
            for d in deps:
                if d in by and role(by[d].get("status")) != "done":
                    err(tid, "status", f"{status}, but dependency {d} is {by[d].get('status')}",
                        [ASK + f"{tid} is {status} but {d} isn't done; finish {d}, or reopen {tid}?",
                         f"{CMD} set {tid} backlog   (reopen {tid})"])
            for j, u in enumerate(uts):
                if u.get("required") is True and check_result(t, j) != "pass":
                    err(tid, "user_checks",
                        f"{status}, but required user test {j} '{short(u.get('title', ''))}' has no pass recorded",
                        [ASK + f"did '{short(u.get('title', ''))}' pass when you tried it?",
                         f"{CMD} usertest {tid} {j} pass   (only after the user says it passed)"])

        # ranks after dependencies
        if is_int(t.get("rank")):
            for d in deps:
                dt = by.get(d)
                if dt is not None and role(dt.get("status")) != "draft" and is_int(dt.get("rank")) \
                        and dt["rank"] >= t["rank"]:
                    err(tid, "rank", f"{t['rank']} must come after dependency {d} (rank {dt['rank']})",
                        [f"{CMD} rerank {tid} --after {d}",
                         f"{CMD} edit {tid} --rerank   (or add --rerank to the edit that changed depends_on; "
                         "moves it right after its latest dependency)"])

        if "unlocks" in t and is_str_list(t["unlocks"]):
            exp = expected_unlocks(doc, tid)
            if sorted(t["unlocks"]) != exp:
                warn(tid, "unlocks", f"out of date; from depends_on it should be [{', '.join(exp)}] "
                                     "(fixed automatically on the next add, new or edit)",
                     [f"{CMD} edit {tid} depends_on:={jq(deps)}   (any edit of depends_on recomputes unlocks)"])

    # ---- dependency cycles
    state: Dict[str, int] = {}
    reported: Set[frozenset] = set()

    def visit(n: str, path: List[str]) -> None:
        state[n] = 1
        path.append(n)
        for d in deps_of(by[n]):
            if d not in by or d == n:
                continue
            if state.get(d) == 1:
                cyc = path[path.index(d):] + [d]
                key = frozenset(cyc)
                if key not in reported:
                    reported.add(key)
                    a0, b0 = cyc[0], cyc[1]
                    err(a0, "depends_on", "dependency cycle: " + " -> ".join(cyc),
                        [ASK + "which of these dependencies should go: " + ", ".join(
                            f"{x} needs {y}" for x, y in zip(cyc, cyc[1:])) + "?",
                         f"{CMD} edit {a0} depends_on:={jq([x for x in deps_of(by[a0]) if x != b0])}   "
                         f"(drops {a0} -> {b0})"])
            elif state.get(d) is None:
                visit(d, path)
        path.pop()
        state[n] = 2

    for tid in by:
        if state.get(tid) is None:
            visit(tid, [])
    return errors, warnings


# --------------------------------------------------------------------------- queries


def is_ready(t: Dict[str, Any], ids: Dict[str, Dict[str, Any]]) -> bool:
    if role(t.get("status")) not in READY_STATUSES:
        return False
    return all(d in ids and role(ids[d].get("status")) == "done" for d in deps_of(t))


def ready_sorted(doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Ready tickets in rank order; tickets in unscheduled phases are never offered."""
    ids = by_id(doc)
    later = unscheduled_ids(doc)
    return by_rank(t for t in tickets_of(doc) if is_ready(t, ids) and t.get("phase") not in later)


def brief(t: Dict[str, Any]) -> Dict[str, Any]:
    keys = ("id", "title", "summary", "status", "rank", "phase", "priority", "areas", "estimate")
    return {k: t.get(k) for k in keys}


def line(t: Dict[str, Any]) -> str:
    areas = "/".join(t.get("areas") or []) if is_str_list(t.get("areas")) else "?"
    rank = t.get("rank")
    rank_s = f"#{rank:>2}" if is_int(rank) else "#?"
    return (f"{rank_s} {t.get('id')} [{t.get('phase', '?')} {t.get('priority', '?')} {areas} "
            f"{t.get('estimate', '?')}] {t.get('title', '')}  ({status_text(t.get('status'))})")


def find(doc: Dict[str, Any], tid: str) -> Dict[str, Any]:
    t = by_id(doc).get(tid)
    if t is None:
        raise Refused(f"{tid}: no such ticket", fix=unknown_id_fix(doc, tid))
    return t


def removed_of(doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    r = meta_of(doc).get("removed")
    return [x for x in r if isinstance(x, dict) and isinstance(x.get("ticket"), dict)] if isinstance(r, list) else []


def next_number(doc: Dict[str, Any], prefix: str) -> int:
    """Next free number; ids of removed (archived) tickets are never reused."""
    rx = re.compile(r"^" + re.escape(prefix) + r"-(\d+)$")
    every = tickets_of(doc) + [x["ticket"] for x in removed_of(doc)]
    nums = [int(m.group(1)) for t in every for m in [rx.match(str(t.get("id", "")))] if m]
    return max(nums, default=0) + 1


def make_id(prefix: str, n: int) -> str:
    return f"{prefix}-{n:03d}"


def place(doc: Dict[str, Any], new: List[Dict[str, Any]], after: Optional[str],
          before: Optional[str] = None) -> int:
    """Give new tickets ranks: at the end, right after `after`, or right before `before`. Existing
    tickets below the insertion point move down only as far as needed. Returns how many moved."""
    existing = by_rank(t for t in tickets_of(doc) if t not in new)
    if after is None and before is None:
        top = max((rank_of(t) for t in existing if is_int(t.get("rank"))), default=0)
        for i, t in enumerate(new):
            ordered_set(t, "rank", top + 1 + i)
        return 0
    flag, ref = ("--after", after) if after is not None else ("--fixes", before)
    anchor = by_id(doc).get(str(ref))
    if anchor is None or anchor in new:
        raise Refused(f"{flag} {ref}: no such ticket", fix=unknown_id_fix(doc, str(ref)))
    start = rank_of(anchor) if after is not None else rank_of(anchor) - 1
    for i, t in enumerate(new):
        ordered_set(t, "rank", start + 1 + i)
    prev = start + len(new)
    moved = 0
    for t in existing:
        if rank_of(t) <= start:
            continue
        if rank_of(t) <= prev:
            t["rank"] = prev + 1
            moved += 1
        prev = t["rank"]
    return moved


# --------------------------------------------------------------------------- batch files


def load_batch(path: str) -> Dict[str, Any]:
    again = f"{CMD} batch-check --file {path}"
    batch = read_json(Path(path), f"batch file {path}", retry=again)
    if not isinstance(batch, dict) or not isinstance(batch.get("tickets"), list):
        raise Refused(f"batch file {path}: must be {{\"phases\": [...], \"tickets\": [...]}}",
                      fix=[f"rewrite {path} as {{\"phases\": [...], \"tickets\": [{{\"key\": \"...\", ...}}]}}, "
                           f"then run: {again}"])
    if "phases" in batch and not isinstance(batch["phases"], list):
        raise Refused(f"batch file {path}: phases must be a list",
                      fix=[f"in {path}, make \"phases\" a list (or remove it), then run: {again}"])
    return batch


NEW_FLAGS = {
    "title": "--title \"...\"", "summary": "--summary \"...\"", "story": "--story \"...\"",
    "description": "--description \"...\"", "acceptance": "--acceptance \"...\" (once per check)",
    "test_scenarios": "--test \"When ..., then ...\" (once per test)", "areas": "--areas backend,frontend",
    "phase": "--phase P1", "priority": "--priority P2", "estimate": "--estimate 1d",
    "user_tests": "--user-test-json " + jq(FIELD_EXAMPLE["user_tests"][0]), "depends_on": "--depends ID,ID",
    "visual": "--visual \"...\"", "technical": "--technical \"...\"", "labels": "--labels a,b",
}


def batch_fix(source: Optional[str], name: str, field: str, as_draft: bool) -> List[str]:
    """How to fix a batch (or `new`) problem. source is the batch file path, None for `new`."""
    b = base_field(field)
    if source is None:
        flag = NEW_FLAGS.get(b)
        return [f"re-run {CMD} new with " + (flag if flag else f"a corrected {b}")]
    return [f"in {source}, fix \"{field or 'the entry'}\" on {name}, then run: {CMD} batch-check --file {source}"]


def check_batch(doc: Optional[Dict[str, Any]], batch: Dict[str, Any], as_draft: bool = False,
                label: Any = None, source: Optional[str] = None) -> Tuple[List[Issue], List[Issue]]:
    """Validate batch tickets on their own: fields, keys, dependencies, writing rules."""
    errors, warnings = check_batch_raw(doc, batch, as_draft=as_draft, label=label)
    for issue in errors + warnings:
        if not issue.fix:
            issue.fix = batch_fix(source, issue.where, issue.field, as_draft)
    return errors, warnings


def check_batch_raw(doc: Optional[Dict[str, Any]], batch: Dict[str, Any], as_draft: bool = False,
                    label: Any = None) -> Tuple[List[Issue], List[Issue]]:
    errors: List[Issue] = []
    warnings: List[Issue] = []

    def err(where: str, field: str, message: str, fix: Optional[Sequence[str]] = None) -> None:
        errors.append(Issue(where, field, message, fix))

    def warn(where: str, field: str, message: str, fix: Optional[Sequence[str]] = None) -> None:
        warnings.append(Issue(where, field, message, fix))

    board_ids = by_id(doc) if doc else {}
    board_phases = {p.get("id"): p for p in (doc or {}).get("phases", []) if isinstance(p, dict)}
    uta = user_test_areas_of(doc) if doc else list(DEFAULT_USER_TEST_AREAS)
    batch_phases: Set[str] = set()
    for i, p in enumerate(batch.get("phases") or []):
        if not (isinstance(p, dict) and isinstance(p.get("id"), str) and p["id"].strip()):
            err("batch phases", f"[{i}].id", "each phase needs an id")
            continue
        pid = p["id"]
        if pid in batch_phases:
            err(f"batch phase {pid}", "id", "listed twice in the batch")
        batch_phases.add(pid)
        if not (isinstance(p.get("name"), str) and p["name"].strip()):
            err(f"batch phase {pid}", "name", "missing (required)")
        if pid in board_phases and board_phases[pid] != p:
            err(f"batch phase {pid}", "id", "already on the board with different details; "
                                            "drop it from the batch or use another id")
    known_phases = batch_phases | set(board_phases)

    keys: Dict[str, int] = {}
    for i, t in enumerate(batch.get("tickets") or []):
        if not isinstance(t, dict):
            err(f"batch ticket #{i + 1}", "", "must be a JSON object")
            continue
        k = t.get("key")
        name = label(i, t) if label else (f"'{k}'" if isinstance(k, str) and k else f"batch ticket #{i + 1}")
        if label is None:
            if not (isinstance(k, str) and k.strip()):
                err(name, "key", "missing (a short name like \"reset-request\")")
            elif k in keys:
                err(name, "key", f"used twice (tickets #{keys[k] + 1} and #{i + 1})")
            elif k in board_ids:
                err(name, "key", "same as an existing ticket id; pick another key")
            else:
                keys[k] = i
        for f in BATCH_FORBIDDEN:
            if f in t:
                err(name, f, "set by board.py; remove it from the batch")
        required = DRAFT_REQUIRED if as_draft else tuple(
            f for f in BASE_REQUIRED + CONTENT_REQUIRED if f not in ("id", "rank", "status", "depends_on"))
        for f in required:
            if not present(t, f):
                err(name, f, "missing (required)" if f != "acceptance" else "must list at least one item")
        for f in STRING_FIELDS:
            if f in t and t[f] is not None and not isinstance(t[f], str):
                err(name, f, "must be text")
        for f in LIST_FIELDS:
            if f in t and not is_str_list(t[f]):
                err(name, f, "must be a list of text values")
        phase = t.get("phase")
        if isinstance(phase, str) and phase and phase not in known_phases:
            err(name, "phase", f"'{phase}' is not in the batch phases or on the board")
        for d in deps_of(t):
            if d in keys and d != k:
                continue
            if d in board_ids:
                if role(board_ids[d].get("status")) == "draft" and not as_draft:
                    err(name, "depends_on", f"{d} is a draft; promote it first")
                continue
            if d == k:
                err(name, "depends_on", "a ticket can't depend on itself")
            elif any(isinstance(x, dict) and x.get("key") == d for x in batch["tickets"]):
                err(name, "depends_on", f"'{d}' comes later in the batch; list it before this ticket")
            else:
                err(name, "depends_on", f"'{d}' is not a batch key or an existing ticket id")
        if as_draft:
            continue
        title = t.get("title")
        if isinstance(title, str) and len(title) > TITLE_MAX:
            err(name, "title", f"is {len(title)} characters; keep it to {TITLE_MAX} or fewer")
        if is_str_list(t.get("test_scenarios")):
            for s in t["test_scenarios"]:
                if "when" not in s.lower():
                    warn(name, "test_scenarios", f"'{short(s)}' should read \"When ..., then ...\"")
        validate_user_tests(name, t, err)
        areas = t.get("areas") if is_str_list(t.get("areas")) else []
        hits = [a for a in areas if a in uta]
        if hits and not any(u.get("required") is True for u in user_tests_of(t)):
            err(name, "user_tests", f"area '{hits[0]}' is in meta.user_test_areas, so the ticket needs "
                                    "at least one user test with \"required\": true")
    return errors, warnings


def build_batch(doc: Dict[str, Any], batch: Dict[str, Any], as_draft: bool, after: Optional[str],
                before: Optional[str] = None) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], int]:
    """Turn batch entries into real tickets on doc (in memory). Returns (phases, tickets, moved)."""
    prefix = meta_of(doc)["prefix"]
    n = next_number(doc, prefix)
    keymap: Dict[str, str] = {}
    entries = batch["tickets"]
    for i, e in enumerate(entries):
        k = e.get("key")
        new_id = make_id(prefix, n + i)
        if isinstance(k, str) and k:
            keymap[k] = new_id
        e["_id"] = new_id
    new_tickets: List[Dict[str, Any]] = []
    for e in entries:
        fields = {k: v for k, v in e.items() if k not in ("key", "_id")}
        fields["id"] = e.pop("_id")
        fields["depends_on"] = [keymap.get(d, d) for d in deps_of(e)]
        fields.setdefault("labels", [])
        fields["rank"] = 0
        fields["status"] = new_status(doc, as_draft)
        fields["unlocks"] = []
        fields["handoff"] = []
        new_tickets.append(canonical(fields))
    existing_phases = {p.get("id") for p in doc.get("phases", []) if isinstance(p, dict)}
    new_phases = [p for p in (batch.get("phases") or []) if p.get("id") not in existing_phases]
    doc["phases"].extend(new_phases)
    doc["tickets"].extend(new_tickets)
    moved = place(doc, new_tickets, after, before)
    recompute_unlocks(doc)
    return new_phases, new_tickets, moved


def run_add(doc: Dict[str, Any], batch: Dict[str, Any], as_draft: bool, after: Optional[str],
            dry_run: bool, label: Any = None, source: Optional[str] = None, before: Optional[str] = None,
            post: Any = None) -> int:
    """post(doc, new_tickets) -> [report lines]: extra changes to existing tickets (new --fixes),
    applied before the whole board is validated."""
    errors, warnings = check_batch(doc, batch, as_draft=as_draft, label=label, source=source)
    if errors:
        if source:
            raise Refused("not added: fix these in the batch first:", errors)
        raise Refused("not added: the new ticket is missing things (nothing was saved):", errors,
                      fix=[] if as_draft else [f"add the flags listed below, or re-run {CMD} new ... with --draft to save it unfinished"])
    if after is not None and after not in by_id(doc):
        raise Refused(f"--after {after}: no such ticket", fix=unknown_id_fix(doc, after))
    new_phases, new_tickets, moved = build_batch(doc, batch, as_draft, after, before)
    extra: List[str] = post(doc, new_tickets) if post else []
    created_all = [t["id"] for t in new_tickets]
    created = [] if as_draft else created_all
    ok_errors, _ = validate(doc, created=created)
    blocked = write_blockers(ok_errors)
    if blocked:
        for issue in blocked[1]:
            if issue.where in created_all:
                issue.fix = batch_fix(source, issue.where, issue.field, as_draft)
        raise refuse_blocked(blocked, "not added: the board would be invalid:")
    print_warnings(warnings)
    if dry_run:
        atomic_write(PREVIEW, dumps({"preview": True, "phases": new_phases, "tickets": new_tickets}))
        print(f"Preview only, nothing saved. Wrote kanban/preview.json ({len(new_tickets)} ticket"
              f"{'s' if len(new_tickets) != 1 else ''}); open the board to look at it.")
    else:
        write_board(doc, ok_errors)
        remove_preview()
        print(f"Added {len(new_tickets)} ticket{'s' if len(new_tickets) != 1 else ''}:")
    for t in new_tickets:
        print(f"  {t['id']}  rank {t['rank']:>3}  {t['status']:<8} {t.get('phase', '')}  {t.get('title', '')}")
    for p in new_phases:
        print(f"  new phase {p['id']}: {p.get('name', '')}")
    if moved:
        print(f"  ({moved} existing ticket{'s' if moved != 1 else ''} moved down to make room)")
    for ln in extra:
        print("  " + ln)
    return 0


# --------------------------------------------------------------------------- show formatting


def wrap_md(text: str, indent: str = "  ") -> List[str]:
    """Wrap markdown-ish text for a terminal: paragraphs and list items wrap, fenced code,
    tables and indented blocks stay exactly as written."""
    out: List[str] = []
    fence = False
    for raw in str(text).splitlines():
        s = raw.rstrip()
        if s.lstrip().startswith("```"):
            fence = not fence
            out.append(indent + s)
            continue
        if fence or s.startswith(("    ", "\t")) or s.lstrip().startswith("|"):
            out.append(indent + s if s else "")
            continue
        if not s.strip():
            out.append("")
            continue
        m = re.match(r"^(\s*)([-*+]|\d+[.)])\s+", s)
        if m:
            lead = indent + m.group(1)
            bullet = m.group(2) + " "
            body = s[m.end():]
            out.extend(textwrap.wrap(body, WIDTH, initial_indent=lead + bullet,
                                     subsequent_indent=lead + " " * len(bullet),
                                     break_long_words=False, break_on_hyphens=False) or [lead + bullet])
        else:
            out.extend(textwrap.wrap(s.strip(), WIDTH, initial_indent=indent, subsequent_indent=indent,
                                     break_long_words=False, break_on_hyphens=False))
    while out and not out[-1]:
        out.pop()
    return out


def bullets(items: Iterable[str], indent: str = "  ", mark: str = "- ") -> List[str]:
    out: List[str] = []
    for it in items:
        out.extend(textwrap.wrap(" ".join(str(it).split()), WIDTH, initial_indent=indent + mark,
                                 subsequent_indent=indent + " " * len(mark),
                                 break_long_words=False, break_on_hyphens=False) or [indent + mark])
    return out


def show_text(doc: Dict[str, Any], t: Dict[str, Any]) -> str:
    ids = by_id(doc)
    phases = {p.get("id"): p for p in doc.get("phases", []) if isinstance(p, dict)}
    tid = t.get("id")
    lines: List[str] = [f"{tid} · {t.get('title', '')}"]
    ph = t.get("phase", "?")
    ph_name = phases.get(ph, {}).get("name")
    ph_bits = [str(ph_name)] if ph_name else []
    if phases.get(ph, {}).get("unscheduled") is True:
        ph_bits.append("unscheduled")
    bits = [f"Phase {ph}" + (f" ({', '.join(ph_bits)})" if ph_bits else ""), f"priority {t.get('priority', '?')}",
            f"estimate {t.get('estimate', '?')}", f"rank {t.get('rank', '?')}", f"status {status_text(t.get('status'))}"]
    lines.append(" · ".join(bits))
    extra = []
    if is_str_list(t.get("areas")) and t["areas"]:
        extra.append("Areas: " + ", ".join(t["areas"]))
    if is_str_list(t.get("labels")) and t["labels"]:
        extra.append("Labels: " + ", ".join(t["labels"]))
    if role(t.get("status")) == "draft":
        extra.append("DRAFT: not ready to work yet")
    if claim_of(t):
        extra.append(f"On: {t['claimed_by']['by']} since {t['claimed_by'].get('since', '?')}")
    if workflow_name(doc) != "free":
        extra.append(f"Workflow: {workflow_name(doc)}")
    if extra:
        lines.append(" · ".join(extra))

    def section(title: str, body: List[str]) -> None:
        if body:
            lines.append("")
            lines.append(title)
            lines.extend(body)

    legacy = is_legacy(t)
    if legacy and present(t, "description"):
        section("Details", wrap_md(t["description"]))
    if present(t, "summary"):
        section("Summary", wrap_md(t["summary"]))
    if present(t, "story"):
        section("Story", wrap_md(t["story"]))
    if present(t, "visual"):
        section("Picture", ["  " + ln if ln.strip() else "" for ln in str(t["visual"]).rstrip().splitlines()])
    if is_str_list(t.get("acceptance")) and t["acceptance"]:
        section("Done when", checklist(t, "acceptance"))
    uts = user_tests_of(t)
    if uts:
        body: List[str] = []
        for j, u in enumerate(uts):
            if j:
                body.append("")
            req = "required" if u.get("required") is True else "optional"
            body.extend(textwrap.wrap(f"Test {j + 1} ({req}): {u.get('title', '')}", WIDTH,
                                      initial_indent="  ", subsequent_indent="    "))
            if present(u, "setup"):
                body.extend(textwrap.wrap(str(u["setup"]), WIDTH, initial_indent="    Before you start: ",
                                          subsequent_indent="      "))
            steps = u.get("steps") if is_str_list(u.get("steps")) else []
            if steps:
                body.append("    Steps:")
                for n, st in enumerate(steps, 1):
                    body.extend(textwrap.wrap(" ".join(st.split()), WIDTH, initial_indent=f"      {n}. ",
                                              subsequent_indent=" " * (len(str(n)) + 8)))
            if present(u, "expect"):
                body.extend(textwrap.wrap(str(u["expect"]), WIDTH, initial_indent="    You should see: ",
                                          subsequent_indent="      "))
            c = checks_of(t).get(str(j))
            if isinstance(c, dict) and c.get("result"):
                rec = f"    Result: {c['result']}"
                if c.get("date"):
                    rec += f" on {c['date']}"
                if c.get("note"):
                    rec += f" ({c['note']})"
                body.extend(textwrap.wrap(rec, WIDTH, subsequent_indent="      "))
            else:
                body.append("    Result: not tried yet")
        body.append("")
        body.append("  Record a result with (index 0 is Test 1, index 1 is Test 2, ...):")
        body.append(f"    {CMD} usertest {tid} INDEX pass|fail --note \"...\"")
        section("Try it yourself", body)
    if is_str_list(t.get("test_scenarios")) and t["test_scenarios"]:
        section("Automated tests", checklist(t, "test"))
    if not legacy and present(t, "description"):
        section("Details", wrap_md(t["description"]))
    if present(t, "technical"):
        section("Technical notes", wrap_md(t["technical"]))
    deps = deps_of(t)
    unlocks = t.get("unlocks") if is_str_list(t.get("unlocks")) else []
    nu: List[str] = []
    if deps:
        nu.extend(textwrap.wrap("Needs: " + ", ".join(
            f"{d} ({ids[d].get('status')})" if d in ids else f"{d} (missing)" for d in deps), WIDTH,
            initial_indent="  ", subsequent_indent="    "))
    else:
        nu.append("  Needs: nothing")
    nu.extend(textwrap.wrap("Unlocks: " + (", ".join(unlocks) if unlocks else "nothing"), WIDTH,
                            initial_indent="  ", subsequent_indent="    "))
    section("Needs / unlocks", nu)
    if present(t, "plan_doc"):
        section("Plan doc", ["  " + str(t["plan_doc"])])
    section("Code changes", code_lines(t))
    handoff = [h for h in t.get("handoff", []) if isinstance(h, dict)] if isinstance(t.get("handoff"), list) else []
    if handoff:
        hb: List[str] = []
        for h in handoff:
            head = f"{h.get('date', '?')} · {h.get('status', '?')}: "
            hb.extend(textwrap.wrap(head + " ".join(str(h.get("note", "")).split()), WIDTH,
                                    initial_indent="  ", subsequent_indent="    ",
                                    break_long_words=False, break_on_hyphens=False))
        section("History", hb)
    return "\n".join(lines)


def checklist(t: Dict[str, Any], kind: str) -> List[str]:
    """[x] for a ticked item (with its evidence) and for every item of a done ticket, else [ ]."""
    done = role(t.get("status")) == "done"
    ic = item_checks_of(t)
    out: List[str] = []
    for j, item in enumerate(t[ITEM_KINDS[kind]]):
        c = ic.get(f"{kind}:{j}")
        out.extend(bullets([item], mark="[x] " if done or isinstance(c, dict) else "[ ] "))
        if isinstance(c, dict):
            txt = "checked" + (f" {c['date']}" if isinstance(c.get("date"), str) else "")
            if isinstance(c.get("evidence"), str) and c["evidence"].strip():
                txt += ": " + " ".join(c["evidence"].split())
            out.extend(textwrap.wrap(txt, WIDTH, initial_indent="      ", subsequent_indent="        ",
                                     break_long_words=False, break_on_hyphens=False))
    return out


def code_lines(t: Dict[str, Any]) -> List[str]:
    out: List[str] = []
    pr = t.get("pr")
    if isinstance(pr, dict) and pr.get("url"):
        out.append(f"  PR: {pr['url']} ({pr.get('state', '?')})")
        if isinstance(pr.get("title"), str) and pr["title"].strip():
            out.extend(textwrap.wrap(pr["title"], WIDTH, initial_indent="    ", subsequent_indent="    "))
    cs = t.get("commits")
    for c in cs if isinstance(cs, list) else []:
        if not isinstance(c, dict):
            continue
        text = f"{str(c.get('sha', ''))[:7]} {' '.join(str(c.get('message', '')).split())}".rstrip()
        text += f" ({c.get('date', '?')})"
        out.extend(textwrap.wrap(text, WIDTH, initial_indent="  ", subsequent_indent="          ",
                                 break_long_words=False, break_on_hyphens=False))
    dw = t.get("done_without")
    if isinstance(dw, dict):
        for key, label in (("code", "Closed without code"), ("pr", "Closed without a PR")):
            if isinstance(dw.get(key), str):
                out.extend(textwrap.wrap(f"{label}: {dw[key]}", WIDTH, initial_indent="  ",
                                         subsequent_indent="    "))
    return out


def print_warnings(warnings: Sequence[Issue]) -> None:
    for w in warnings:
        print(f"warning: {w}")
        for ln in fix_lines(w.fix):
            print(ln)


def print_issues(errors: Sequence[Issue], warnings: Sequence[Issue]) -> None:
    for e in errors:
        print(f"error: {e}", file=sys.stderr)
        for ln in fix_lines(e.fix):
            print(ln, file=sys.stderr)
    print_warnings(warnings)


# --------------------------------------------------------------------------- versions


def file_versions() -> Tuple[bool, Optional[str], Optional[int]]:
    if not TICKETS.exists():
        return False, None, None
    try:
        doc = json.loads(TICKETS.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return True, None, None
    m = meta_of(doc)
    sv = m.get("slate_version")
    sc = m.get("schema_version")
    return True, (sv if isinstance(sv, str) else None), (sc if is_int(sc) else None)


def plugin_version(root: str) -> str:
    path = Path(root) / ".claude-plugin" / "plugin.json"
    data = read_json(path, "plugin.json")
    v = data.get("version") if isinstance(data, dict) else None
    if not isinstance(v, str) or not v.strip():
        raise Refused(f"{path}: no \"version\" in plugin.json",
                      fix=[ASK + "the Slate plugin install looks broken (plugin.json has no version); "
                                 "can you reinstall or update the Slate plugin?"])
    return v


def relation(plugin: str) -> str:
    """same / behind (project older than plugin) / ahead (project newer than plugin)."""
    exists, fsv, fsc = file_versions()
    pv = vtuple(plugin)
    if vtuple(SLATE_VERSION) > pv or (fsv is not None and vtuple(fsv) > pv) \
            or (fsc is not None and fsc > SCHEMA_VERSION):
        return "ahead"
    if vtuple(SLATE_VERSION) < pv:
        return "behind"
    if exists and (fsv is None or vtuple(fsv) < pv or fsc is None or fsc < SCHEMA_VERSION):
        return "behind"
    return "same"


# --------------------------------------------------------------------------- commands


def cmd_init(a: argparse.Namespace) -> int:
    if TICKETS.exists():
        raise Refused("kanban/tickets.json already exists; init never overwrites it",
                      fix=[f"{CMD} status   (the board is already set up; use it)",
                           f"{CMD} set-meta project=" + shlex.quote("New name") + "   (to rename the project)"])
    project = (a.project or "").strip()
    pfx = a.prefix if PREFIX_RE.match(a.prefix or "") else "ACME"
    if not project:
        raise Refused("meta project: --project must not be empty",
                      fix=[f"{CMD} init --project " + shlex.quote("Project name") + f" --prefix {pfx}"])
    if not PREFIX_RE.match(a.prefix or ""):
        guess = re.sub(r"[^A-Z0-9]", "", (a.prefix or project).upper()).lstrip("0123456789")[:10]
        guess = guess if PREFIX_RE.match(guess) else "ACME"
        raise Refused(f"meta prefix: '{a.prefix}' must be 2-10 capital letters or digits, "
                      "starting with a letter (for example ACME)",
                      fix=[f"{CMD} init --project {shlex.quote(project or 'Project name')} --prefix {guess}"])
    areas = parse_csv(a.areas) or list(DEFAULT_AREAS)
    repo_url = clean_repo_url(a.repo_url) if a.repo_url is not None else None
    doc = {
        "meta": {
            "project": project,
            "prefix": a.prefix,
            **({"repo_url": repo_url} if repo_url else {}),
            "slate_version": SLATE_VERSION,
            "schema_version": SCHEMA_VERSION,
            "generated": today(),
            "statuses": list(DEFAULT_STATUSES),
            "areas": areas,
            "priorities": list(DEFAULT_PRIORITIES),
            "user_test_areas": list(DEFAULT_USER_TEST_AREAS),
        },
        "phases": [],
        "tickets": [],
    }
    commit(doc)
    print(f"Created kanban/tickets.json for {project} (prefix {a.prefix}, areas {', '.join(areas)}).")
    return 0


def cmd_version(a: argparse.Namespace) -> int:
    exists, fsv, fsc = file_versions()
    plugin = plugin_version(a.against) if a.against else None
    rel = relation(plugin) if plugin else None
    if a.json:
        print(json.dumps({"board": SLATE_VERSION, "schema": SCHEMA_VERSION, "file_slate_version": fsv,
                          "file_schema_version": fsc, "plugin": plugin, "relation": rel}, indent=2))
        return 0
    if exists:
        ftxt = f"tickets.json {fsv or '-'}/{fsc if fsc is not None else '-'}"
    else:
        ftxt = "tickets.json missing"
    out = f"board {SLATE_VERSION} · schema {SCHEMA_VERSION} · {ftxt}"
    if plugin:
        out += f" · plugin {plugin} · {rel}"
    print(out)
    return 0


def cmd_next(a: argparse.Namespace) -> int:
    if not TICKETS.exists():
        return 0
    if a.brief:
        return next_brief(a)
    doc = read_board()
    ts = tickets_of(doc)
    me = whoami(a.as_)
    in_flight = by_rank(t for t in ts if role(t.get("status")) in ("in_progress", "review"))
    open_ = [t for t in in_flight if not claimed_elsewhere(t, me)]
    elsewhere = [t for t in in_flight if claimed_elsewhere(t, me)]
    waiting = by_rank(t for t in ts if role(t.get("status")) == "user_testing")
    merging = by_rank(t for t in ts if role(t.get("status")) == "merge_ready")
    ready = [t for t in ready_sorted(doc) if not claimed_elsewhere(t, me)]
    if a.json:
        out: Dict[str, Any] = {"open": [brief(t) for t in open_], "user_testing": [brief(t) for t in waiting],
                               "merge_ready": [brief(t) for t in merging],
                               "elsewhere": [dict(brief(t), claimed_by=t.get("claimed_by")) for t in elsewhere],
                               "next": brief(ready[0]) if ready else None, "me": me}
        if a.against:
            try:
                out["relation"] = relation(plugin_version(a.against))
            except Refused:
                out["relation"] = None
        print(json.dumps(out, indent=2, ensure_ascii=False))
        return 0
    if open_:
        print("Resume first (already started):")
        for t in open_:
            print("  " + line_on(t))
        print()
    if elsewhere:
        print(f"Being worked on elsewhere (not by {me}; leave them):")
        for t in elsewhere:
            print("  " + line_on(t))
        print()
    if waiting:
        print("Waiting for you to test:")
        for t in waiting:
            print("  " + line_on(t))
        print()
    if merging:
        print("Waiting for merge (the PR needs merging; then: link ID --pr-state merged, set ID done):")
        for t in merging:
            pr = t.get("pr") if isinstance(t.get("pr"), dict) else {}
            print("  " + line(t) + (f"  {pr['url']}" if isinstance(pr.get("url"), str) else ""))
        print()
    if not ready:
        if not ts:
            print(f"No tickets yet. Plan some with /slate:plan or {CMD} new.")
        elif all(role(t.get("status")) == "done" for t in ts):
            print("Every ticket is done.")
        else:
            print(f"No ready tickets. Run `{CMD} status` to see what is blocking.")
        return 0
    print("Next ticket:")
    print("  " + line_on(ready[0]))
    print(f"\nRun: {CMD} show {ready[0]['id']}")
    return 0


def next_brief(a: argparse.Namespace) -> int:
    head = f"Slate {SLATE_VERSION}: "
    try:
        doc = read_board()
    except Refused:
        print(head + f"kanban/tickets.json can't be read; run {CMD} check")
        return 0
    ts = tickets_of(doc)
    parts: List[str] = []
    me = whoami(None)
    in_flight = by_rank(t for t in ts if role(t.get("status")) in ("in_progress", "review"))
    open_ = [t for t in in_flight if not claimed_elsewhere(t, me)]
    n_elsewhere = len(in_flight) - len(open_)
    for t in open_[:3]:
        parts.append(f"{t.get('id')} {'in review' if role(t.get('status')) == 'review' else 'in progress'}")
    if len(open_) > 3:
        parts.append(f"+{len(open_) - 3} more in flight")
    if n_elsewhere:
        parts.append(f"{n_elsewhere} being worked on elsewhere")
    waiting = [t for t in ts if role(t.get("status")) == "user_testing"]
    if waiting:
        parts.append(f"{len(waiting)} waiting for you to test")
    merging = [t for t in ts if role(t.get("status")) == "merge_ready"]
    if merging:
        parts.append(f"{len(merging)} waiting for merge")
    ready = [t for t in ready_sorted(doc) if not claimed_elsewhere(t, me)]
    if ready:
        parts.append(f"next ready {ready[0]['id']}")
    elif not ts:
        parts.append("no tickets yet, run /slate:plan")
    elif all(role(t.get("status")) == "done" for t in ts):
        parts.append("every ticket is done")
    else:
        parts.append("nothing ready")
    errors, _ = validate(doc)
    if errors:
        parts.append(f"board has {len(errors)} error{'s' if len(errors) != 1 else ''}, run {CMD} check")
    live = running_server()
    if live:
        parts.append(f"board page live at {live['url']}")
    if a.against:
        try:
            rel = relation(plugin_version(a.against))
        except Refused:
            rel = None
        if rel == "behind":
            parts.append("board behind plugin, run /slate:upgrade")
        elif rel == "ahead":
            parts.append("board newer than plugin, update the Slate plugin")
        try:  # the SessionStart line also carries doctor's findings (local checks only, no network)
            probs = [p for p in doctor_problems(a.against, doc)
                     if not p.get("info") and
                     p["code"] not in ("board-unreadable", "board-errors", "board-files-outdated", "plugin-outdated",
                                       "schema-outdated")]  # already said above
            if probs:
                parts.append(doctor_brief(probs, prefix=""))
        except Exception:
            pass
    print(head + " · ".join(parts))
    return 0


def add_filter_args(s: argparse.ArgumentParser) -> None:
    """--phase --status --label --area: repeatable, comma lists allowed; OR within a flag, AND across."""
    s.add_argument("--phase", action="append", metavar="P[,P]", help="only these phases")
    s.add_argument("--status", action="append", metavar="S[,S]", help="only these statuses")
    s.add_argument("--label", action="append", metavar="L[,L]", help="only tickets with one of these labels")
    s.add_argument("--area", action="append", metavar="A[,A]", help="only tickets in one of these areas")


def filter_tickets(doc: Dict[str, Any], a: argparse.Namespace, tickets: Iterable[Dict[str, Any]],
                   cmd: str) -> List[Dict[str, Any]]:
    """Apply the filter flags; unknown phases / statuses are refused (labels and areas are free text)."""
    phases = parse_multi(getattr(a, "phase", None))
    statuses = parse_multi(getattr(a, "status", None))
    labels = parse_multi(getattr(a, "label", None))
    areas = parse_multi(getattr(a, "area", None))
    known_phases = [str(p.get("id")) for p in phases_of(doc)]
    for ph in phases:
        if ph not in known_phases:
            close = get_close_matches(ph, known_phases, n=1)
            raise Refused(f"phase {ph} id: no such phase (phases: {', '.join(known_phases) or 'none yet'})",
                          fix=[f"{CMD} {cmd} --phase {close[0] if close else (known_phases[0] if known_phases else 'P1')}"
                               + ("   (did you mean this?)" if close else ""), f"{CMD} status   (lists the phases)"])
    known_statuses = statuses_of(doc)
    for st in statuses:
        if st not in known_statuses:
            close = get_close_matches(st, known_statuses, n=1)
            raise Refused(f"status {st}: not one of meta.statuses ({', '.join(known_statuses)})",
                          fix=[f"{CMD} {cmd} --status {close[0] if close else 'STATUS'}"
                               + ("   (did you mean this?)" if close else
                                  f"   (STATUS one of: {', '.join(known_statuses)})")])
    out: List[Dict[str, Any]] = []
    for t in tickets:
        if phases and t.get("phase") not in phases:
            continue
        if statuses and t.get("status") not in statuses:
            continue
        tl = t.get("labels") if is_str_list(t.get("labels")) else []
        if labels and not any(x in tl for x in labels):
            continue
        ta = t.get("areas") if is_str_list(t.get("areas")) else []
        if areas and not any(x in ta for x in areas):
            continue
        out.append(t)
    return out


def cmd_list(a: argparse.Namespace) -> int:
    if a.n < 0:
        raise UsageError("list: N must be 0 or more", fix=[f"{CMD} list 5"])
    doc = read_board()
    me = whoami(a.as_)
    ready = filter_tickets(doc, a, [t for t in ready_sorted(doc) if not claimed_elsewhere(t, me)], "list")[: a.n]
    if a.json:
        print(json.dumps([brief(t) for t in ready], indent=2, ensure_ascii=False))
        return 0
    if not ready:
        print("No ready tickets.")
    for t in ready:
        print(line_on(t))
    return 0


def cmd_export(a: argparse.Namespace) -> int:
    doc = read_board()
    ts = filter_tickets(doc, a, by_rank(tickets_of(doc)), "export --json")
    if a.statuses:
        print(json.dumps(status_setup(doc), indent=2, ensure_ascii=False))
        return 0
    wanted = parse_multi(a.status)
    if not a.drafts:
        ts = [t for t in ts if role(t.get("status")) != "draft" or t.get("status") in wanted]
    if LABEL_OF:
        ts = [dict(t, status_label=slabel(t.get("status"))) for t in ts]
    if a.removed:
        print(json.dumps([x for x in meta_of(doc).get("removed", []) if isinstance(x, dict)], indent=2,
                         ensure_ascii=False))
        return 0
    print(json.dumps(ts, indent=2, ensure_ascii=False))
    return 0


def cmd_show(a: argparse.Namespace) -> int:
    doc = read_board()
    t = find(doc, a.id)
    if a.json:
        print(json.dumps(t, indent=2, ensure_ascii=False))
    else:
        print(show_text(doc, t))
    return 0


def cmd_status(a: argparse.Namespace) -> int:
    doc = read_board()
    ts = filter_tickets(doc, a, tickets_of(doc), "status")
    statuses = statuses_of(doc)
    counts = {s: 0 for s in statuses}
    for t in ts:
        s = str(t.get("status"))
        counts[s] = counts.get(s, 0) + 1
    later = unscheduled_ids(doc)
    only = parse_multi(a.phase)
    phases = []
    for p in phases_display_order(doc):
        if only and p.get("id") not in only:
            continue
        pts = [t for t in ts if t.get("phase") == p.get("id")]
        row = {"id": p.get("id"), "name": p.get("name", ""), "total": len(pts),
               "done": sum(role(t.get("status")) == "done" for t in pts),
               "in_flight": sum(role(t.get("status")) in OPEN_STATUSES for t in pts)}
        if p.get("unscheduled") is True:
            row["unscheduled"] = True
        phases.append(row)
    waiting = by_rank(t for t in ts if role(t.get("status")) == "user_testing")
    merging = by_rank(t for t in ts if role(t.get("status")) == "merge_ready")
    drafts = by_rank(t for t in ts if role(t.get("status")) == "draft")
    n_later = sum(t.get("phase") in later for t in ts)
    claims = [t for t in by_rank(ts) if claim_of(t)]
    unlock_lines = unlock_state()
    if a.json:
        print(json.dumps({"project": meta_of(doc).get("project"), "total": len(ts), "phases": phases,
                          "counts": counts, "user_testing": [brief(t) for t in waiting],
                          "merge_ready": [brief(t) for t in merging],
                          "drafts": [{"id": t.get("id"), "title": t.get("title")} for t in drafts],
                          "unscheduled": n_later,
                          "claims": [{"id": t.get("id"), "status": t.get("status"), **t["claimed_by"]} for t in claims],
                          "unlock": unlock_lines},
                         indent=2, ensure_ascii=False))
        return 0
    print(f"{meta_of(doc).get('project', 'Board')} · {len(ts)} ticket{'s' if len(ts) != 1 else ''}")
    if phases:
        print("\nPhases")
        labels = [f"{p['id']} {p['name']}" + (" (unscheduled)" if p.get("unscheduled") else "") for p in phases]
        w = max(len(x) for x in labels)
        for p, label in zip(phases, labels):
            print(f"  {label:<{w}}  {p['done']:>2}/{p['total']:<2} done · {p['in_flight']} in flight")
    print("\nStatuses" + (f" (workflow: {workflow_name(doc)})" if workflow_name(doc) != "free" else ""))
    print("  " + " · ".join(f"{slabel(s)} {n}" for s, n in counts.items()))
    print("\nWaiting for you to test")
    if waiting:
        for t in waiting:
            print(f"  {t.get('id')}  {t.get('title', '')}")
    else:
        print("  nothing")
    print("\nWaiting for merge")
    if merging:
        for t in merging:
            pr = t.get("pr") if isinstance(t.get("pr"), dict) else {}
            print(f"  {t.get('id')}  {t.get('title', '')}"
                  + (f"  ({pr['url']}, {pr.get('state')})" if isinstance(pr.get("url"), str) else ""))
    else:
        print("  nothing")
    print("\nDrafts (not ready to work)")
    if drafts:
        for t in drafts:
            print(f"  {t.get('id')}  {t.get('title', '')}")
    else:
        print("  nothing")
    if claims:
        print("\nClaimed (who is on what)")
        for t in claims:
            c = t["claimed_by"]
            print(f"  {t.get('id')}  on: {c.get('by')} since {c.get('since')}  ({t.get('status')})")
    if n_later:
        print(f"\nUnscheduled: {n_later} ticket{'s' if n_later != 1 else ''} in unscheduled phases "
              "(next and list skip them)")
    print_unlock_warnings(unlock_lines)
    return 0


def cmd_check(a: argparse.Namespace) -> int:
    doc = read_board()
    errors, warnings = validate(doc)
    quiet = bool(a.quiet_optional) or meta_of(doc).get("check_quiet_optional") is True
    hidden = [w for w in warnings if w.optional] if quiet else []
    if quiet:
        warnings = [w for w in warnings if not w.optional]
    unlock_lines = unlock_state()
    if a.json:
        print(json.dumps({"ok": not errors, "errors": [e.as_dict() for e in errors],
                          "warnings": [w.as_dict() for w in warnings], "optional_hidden": len(hidden),
                          "unlock": unlock_lines},
                         indent=2, ensure_ascii=False))
        return 1 if errors else 0
    print_issues(errors, warnings)
    print_unlock_warnings(unlock_lines)
    n = len(tickets_of(doc))
    summary = (f"{len(errors)} error{'s' if len(errors) != 1 else ''}, "
               f"{len(warnings)} warning{'s' if len(warnings) != 1 else ''} ({n} tickets)")
    if errors:
        print(f"not ok: {summary}", file=sys.stderr)
        code = 1
    else:
        print(f"ok: {summary}")
        code = 0
    if hidden:
        print(f"{len(hidden)} optional warning{'s' if len(hidden) != 1 else ''} hidden "
              "(missing visual or technical notes)")
    return code


def parse_json_arg(flag: str, text: str) -> Any:
    try:
        return json.loads(text)
    except json.JSONDecodeError as e:
        raise UsageError(f"{flag}: not valid JSON ({e.msg} at column {e.colno})",
                         fix=[f"wrap the JSON in single quotes and use double quotes inside, e.g. "
                              f"{flag.rstrip('=').rstrip(':')}:='[\"a\", \"b\"]'" if flag.endswith(":=")
                              else f"wrap the JSON in single quotes and use double quotes inside, e.g. "
                                   f"{flag} '{{\"title\": \"...\"}}'"])


def rerun_with(extra: str) -> str:
    """This command again with `extra` appended (for "re-run with ..." hints)."""
    return f"{CMD} {shlex.join(RAW_ARGV)} {extra}".replace("  ", " ")


def cmd_new(a: argparse.Namespace) -> int:
    fixes = parse_multi(a.fixes)
    if fixes and a.after:
        raise UsageError("new: --fixes already places the ticket (right before the earliest ticket it fixes), "
                         "so it can't go with --after", fix=[f"re-run {CMD} new ... without --after"])
    if a.reopen and not fixes:
        raise UsageError("new: --reopen only goes with --fixes ID", fix=[f"re-run {CMD} new ... without --reopen"])
    doc = load_for_write()
    prefix = meta_of(doc)["prefix"]
    new_id = make_id(prefix, next_number(doc, prefix))
    ids = by_id(doc)
    for f in fixes:
        if f not in ids:
            raise Refused(f"{f} id: no such ticket (named in --fixes)", fix=unknown_id_fix(doc, f))
    finished = [f for f in fixes if role(ids[f].get("status")) in FINISHED]
    if finished and not a.reopen:
        them = "it" if len(finished) == 1 else "them"
        state = (f"is {ids[finished[0]].get('status')}" if len(finished) == 1 else
                 "; ".join(f"{f} is {ids[f].get('status')}" for f in finished))
        raise Refused(f"{finished[0]} status: {state}, so a bug that fixes {them} means reopening {them}",
                      fix=[ASK + f"a bug in {', '.join(finished)}: reopen {them} (back to in_progress) until "
                                 f"{new_id} is fixed? If yes: {rerun_with('--reopen')}",
                           ASK + f"or should {new_id} be a separate ticket that doesn't reopen {them}? "
                                 f"Then re-run without --fixes {' '.join(finished)} (keep --bug)"])
    labels = parse_multi(a.labels)
    if a.bug or fixes:
        labels = list(dict.fromkeys(labels + ["bug"] + [f"fixes-{f}" for f in fixes]))
    entry: Dict[str, Any] = {"key": new_id, "title": a.title, "summary": a.summary}
    for flag, field in (("story", "story"), ("visual", "visual"), ("description", "description")):
        v = getattr(a, flag)
        if v is not None:
            entry[field] = v
    if a.acceptance:
        entry["acceptance"] = list(a.acceptance)
    elif not a.draft:
        entry["acceptance"] = []
    if a.test:
        entry["test_scenarios"] = list(a.test)
    elif not a.draft:
        entry["test_scenarios"] = []
    if a.user_test_json:
        entry["user_tests"] = [parse_json_arg("--user-test-json", u) for u in a.user_test_json]
    if a.technical is not None:
        entry["technical"] = a.technical
    if a.plan_doc is not None:
        entry["plan_doc"] = a.plan_doc
    entry["phase"] = a.phase
    entry["areas"] = parse_multi(a.areas)
    entry["priority"] = a.priority
    entry["depends_on"] = parse_multi(a.depends)
    entry["estimate"] = a.estimate
    entry["labels"] = labels
    batch = {"tickets": [entry]}
    before = by_rank(ids[f] for f in fixes)[0]["id"] if fixes else None

    def post(d: Dict[str, Any], new_tickets: List[Dict[str, Any]]) -> List[str]:
        nid = new_tickets[0]["id"]
        cur = by_id(d)
        out: List[str] = []
        for f in fixes:
            ft = cur[f]
            deps = deps_of(ft)
            if nid not in deps:
                ordered_set(ft, "depends_on", deps + [nid])
            out.append(f"{f} now waits for {nid}")
            if role(ft.get("status")) in FINISHED:
                was = ft["status"]
                ft["status"] = status_for_role(d, "in_progress") or was
                h = ft.get("handoff") if isinstance(ft.get("handoff"), list) else []
                h.append(handoff_entry(ft["status"], f"Reopened (was {was}): bug {nid} '{short(a.title, 60)}' fixes it"))
                ordered_set(ft, "handoff", h)
                out.append(f"{f} reopened: {was} -> {ft['status']}")
        recompute_unlocks(d)
        return out

    return run_add(doc, batch, as_draft=a.draft, after=a.after, dry_run=a.dry_run,
                   label=lambda i, t: new_id, before=before, post=post if fixes else None)


def cmd_add(a: argparse.Namespace) -> int:
    doc = load_for_write()
    batch = load_batch(a.file)
    if not batch["tickets"]:
        raise Refused(f"batch file {a.file}: has no tickets",
                      fix=[f"put at least one ticket in the \"tickets\" list of {a.file}, then run: "
                           f"{CMD} batch-check --file {a.file}"])
    return run_add(doc, batch, as_draft=a.as_draft, after=a.after, dry_run=a.dry_run, source=a.file)


def cmd_batch_check(a: argparse.Namespace) -> int:
    batch = load_batch(a.file)
    doc: Optional[Dict[str, Any]] = None
    if TICKETS.exists():
        doc = read_board()
    errors, warnings = check_batch(doc, batch, as_draft=a.as_draft, source=a.file)
    if a.json:
        print(json.dumps({"ok": not errors, "errors": [e.as_dict() for e in errors],
                          "warnings": [w.as_dict() for w in warnings]}, indent=2, ensure_ascii=False))
        return 1 if errors else 0
    print_issues(errors, warnings)
    n = len(batch["tickets"])
    summary = f"{len(errors)} errors, {len(warnings)} warnings ({n} batch tickets)"
    if errors:
        print(f"not ok: {summary}", file=sys.stderr)
        return 1
    print(f"ok: {summary}")
    return 0


def cmd_discard_preview(a: argparse.Namespace) -> int:
    print("Removed kanban/preview.json." if remove_preview() else "No preview to discard.")
    return 0


def done_code_check(tid: str, t: Dict[str, Any], note: str, no_code: Optional[str],
                    no_pr: Optional[str], status: str = "done") -> List[str]:
    """Rules for moving to done or merge_ready: commits linked (and present in git), PR set when there
    is a remote. Returns warnings; raises Refused on a missing commit / sha / PR."""
    if no_code is not None:
        return []
    root_s = git(["rev-parse", "--show-toplevel"], HERE)
    if root_s is None:
        return ["git isn't available here (or this isn't a git repository), so linked commits and the "
                "pull request weren't checked"]
    root = Path(root_s)
    again = f"{CMD} set {tid} {status} --handoff {shlex.quote(note)}"
    can_t = "it can't be done" if role(status) == "done" else f"it can't move to {status}"
    commits = [c for c in t.get("commits", []) if isinstance(c, dict)] if isinstance(t.get("commits"), list) else []
    if not commits:
        fix = [f"{CMD} link {tid} --commit HEAD   (then: {again})"]
        if role(status) == "done":
            fix.append(ASK + f"was anything coded for {tid}? If not, with their OK: {again} --no-code \"why\"")
        else:
            fix.append(ASK + f"was anything coded for {tid}? If not, with their OK close it instead: "
                             f"{CMD} set {tid} done --handoff {shlex.quote(note)} --no-code \"why\"")
        raise Refused(f"{tid} commits: has no commits linked, so {can_t}", fix=fix)
    missing = [str(c.get("sha")) for c in commits
               if git(["cat-file", "-e", f"{c.get('sha')}^{{commit}}"], root) is None]
    if missing:
        raise Refused(f"{tid} commits: {', '.join(m[:12] for m in missing)} "
                      f"{'is' if len(missing) == 1 else 'are'} not a commit in this git repository",
                      fix=["git log --oneline -10   (find the right commit)",
                           f"{CMD} link {tid} --commit SHA   (then: {again})",
                           ASK + f"is {', '.join(m[:12] for m in missing)} on another clone or branch that "
                                 "needs fetching (git fetch), or was it linked by mistake?"])
    if no_pr is None and git(["remote"], root) and not isinstance(t.get("pr"), dict):
        state = "merged" if role(status) == "done" else "open"
        raise Refused(f"{tid} pr: no pull request linked, and this repo has a git remote",
                      fix=[f"{CMD} link {tid} --pr URL --pr-state {state}   (then: {again})",
                           ASK + f"is there a pull request for {tid}? If not, with their OK: {again} --no-pr \"why\""])
    return []


def set_status(doc: Dict[str, Any], tid: str, status: str, handoff: Optional[str],
               no_code: Optional[str] = None, no_pr: Optional[str] = None, ignore_deps: Optional[str] = None,
               save: bool = True, me: Optional[str] = None,
               take_over: Optional[str] = None, path: bool = True) -> Tuple[Dict[str, Any], List[str]]:
    """Move one ticket (in doc). Validates the whole board; writes it when save. Returns (ticket, warnings).
    me: who is doing it (for claims); take_over: reason to take a ticket claimed by someone else."""
    ids = by_id(doc)
    t = find(doc, tid)
    statuses = statuses_of(doc)
    r = role(status)
    other = claimed_elsewhere(t, me) if me else None
    if take_over is not None and not take_over.strip():
        raise Refused(f"{tid} claimed_by: --take-over needs a reason",
                      fix=[f"{CMD} set {tid} {status} --take-over \"why you are taking it over\""])
    if other and take_over is None and r != "done":  # done is gated by the merged PR instead
        c = t["claimed_by"]
        raise Refused(f"{tid} claimed_by: being worked on by {other} (since {c.get('since', '?')}), not by {me}",
                      fix=[f"{CMD} next   (pick a ticket nobody is on)",
                           ASK + f"{tid} is claimed by {other}; should you take it over? If yes: "
                                 + rerun_with('--take-over "reason"'),
                           f"{CMD} set {tid} {status} --as {shlex.quote(other)} ...   (if you ARE {other}, "
                           "e.g. the same work on a renamed branch)"])
    if status not in statuses:
        if status in DEFAULT_STATUSES:
            fix = [f"{CMD} migrate   (this board is from an older Slate; migrate adds the {status} status)"]
        else:
            close = get_close_matches(status, statuses, n=1)
            fix = [f"{CMD} set {tid} {close[0] if close else 'STATUS'}"
                   + ("   (did you mean this?)" if close else f"   (STATUS one of: {', '.join(statuses)})")]
        raise Refused(f"{tid} status: '{status}' is not one of meta.statuses ({', '.join(statuses)})", fix=fix)
    note = (handoff or "").strip()
    hq = shlex.quote(note or "...")
    if path:
        check_path(doc, t, status, note)
    if ignore_deps is not None:
        if r in FINISHED:
            raise Refused(f"{tid} depends_on: --ignore-deps can't be used for {status}; "
                          f"{status} always needs every dependency done",
                          fix=[f"{CMD} show {tid}   (see which dependencies are open, and finish them first)",
                               f"{CMD} set {tid} {status} --handoff {hq}   (without --ignore-deps, once they are done)"])
        if r not in IGNORE_DEPS_OK:
            raise Refused(f"{tid} depends_on: --ignore-deps only goes with "
                          f"{', '.join(names_with_role(doc, IGNORE_DEPS_OK)) or ', '.join(IGNORE_DEPS_OK)}",
                          fix=[f"{CMD} set {tid} {status}" + (f" --handoff {hq}" if note else "")
                               + "   (without --ignore-deps)"])
        if not ignore_deps.strip():
            raise Refused(f"{tid} depends_on: --ignore-deps needs a reason",
                          fix=[f"{CMD} set {tid} {status}" + (f" --handoff {hq}" if note else "")
                               + " --ignore-deps \"why it can start before its dependencies are done\""])
    if note_required(doc, status) and not note:
        raise Refused(f"{tid} handoff: moving to {status} needs a note",
                      fix=[f"{CMD} set {tid} {status} --handoff \"what was built, what was verified, follow-ups\""])
    later = unscheduled_ids(doc)
    if r in SCHEDULED_ONLY and t.get("phase") in later:
        ph = t.get("phase")
        sched = [str(p.get("id")) for p in phases_of(doc) if p.get("id") not in later]
        fix = ([f"{CMD} edit {tid} phase={sched[0]}   (move it into a scheduled phase first; "
                f"scheduled: {', '.join(sched)})"] if sched else [])
        fix.append(f"{CMD} edit-phase {ph} unscheduled:=false   (or schedule the whole phase)")
        raise Refused(f"{tid} phase: {ph} is an unscheduled phase, so {tid} can't move to {status}", fix=fix)
    extra = ""
    if r in DEPS_GATED:
        blocked = [d for d in deps_of(t) if role(ids.get(d, {}).get("status")) != "done"]
        if blocked and ignore_deps is not None:
            extra = f"(deps open: {', '.join(blocked)} — {ignore_deps.strip()})"
        elif blocked:
            fix = [f"{CMD} show {blocked[0]}   (work on {blocked[0]} first)", f"{CMD} next",
                   ASK + f"should {tid} still wait for {', '.join(blocked)}? If not: "
                         f"{CMD} edit {tid} depends_on:={jq([d for d in deps_of(t) if d not in blocked])}"]
            if r in IGNORE_DEPS_OK:
                fix.append(ASK + f"can {tid} start while {', '.join(blocked)} {'is' if len(blocked) == 1 else 'are'} "
                                 f"still open (e.g. a stacked branch)? If yes: {CMD} set {tid} {status}"
                                 + (f" --handoff {hq}" if note else "") + " --ignore-deps \"reason\"")
            raise Refused(f"{tid} depends_on: can't move to {status} until these are done: " + ", ".join(
                f"{d} ({ids[d].get('status')})" if d in ids else f"{d} (missing)" for d in blocked), fix=fix)
    uts = user_tests_of(t)
    if r == "user_testing" and not uts:
        nxt = status_for_role(doc, "merge_ready", "done") or "done"
        raise Refused(f"{tid} user_tests: the ticket has no user tests, so there is nothing to try",
                      fix=[f"{CMD} edit {tid} user_tests:={jq(FIELD_EXAMPLE['user_tests'])}",
                           f"{CMD} set {tid} {nxt} --handoff {hq}   (if there is nothing to try by hand)"])
    if r in FINISHED:
        missing = [(j, u) for j, u in enumerate(uts) if u.get("required") is True and check_result(t, j) != "pass"]
        if missing:
            can_t = "can't be done" if r == "done" else f"can't move to {status}"
            testing = status_for_role(doc, "user_testing")
            raise Refused(f"{tid} user_checks: {can_t} until these required user tests pass: "
                          + ", ".join(f"{j} '{short(u.get('title', ''))}'" for j, u in missing),
                          fix=[ASK + f"did '{short(missing[0][1].get('title', ''))}' pass when you tried it?",
                               f"{CMD} usertest {tid} {missing[0][0]} pass   (only after the user says it passed)"]
                          + ([] if role(t.get("status")) == "user_testing" or not testing else
                             [f"{CMD} set {tid} {testing} --handoff \"how to try it\"   (hand it over for testing)"]))
    if no_code is not None and r != "done":
        raise Refused(f"{tid} status: --no-code only goes with done",
                      fix=[f"{CMD} set {tid} {status} --handoff {hq}   (without --no-code)"]
                      + ([f"{CMD} set {tid} {status_for_role(doc, 'done') or 'done'} --handoff {hq} "
                          f"--no-code {shlex.quote(no_code or 'why')}   (close it without code instead)"]
                         if r == "merge_ready" else []))
    if no_pr is not None and r not in FINISHED:
        raise Refused(f"{tid} status: --no-pr only goes with merge_ready or done",
                      fix=[f"{CMD} set {tid} {status} --handoff {hq}   (without --no-pr)"])
    for flag, v in (("--no-code", no_code), ("--no-pr", no_pr)):
        if v is not None and not v.strip():
            raise Refused(f"{tid} done_without: {flag} needs a reason",
                          fix=[f"{CMD} set {tid} {status} --handoff {hq} {flag} \"docs only\""])
    old_dw = t.get("done_without") if isinstance(t.get("done_without"), dict) else {}
    pr = t.get("pr") if isinstance(t.get("pr"), dict) else None
    if r == "done" and pr is not None and pr.get("state") != "merged" \
            and no_pr is None and no_code is None and "pr" not in old_dw:
        again = f"{CMD} set {tid} done --handoff {hq}"
        raise Refused(f"{tid} pr: the pull request is {pr.get('state')}, not merged, so {tid} can't be done",
                      fix=[f"{CMD} link {tid} --pr-state merged   (only once the PR really is merged; then: {again})",
                           ASK + f"is the PR for {tid} ({pr.get('url')}) merged? If it won't be merged, "
                                 f"with their OK: {again} --no-pr \"why\""])
    warnings: List[str] = []
    if r in FINISHED:
        effective_no_pr = no_pr if no_pr is not None else old_dw.get("pr")
        warnings = done_code_check(tid, t, note, no_code, effective_no_pr, status)
        dw: Dict[str, str] = {}
        if no_code is not None:
            dw["code"] = no_code.strip()
            note = f"{note} (no code: {dw['code']})".strip()
        elif no_pr is not None:
            dw["pr"] = no_pr.strip()
            note = f"{note} (no PR: {dw['pr']})".strip()
        if dw:
            ordered_set(t, "done_without", dw)
    if extra:
        note = f"{note} {extra}".strip()
    if other and take_over is not None:
        note = f"{note} (took over from {other}: {take_over.strip()})".strip()
    prev = t.get("status")
    t["status"] = status
    apply_claim(t, status, me, took_over=bool(other and take_over is not None))
    if note:
        h = t.get("handoff") if isinstance(t.get("handoff"), list) else []
        h.append(handoff_entry(status, note))
        ordered_set(t, "handoff", h)
    leaving_draft = role(prev) == "draft" and r != "draft"
    header = (f"{tid} can't leave draft until these are filled in:" if leaving_draft
              else "not saved: the change would leave the board invalid:")
    commit(doc, strict=[tid] if leaving_draft else [], header=header, write=save)
    return t, warnings


def split_ids(arg: str, cmd: str) -> List[str]:
    ids = list(dict.fromkeys(parse_csv(arg)))
    if not ids:
        raise UsageError(f"{cmd}: give a ticket id, or several separated by commas (ACME-001,ACME-002)",
                         fix=[f"{CMD} {cmd} ACME-001,ACME-002 ..."])
    return ids


def bulk(doc: Dict[str, Any], ids: Sequence[str], fn: Any, what: str) -> Tuple[Dict[str, Any], List[Any]]:
    """Apply fn(doc, tid) to every ticket on a copy of the board, one after the other. All or nothing:
    if any ticket is refused, every refusal is reported and nothing is written."""
    problems: List[Issue] = []
    refused = 0
    results: List[Any] = []
    for tid in ids:
        trial = copy.deepcopy(doc)
        try:
            res = fn(trial, tid)
        except Refused as e:
            refused += 1
            problems.append(Issue(e.message, "", "", e.fix))
            problems.extend(e.issues)
            continue
        doc = trial
        results.append(res)
    if problems:
        raise Refused(f"nothing was changed: {refused} of {len(ids)} tickets can't {what} "
                      "(all or nothing; fix these, then run the same command again):", problems)
    return doc, results


def cmd_set(a: argparse.Namespace) -> int:
    ids = split_ids(a.id, "set")
    doc = load_for_write()
    me = whoami(a.as_)
    if len(ids) == 1:
        t, warnings = set_status(doc, ids[0], a.status, a.handoff, no_code=a.no_code, no_pr=a.no_pr,
                                 ignore_deps=a.ignore_deps, me=me, take_over=a.take_over)
        print(line(t))
        for w in warnings:
            print(f"warning: {w}")
        return 0
    doc, results = bulk(doc, ids, lambda d, tid: set_status(d, tid, a.status, a.handoff, no_code=a.no_code,
                                                            no_pr=a.no_pr, ignore_deps=a.ignore_deps,
                                                            save=False, me=me, take_over=a.take_over)[1],
                        f"move to {a.status}")
    write_board(doc)
    ts = by_id(doc)
    for tid in ids:
        print(line(ts[tid]))
    for w in dict.fromkeys(w for ws in results for w in ws):
        print(f"warning: {w}")
    return 0


def cmd_promote(a: argparse.Namespace) -> int:
    doc = load_for_write()
    t = find(doc, a.id)
    if role(t.get("status")) != "draft":
        raise Refused(f"{a.id} status: is {t.get('status')}, not draft; nothing to promote",
                      fix=[f"{CMD} show {a.id}   (it is already out of draft)",
                           f"{CMD} set {a.id} STATUS --handoff \"...\"   (to change its status)"])
    target = status_for_role(doc, "backlog", "ready")
    if target is None:
        raise Refused("meta statuses: no status has the backlog or ready role, so a draft has nowhere to go",
                      fix=[f"{CMD} add-status backlog --after {statuses_of(doc)[0] if statuses_of(doc) else 'draft'} "
                           "--like backlog"])
    t, warnings = set_status(doc, a.id, target, a.handoff, me=whoami(None), path=False)
    print(line(t))
    for w in warnings:
        print(f"warning: {w}")
    later = unscheduled_ids(doc)
    if t.get("phase") in later:
        sched = [str(p.get("id")) for p in phases_of(doc) if p.get("id") not in later]
        print(f"note: {a.id} is in unscheduled phase {t.get('phase')}, so next and list won't offer it. "
              f"To schedule it: {CMD} edit {a.id} phase={sched[0] if sched else 'PHASE'}")
    return 0


def prune_item_checks(t: Dict[str, Any]) -> List[str]:
    """Drop ticks whose acceptance / test item no longer exists (after an edit shortened the list)."""
    ic = t.get("item_checks")
    if not isinstance(ic, dict):
        return []
    dropped: List[str] = []
    for k in list(ic):
        m = ITEM_KEY_RE.match(k)
        if not m:
            continue
        items = t.get(ITEM_KINDS[m.group(1)])
        if int(m.group(2)) >= (len(items) if isinstance(items, list) else 0):
            del ic[k]
            dropped.append(k)
    if not ic:
        t.pop("item_checks", None)
    return dropped


def rerank_after_deps(doc: Dict[str, Any], start: Sequence[str]) -> List[str]:
    """Move each ticket in start right after its latest dependency when it sits before it; tickets that
    depend on a moved ticket are checked in turn. Ranks become 1..n. Returns the ids that moved."""
    ids = by_id(doc)
    order = by_rank(tickets_of(doc))
    queue = list(start)
    moved: List[str] = []
    steps, limit = 0, len(order) ** 2 + 10  # a dependency cycle can't loop forever
    while queue and steps < limit:
        steps += 1
        t = ids.get(queue.pop(0))
        if t is None or role(t.get("status")) == "draft":
            continue
        deps = [ids[d] for d in deps_of(t) if d in ids and ids[d] is not t and role(ids[d].get("status")) != "draft"]
        if not deps:
            continue
        latest = max(deps, key=order.index)
        if order.index(latest) < order.index(t):
            continue
        order.remove(t)
        order.insert(order.index(latest) + 1, t)
        if t["id"] not in moved:
            moved.append(t["id"])
        queue.extend(str(u["id"]) for u in tickets_of(doc) if t["id"] in deps_of(u))
    if moved:
        for i, x in enumerate(order, 1):
            x["rank"] = i
    return moved


def cmd_edit(a: argparse.Namespace) -> int:
    changes: List[Tuple[str, Any, str]] = []  # (key, value, "set" | "append")
    for item in a.assignments:
        if "=" not in item:
            raise UsageError(f"edit: '{item}' should be key=value (text), key+=text (append) or key:=JSON",
                             fix=[f"{CMD} edit {a.id} summary=\"New text\" areas:='[\"backend\"]'"])
        key, value = item.split("=", 1)
        if key.endswith(":"):
            key = key[:-1]
            changes.append((key, parse_json_arg(f"{key}:=", value), "set"))
        elif key.endswith("+"):
            key = key[:-1]
            if KEY_RE.match(key) and key not in APPENDABLE and key not in PROTECTED:
                list_hint = key in LIST_FIELDS or key in FIELD_EXAMPLE
                raise Refused(f"{a.id} {key}: += only appends to text fields ({', '.join(APPENDABLE)})",
                              fix=[f"{CMD} edit {a.id} {key}:={jq(FIELD_EXAMPLE.get(key, ['...']))}   "
                                   "(give the whole new list)" if list_hint else
                                   f"{CMD} edit {a.id} {key}=\"...\"   (replaces the value)"])
            changes.append((key, value, "append"))
        else:
            changes.append((key, value, "set"))
    if a.file:
        patch = read_json(Path(a.file), f"patch file {a.file}", retry=f"{CMD} edit {a.id} --file {a.file}")
        if not isinstance(patch, dict):
            raise Refused(f"patch file {a.file}: must be a JSON object of field: value",
                          fix=[f"rewrite {a.file} as {{\"field\": value, ...}}, then run: {CMD} edit {a.id} --file {a.file}"])
        changes.extend((k, v, "set") for k, v in patch.items())
    if not changes and not a.rerank:
        raise UsageError("edit: give at least one key=value, key+=text, key:=JSON, --file PATCH.json or --rerank",
                         fix=[f"{CMD} edit {a.id} summary=\"New text\" areas:='[\"backend\"]'"])
    for key, _, _ in changes:
        if not KEY_RE.match(key):
            raise UsageError(f"edit: '{key}' is not a field name",
                             fix=[f"use a field name like summary, story, acceptance: {CMD} edit {a.id} summary=\"...\""])
        if key in PROTECTED:
            why, fixes = PROTECTED[key]
            raise Refused(f"{a.id} {key}: can't be changed with edit ({why})",
                          fix=[f.format(cmd=CMD, id=a.id) for f in fixes])
    # --rerank may repair a rank error already on disk: a repair write (fewer errors, none new) is allowed
    ids = split_ids(a.id, "edit")
    doc = load_for_write()

    def edit_one(d: Dict[str, Any], tid: str, save: bool) -> Tuple[List[str], List[str], List[str]]:
        t = find(d, tid)
        for key, value, mode in changes:
            if mode == "append":
                old = t.get(key)
                value = value if not (isinstance(old, str) and old.strip()) else old.rstrip() + "\n\n" + value
            if value is None:
                t.pop(key, None)
            else:
                ordered_set(t, key, copy.deepcopy(value))
        keys = list(dict.fromkeys(k for k, _, _ in changes))
        if "depends_on" in keys:
            recompute_unlocks(d)
        dropped = prune_item_checks(t) if ("acceptance" in keys or "test_scenarios" in keys) else []
        moved = rerank_after_deps(d, [tid]) if a.rerank else []
        commit(d, write=save)
        return keys, moved, dropped

    if len(ids) == 1:
        results = [edit_one(doc, ids[0], True)]
    else:
        doc, results = bulk(doc, ids, lambda d, tid: edit_one(d, tid, False), "be edited")
        write_board(doc)
    ts = by_id(doc)
    for tid, (keys, moved, dropped) in zip(ids, results):
        print(line(ts[tid]))
        print("updated: " + ", ".join(keys + (["rank"] if moved else [])) if keys or moved else "nothing to change")
        for m in moved:
            print(f"  moved {m} to rank {ts[m]['rank']} (right after its latest dependency)")
        if dropped:
            print(f"  dropped ticks for items that no longer exist: {', '.join(dropped)}")
    return 0


def cmd_rerank(a: argparse.Namespace) -> int:
    doc = load_for_write()
    t = find(doc, a.id)
    order = [x for x in by_rank(tickets_of(doc)) if x is not t]
    if a.first:
        order.insert(0, t)
    else:
        if a.after == a.id:
            raise Refused(f"{a.id} rank: --after must name a different ticket",
                          fix=[f"{CMD} rerank {a.id} --after OTHER_ID", f"{CMD} rerank {a.id} --first"])
        other = find(doc, a.after)
        order.insert(order.index(other) + 1, t)
    for i, x in enumerate(order, 1):
        x["rank"] = i
    commit(doc)
    print(line(t))
    return 0


# --------------------------------------------------------------------------- phases


def suggest_phase_id(doc: Dict[str, Any], raw: str = "") -> str:
    used = {str(p.get("id")) for p in phases_of(doc)}
    guess = re.sub(r"[^A-Za-z0-9_-]", "", raw)[:20]
    if guess and not guess[0].isalpha():
        guess = ("P" + guess)[:20]
    if guess and PHASE_ID_RE.match(guess) and guess not in used:
        return guess
    n = len(used) + 1
    while f"P{n}" in used:
        n += 1
    return f"P{n}"


def phase_id_error(doc: Dict[str, Any], pid: str, command: Any) -> Refused:
    """A bad new phase id. command(good_id) -> the command to suggest."""
    return Refused(f"phase {pid} id: must start with a letter and use only letters, digits, - or _ "
                   "(up to 20 characters)", fix=[command(suggest_phase_id(doc, pid))])


def find_phase(doc: Dict[str, Any], pid: str) -> Dict[str, Any]:
    for p in phases_of(doc):
        if p.get("id") == pid:
            return p
    known = [str(p.get("id")) for p in phases_of(doc)]
    close = [k for k in known if k.lower() == pid.lower()] or get_close_matches(pid, known, n=1)
    raise Refused(f"phase {pid} id: no such phase (phases: {', '.join(known) or 'none yet'})",
                  fix=([f"{CMD} " + shlex.join([close[0] if x == pid else x for x in RAW_ARGV])
                        + "   (did you mean this?)"] if close and RAW_ARGV else [])
                  + [f"{CMD} status   (lists the phases)"])


def cmd_add_phase(a: argparse.Namespace) -> int:
    doc = load_for_write()
    pid = a.id.strip()
    again = (lambda good: f"{CMD} add-phase --id {good} --name {shlex.quote(a.name)} "
                          f"--goal {shlex.quote(a.goal)} --demo {shlex.quote(a.demo)}"
                          + (" --unscheduled" if a.unscheduled else ""))
    if not pid:
        raise Refused("phase id: must not be empty", fix=[again(suggest_phase_id(doc))])
    if not PHASE_ID_RE.match(pid):
        raise phase_id_error(doc, pid, again)
    if any(p.get("id") == pid for p in phases_of(doc)):
        raise Refused(f"phase {pid} id: already exists",
                      fix=[again(suggest_phase_id(doc)) + "   (a free id)",
                           f"{CMD} status   (see the phases that exist)"])
    phase: Dict[str, Any] = {"id": pid, "name": a.name, "goal": a.goal, "demo": a.demo}
    if a.unscheduled:
        phase["unscheduled"] = True
    doc["phases"].append(phase)
    commit(doc)
    print(f"Added phase {pid}: {a.name}" + (" (unscheduled: next and list skip its tickets)" if a.unscheduled else ""))
    return 0


def cmd_edit_phase(a: argparse.Namespace) -> int:
    ex = f"{CMD} edit-phase {a.id} name=" + shlex.quote("New name") + " unscheduled:=true"
    changes: List[Tuple[str, Any]] = []
    for item in a.assignments:
        if "=" not in item:
            raise UsageError(f"edit-phase: '{item}' should be key=value (text) or key:=JSON", fix=[ex])
        key, value = item.split("=", 1)
        if key.endswith(":"):
            key = key[:-1]
            changes.append((key, parse_json_arg(f"{key}:=", value)))
        else:
            changes.append((key, value))
    if not changes:
        raise UsageError("edit-phase: give at least one of name=..., goal=..., demo=..., unscheduled:=true|false",
                         fix=[ex])
    for key, value in changes:
        if key == "id":
            raise Refused(f"phase {a.id} id: can't be changed with edit-phase (tickets point at it)",
                          fix=[f"{CMD} rename-phase {a.id} NEW_ID   (renames it and moves its tickets)"])
        if key not in PHASE_EDITABLE:
            raise Refused(f"phase {a.id} {key}: not a phase field ({', '.join(PHASE_EDITABLE)})",
                          fix=[f"{CMD} edit-phase {a.id} KEY=VALUE   (KEY one of: {', '.join(PHASE_EDITABLE)})"])
        if key == "unscheduled" and not isinstance(value, bool):
            raise Refused(f"phase {a.id} unscheduled: must be true or false (JSON, with :=)",
                          fix=[f"{CMD} edit-phase {a.id} unscheduled:=true   (or unscheduled:=false)"])
        if key == "name" and not (isinstance(value, str) and value.strip()):
            raise Refused(f"phase {a.id} name: must be non-empty text",
                          fix=[f"{CMD} edit-phase {a.id} name=" + shlex.quote("Phase name")])
        if key in ("goal", "demo") and value is not None and not isinstance(value, str):
            raise Refused(f"phase {a.id} {key}: must be text (or null to remove it)",
                          fix=[f"{CMD} edit-phase {a.id} {key}=\"...\""])
    doc = load_for_write()
    p = find_phase(doc, a.id)
    for key, value in changes:
        if value is None or (key == "unscheduled" and value is False):
            p.pop(key, None)
        else:
            ordered_set(p, key, value, PHASE_ORDER)
    commit(doc)
    print(f"Phase {a.id}: updated " + ", ".join(dict.fromkeys(k for k, _ in changes)))
    if p.get("unscheduled") is True:
        busy = [t for t in by_rank(tickets_of(doc)) if t.get("phase") == a.id
                and role(t.get("status")) in SCHEDULED_ONLY and role(t.get("status")) != "done"]
        print("  unscheduled: next and list skip its tickets"
              + (f"; already started: {', '.join(str(t.get('id')) for t in busy)}" if busy else ""))
    return 0


def cmd_rename_phase(a: argparse.Namespace) -> int:
    doc = load_for_write()
    p = find_phase(doc, a.old)
    new = a.new.strip()
    if not PHASE_ID_RE.match(new):
        raise phase_id_error(doc, new, lambda good: f"{CMD} rename-phase {a.old} {good}")
    if new == a.old:
        print(f"Phase {a.old} already has that id; nothing changed.")
        return 0
    if any(q.get("id") == new for q in phases_of(doc)):
        raise Refused(f"phase {new} id: already exists",
                      fix=[f"{CMD} rename-phase {a.old} {suggest_phase_id(doc, new + '2')}   (a free id)",
                           f"{CMD} remove-phase {a.old} --move-to {new}   (to merge {a.old} into {new})"])
    p["id"] = new
    moved = [t for t in tickets_of(doc) if t.get("phase") == a.old]
    for t in moved:
        t["phase"] = new
    commit(doc)
    print(f"Renamed phase {a.old} to {new}; {len(moved)} ticket{'s' if len(moved) != 1 else ''} moved with it.")
    return 0


def cmd_remove_phase(a: argparse.Namespace) -> int:
    doc = load_for_write()
    p = find_phase(doc, a.id)
    users = by_rank(t for t in tickets_of(doc) if t.get("phase") == a.id)
    if users and a.move_to is None:
        others = [str(q.get("id")) for q in phases_of(doc) if q.get("id") != a.id]
        names = ", ".join(str(t.get("id")) for t in users[:5]) + (" ..." if len(users) > 5 else "")
        raise Refused(f"phase {a.id}: {len(users)} ticket{'s are' if len(users) != 1 else ' is'} in it ({names})",
                      fix=([f"{CMD} remove-phase {a.id} --move-to {others[0]}   (moves them, then removes it)"]
                           if others else [f"{CMD} add-phase --id P9 --name \"...\" --goal \"...\" --demo \"...\"   "
                                           "(a phase to move them to first)"])
                      + [ASK + f"phase {a.id} still has tickets; which phase should they move to?"])
    if a.move_to is not None:
        if a.move_to == a.id:
            raise Refused(f"phase {a.id}: --move-to must name a different phase",
                          fix=[f"{CMD} remove-phase {a.id} --move-to OTHER   ({CMD} status lists the phases)"])
        find_phase(doc, a.move_to)
        for t in users:
            t["phase"] = a.move_to
    doc["phases"] = [q for q in doc["phases"] if q is not p]
    commit(doc)
    print(f"Removed phase {a.id}" + (f"; moved {len(users)} ticket{'s' if len(users) != 1 else ''} to {a.move_to}"
                                     if users else "") + ".")
    return 0


def cmd_reorder_phases(a: argparse.Namespace) -> int:
    doc = load_for_write()
    have = [str(p.get("id")) for p in phases_of(doc)]
    given = [x for arg in a.ids for x in parse_csv(arg)]
    dups = sorted({x for x in given if given.count(x) > 1})
    unknown = [x for x in given if x not in have]
    missing = [x for x in have if x not in given]
    if dups or unknown or missing:
        problems = ([f"listed twice: {', '.join(dups)}"] if dups else []) \
            + ([f"not a phase: {', '.join(unknown)}"] if unknown else []) \
            + ([f"missing: {', '.join(missing)}"] if missing else [])
        order = [x for x in dict.fromkeys(given) if x in have] + missing
        raise Refused(f"phases order: list every phase exactly once ({'; '.join(problems)})",
                      fix=[f"{CMD} reorder-phases {' '.join(order)}"])
    byp = {str(p.get("id")): p for p in phases_of(doc)}
    doc["phases"] = [byp[x] for x in given]
    commit(doc)
    print("Phases now: " + " ".join(given))
    return 0


def cmd_usertest(a: argparse.Namespace) -> int:
    doc = load_for_write()
    t = find(doc, a.id)
    uts = user_tests_of(t)
    if not 0 <= a.index < len(uts):
        have = f"it has {len(uts)} (index 0 to {len(uts) - 1})" if uts else "it has none"
        fix = ([f"{CMD} usertest {a.id} {len(uts) - 1 if a.index >= len(uts) else 0} {a.result}   "
                f"(index 0 is Test 1; see: {CMD} show {a.id})"] if uts else
               [f"{CMD} edit {a.id} user_tests:={jq(FIELD_EXAMPLE['user_tests'])}   (add a user test first)"])
        raise Refused(f"{a.id} user_tests: no user test at index {a.index}; {have}", fix=fix)
    note = a.note or ""
    checks = dict(checks_of(t))
    if a.result == "reset":
        old = checks.pop(str(a.index), None)
        if old is None:
            print(f"{a.id} test {a.index} has no recorded result; nothing changed.")
            return 0
        if checks:
            ordered_set(t, "user_checks", checks)
        else:
            t.pop("user_checks", None)
        was = old.get("result") if isinstance(old, dict) else "?"
        add_handoff(t, f"User test {a.index} result cleared (was {was})" + (f": {note}" if note.strip() else ""))
        commit(doc)
        print(f"Cleared the result of {a.id} test {a.index} ({uts[a.index].get('title', '')}); it was {was}.")
        return 0
    checks[str(a.index)] = {"result": a.result, "date": today(), "note": note}
    ordered_set(t, "user_checks", checks)
    moved = False
    if a.result == "fail" and role(t.get("status")) in ("user_testing", "merge_ready") \
            and status_for_role(doc, "in_progress"):
        t["status"] = status_for_role(doc, "in_progress")
        title = uts[a.index].get("title", f"test {a.index}")
        msg = f"User test failed: {title}" + (f": {note}" if note.strip() else "")
        h = t.get("handoff") if isinstance(t.get("handoff"), list) else []
        h.append(handoff_entry(t["status"], msg))
        ordered_set(t, "handoff", h)
        moved = True
    commit(doc)
    print(f"Recorded {a.result} for {a.id} test {a.index} ({uts[a.index].get('title', '')}).")
    if moved:
        print(f"{a.id} moved back to {t['status']}.")
    return 0


def clean_repo_url(url: str) -> str:
    u = url.strip().rstrip("/")
    if u.endswith(".git"):
        u = u[:-4]
    if not URL_RE.match(u):
        raise Refused(f"meta repo_url: '{url}' must be an http:// or https:// link to the repository",
                      fix=[f"{CMD} set-meta repo_url=https://github.com/OWNER/REPO   (the web address, not git@...)",
                           "git remote get-url origin   (to see the repository address)"])
    return u


def git(args: Sequence[str], cwd: Path) -> Optional[str]:
    """Run git; stdout stripped, or None when git is missing or the command fails."""
    try:
        proc = subprocess.run(["git", *args], cwd=str(cwd), capture_output=True, text=True,
                              encoding="utf-8", errors="replace", timeout=30)
    except (OSError, subprocess.SubprocessError):
        return None
    return proc.stdout.strip() if proc.returncode == 0 else None


def repo_root() -> Path:
    """The git toplevel of board.py's folder, else the current directory."""
    top = git(["rev-parse", "--show-toplevel"], HERE)
    return Path(top) if top else Path.cwd()


def resolve_commit(tid: str, ref: str, message: Optional[str]) -> Dict[str, Any]:
    """A commits entry for a sha or git ref. Unresolvable literal hex shas are kept as given."""
    ref = ref.strip()
    root = repo_root()
    sha = git(["rev-parse", "--verify", "--quiet", ref + "^{commit}"], root) if ref else None
    if sha and SHA_RE.match(sha):
        entry: Dict[str, Any] = {"sha": sha.lower(),
                                 "date": git(["log", "-1", "--format=%cd", "--date=short", sha], root) or today(),
                                 "message": git(["log", "-1", "--format=%s", sha], root) or (message or "")}
        branch = git(["rev-parse", "--abbrev-ref", "HEAD"], root)
        if branch and branch != "HEAD":
            entry["branch"] = branch
        if not DATE_RE.match(entry["date"]):
            entry["date"] = today()
        return entry
    if SHA_RE.match(ref):
        return {"sha": ref.lower(), "date": today(), "message": message or ""}
    raise Refused(f"{tid} commits: '{ref}' is not a commit git can find here ({root}) "
                  "and not a 7-40 character hex sha",
                  fix=["git log --oneline -10   (find the commit)", f"{CMD} link {tid} --commit HEAD",
                       f"{CMD} link {tid} --commit SHA --message \"subject\"   (a sha from another clone)"])


def same_sha(a: str, b: str) -> bool:
    a, b = a.lower(), b.lower()
    return a.startswith(b) or b.startswith(a)


def pr_number(url: str) -> Optional[int]:
    m = PR_NUMBER_RE.search(url)
    return int(m.group(1)) if m else None


def link_one(doc: Dict[str, Any], tid: str, a: argparse.Namespace) -> List[str]:
    """Record commits / the PR on one ticket (in doc). Returns report lines."""
    t = find(doc, tid)
    refs = a.commit or []
    report: List[str] = []
    if refs:
        commits = list(t["commits"]) if isinstance(t.get("commits"), list) else []
        added = 0
        for ref in refs:
            entry = resolve_commit(tid, ref, a.message)
            if any(isinstance(c, dict) and isinstance(c.get("sha"), str) and same_sha(c["sha"], entry["sha"])
                   for c in commits):
                report.append(f"commit {entry['sha'][:7]} already linked")
                continue
            commits.append(entry)
            added += 1
            report.append(f"commit {entry['sha'][:7]} {short(entry['message'], 60)}".rstrip())
        if added:
            ordered_set(t, "commits", commits)

    if a.pr is not None or a.pr_state is not None or a.pr_title is not None:
        old = t.get("pr") if isinstance(t.get("pr"), dict) else None
        if a.pr is None and old is None:
            raise Refused(f"{tid} pr: the ticket has no pull request yet",
                          fix=[f"{CMD} link {tid} --pr URL" + (f" --pr-state {a.pr_state}" if a.pr_state else "")])
        if a.pr is not None and (old is None or old.get("url") != a.pr.strip()):
            url = a.pr.strip()
            pr: Dict[str, Any] = {"url": url}
            n = pr_number(url)
            if n is not None:
                pr["number"] = n
            if a.pr_title is not None:
                pr["title"] = a.pr_title
            pr["state"] = a.pr_state or "draft"
        else:
            pr = dict(old or {})
            if a.pr_title is not None:
                pr["title"] = a.pr_title
            if a.pr_state is not None:
                pr["state"] = a.pr_state
            ordered = {k: pr[k] for k in ("url", "number", "title", "state") if k in pr}
            ordered.update({k: v for k, v in pr.items() if k not in ordered})
            pr = ordered
        ordered_set(t, "pr", pr)
        num = f" #{pr['number']}" if "number" in pr else ""
        report.append(f"PR{num} {pr['url']} ({pr.get('state')})")
    commit(doc, write=False)
    return report


def cmd_link(a: argparse.Namespace) -> int:
    ids = split_ids(a.id, "link")
    if not a.commit and a.pr is None and a.pr_state is None and a.pr_title is None:
        raise UsageError("link: give --commit SHA_OR_REF, --pr URL, --pr-state or --pr-title",
                         fix=[f"{CMD} link {a.id} --commit HEAD",
                              f"{CMD} link {a.id} --pr URL --pr-state draft"])
    if a.pr is not None and not URL_RE.match(a.pr.strip()):
        raise Refused(f"{ids[0]} pr.url: '{a.pr}' must be an http:// or https:// link",
                      fix=[f"{CMD} link {a.id} --pr https://github.com/OWNER/REPO/pull/N   "
                           "(or https://gitlab.com/GROUP/REPO/-/merge_requests/N)"])
    doc = load_for_write()
    if len(ids) == 1:
        reports = [link_one(doc, ids[0], a)]
    else:
        doc, reports = bulk(doc, ids, lambda d, tid: link_one(d, tid, a), "be linked")
    write_board(doc)
    ts = by_id(doc)
    for tid, report in zip(ids, reports):
        print(line(ts[tid]))
        for r in report:
            print("  " + r)
    return 0


def cmd_check_item(a: argparse.Namespace) -> int:
    doc = load_for_write()
    t = find(doc, a.id)
    field = ITEM_KINDS[a.kind]
    items = t.get(field) if is_str_list(t.get(field)) else []
    key = f"{a.kind}:{a.index}"
    unticking = a.cmd == "uncheck-item"
    ic = dict(item_checks_of(t))
    if unticking and key in ic:  # removing an existing tick is always allowed, even for a vanished item
        del ic[key]
        if ic:
            ordered_set(t, "item_checks", ic)
        else:
            t.pop("item_checks", None)
        commit(doc)
        print(f"Unticked {a.id} {a.kind} {a.index}" + (f": {short(items[a.index], 60)}" if 0 <= a.index < len(items)
                                                       else "") + ".")
        return 0
    if not 0 <= a.index < len(items):
        have = f"it has {len(items)} (index 0 to {len(items) - 1})" if items else "it has none"
        fix = ([f"{CMD} {a.cmd} {a.id} {a.kind} {max(0, min(a.index, len(items) - 1))}   "
                f"(index 0 is the first item; see: {CMD} show {a.id})"] if items else
               [f"{CMD} edit {a.id} {field}:={jq(FIELD_EXAMPLE[field])}   (add one first)"])
        raise Refused(f"{a.id} {field}: no item at index {a.index}; {have}", fix=fix)
    if unticking:
        print(f"{a.id} {a.kind} {a.index} was not ticked; nothing changed.")
        return 0
    ic[key] = {"date": today(), "evidence": (a.evidence or "").strip()}
    ordered_set(t, "item_checks", {k: ic[k] for k in sorted(ic, key=item_sort_key)})
    commit(doc)
    print(f"Ticked {a.id} {a.kind} {a.index}: {short(items[a.index], 60)}")
    return 0


def cmd_set_meta(a: argparse.Namespace) -> int:
    changes: List[Tuple[str, Any]] = []
    for item in a.assignments:
        if "=" not in item:
            raise UsageError(f"set-meta: '{item}' should be key=value (text) or key:=JSON", fix=[f"{CMD} set-meta repo_url=https://github.com/OWNER/REPO areas:='[\"backend\", \"ui\"]'"])
        key, value = item.split("=", 1)
        if key.endswith(":"):
            key = key[:-1]
            changes.append((key, parse_json_arg(f"{key}:=", value)))
        else:
            changes.append((key, value))
    if not changes:
        raise UsageError("set-meta: give at least one key=value or key:=JSON", fix=[f"{CMD} set-meta repo_url=https://github.com/OWNER/REPO areas:='[\"backend\", \"ui\"]'"])
    for key, value in changes:
        if key not in META_SETTABLE:
            raise Refused(f"meta {key}: can't be changed with set-meta; only {', '.join(META_SETTABLE)} can",
                          fix=[ASK + f"meta.{key} is fixed once the board exists; should it really change? "
                                     "If so it has to be edited by hand in kanban/tickets.json"
                               if key in ("prefix", "schema_version", "slate_version", "generated") else
                               f"{CMD} add-status / rename-status / edit-status / reorder-statuses / remove-status"
                               if key in ("statuses", "status_roles", "status_labels", "status_from", "status_note") else
                               f"{CMD} set-meta KEY=VALUE   (KEY one of: {', '.join(META_SETTABLE)})"])
        if key == "priorities" and not (is_str_list(value) and value):
            raise Refused("meta priorities: must be a non-empty list of names (JSON, with :=)",
                          fix=[f"{CMD} set-meta priorities:={jq(DEFAULT_PRIORITIES)}"])
        if key == "workflow" and value not in ("strict", "free"):
            raise Refused(f"meta workflow: '{value}' must be strict or free",
                          fix=[f"{CMD} set-meta workflow=strict   (forward moves follow the usual path)",
                               f"{CMD} set-meta workflow=free   (any move allowed)"])
        if key in ("areas", "user_test_areas") and not is_str_list(value):
            raise Refused(f"meta {key}: must be a list of names",
                          fix=[f"{CMD} set-meta {key}:={jq(value.split(',') if isinstance(value, str) and value else DEFAULT_AREAS)}"])
        if key == "check_quiet_optional" and not isinstance(value, bool):
            raise Refused("meta check_quiet_optional: must be true or false (JSON, with :=)",
                          fix=[f"{CMD} set-meta check_quiet_optional:=true   (or :=false)"])
        if key == "project" and not (isinstance(value, str) and value.strip()):
            raise Refused("meta project: must be non-empty text",
                          fix=[f"{CMD} set-meta project=" + shlex.quote("Project name")])
        if key == "repo_url" and value is not None and not isinstance(value, str):
            raise Refused("meta repo_url: must be an http:// or https:// link (or null to remove it)",
                          fix=[f"{CMD} set-meta repo_url=https://github.com/OWNER/REPO",
                               f"{CMD} set-meta repo_url:=null"])
    doc = load_for_write()
    meta = doc["meta"]
    for key, value in changes:
        if key == "priorities":
            off = [t for t in by_rank(tickets_of(doc)) if isinstance(t.get("priority"), str) and t["priority"] not in value]
            if off:
                raise Refused(f"meta priorities: {len(off)} ticket{'s use' if len(off) != 1 else ' uses'} a priority "
                              f"that isn't in the new list ({', '.join(str(t.get('id')) + ' ' + t['priority'] for t in off[:5])})",
                              fix=[f"{CMD} edit {off[0].get('id')} priority={value[0]}   (for each of them first)",
                                   f"{CMD} set-meta priorities:={jq(list(dict.fromkeys(list(value) + [t['priority'] for t in off])))}"
                                   "   (or keep their priorities in the list)"])
        if key == "workflow":
            apply_workflow(doc, value)
            continue
        if key == "repo_url" and value is None:
            meta.pop("repo_url", None)
            continue
        if key == "repo_url":
            value = clean_repo_url(value)
        if key == "project":
            value = value.strip()
        ordered_set(meta, key, value, META_ORDER)
    commit(doc)
    for key, _ in changes:
        if key == "workflow":
            print(f"workflow = {workflow_name(doc)}" + (f"; meta.status_from = {json.dumps(meta.get('status_from'), ensure_ascii=False)}"
                                                        if meta.get("status_from") else ""))
            continue
        print(f"meta.{key} = {json.dumps(meta.get(key), ensure_ascii=False)}")
    return 0


def derive_prefix(doc: Dict[str, Any]) -> Optional[str]:
    found = set()
    for t in tickets_of(doc):
        m = re.match(r"^([A-Z][A-Z0-9]{1,9})-\d+$", str(t.get("id", "")))
        if not m:
            return None
        found.add(m.group(1))
    return found.pop() if len(found) == 1 else None


def migrate_doc(doc: Dict[str, Any]) -> List[str]:
    """Additive schema migrations up to SCHEMA_VERSION. Returns a list of what changed."""
    changes: List[str] = []
    meta = doc.get("meta")
    if not isinstance(meta, dict):
        raise Refused("meta: missing or not an object; can't migrate this file", fix=[restore_fix("meta")])
    new = dict(meta)
    if not (isinstance(meta.get("prefix"), str) and meta["prefix"]):
        p = derive_prefix(doc)
        if p:
            new["prefix"] = p
            changes.append(f"added meta.prefix = {p} (from the ticket ids)")
    current = meta.get("schema_version") if is_int(meta.get("schema_version")) else 0
    if current < 1:
        if "user_test_areas" not in new:
            new["user_test_areas"] = list(DEFAULT_USER_TEST_AREAS)
            changes.append("added meta.user_test_areas = " + json.dumps(DEFAULT_USER_TEST_AREAS))
        st = new.get("statuses")
        if is_str_list(st):
            st = list(st)
            if "user_testing" not in st:
                st.insert(st.index("done") if "done" in st else len(st), "user_testing")
                changes.append("added status user_testing (before done)")
            if "draft" not in st:
                st.insert(0, "draft")
                changes.append("added status draft (first)")
            new["statuses"] = st
    if current < 2:
        # 1 -> 2: merge_ready (waiting for the PR to merge) sits right before done
        st = new.get("statuses")
        if is_str_list(st) and "merge_ready" not in st:
            st = list(st)
            st.insert(st.index("done") if "done" in st else len(st), "merge_ready")
            new["statuses"] = st
            changes.append("added status merge_ready (before done)")
    if current < SCHEMA_VERSION:
        new["schema_version"] = SCHEMA_VERSION
        changes.append(f"set meta.schema_version = {SCHEMA_VERSION} (was {current})" if current
                       else f"added meta.schema_version = {SCHEMA_VERSION}")
    if new.get("slate_version") != SLATE_VERSION:
        changes.append(f"set meta.slate_version = {SLATE_VERSION}"
                       + (f" (was {new['slate_version']})" if "slate_version" in new else ""))
        new["slate_version"] = SLATE_VERSION
    # keep existing keys where they were; place new keys at their canonical spot
    result: Dict[str, Any] = {k: new[k] for k in meta}
    for k in new:
        if k not in result:
            ordered_set(result, k, new[k], META_ORDER)
    doc["meta"] = result
    return changes


def cmd_migrate(a: argparse.Namespace) -> int:
    doc = read_board()
    refuse_if_newer(doc)
    before, _ = validate(doc)
    changes = migrate_doc(doc)
    after, warnings = validate(doc)
    new_errors = {str(e) for e in after} - {str(e) for e in before}
    if new_errors:
        raise Refused("not migrated: migration would add errors:", [e for e in after if str(e) in new_errors],
                      fix=[f"{CMD} check   (fix what it lists, then run migrate again)"])
    if changes:
        write_board(doc, report=False)
        print("Migrated kanban/tickets.json:")
        for c in changes:
            print(f"  - {c}")
    else:
        print(f"kanban/tickets.json is already at schema {SCHEMA_VERSION}, Slate {SLATE_VERSION}.")
    print_issues(after, warnings)
    summary = f"{len(after)} errors, {len(warnings)} warnings ({len(tickets_of(doc))} tickets)"
    if after:
        print(f"not ok: {summary}", file=sys.stderr)
        return 1
    print(f"ok: {summary}")
    return 0


def cmd_upgrade(a: argparse.Namespace) -> int:
    src = Path(a.src).expanduser().resolve()
    names = ("index.html", "board.py", "README.md")
    missing = [n for n in names if not (src / n).is_file()]
    if missing:
        raise Refused(f"upgrade --from {src}: missing {', '.join(missing)}; point it at the plugin's assets/board folder",
                      fix=[f"{CMD} upgrade --from PLUGIN_ROOT/assets/board   (or run /slate:upgrade)"])
    for n in names:
        dst = HERE / n
        if dst.exists() and os.path.samefile(str(src / n), str(dst)):
            continue
        atomic_write(dst, (src / n).read_text(encoding="utf-8"))
        print(f"Updated kanban/{n}")
    try:
        os.chmod(str(HERE / "board.py"), 0o755)
    except OSError:
        pass
    proc = subprocess.run([sys.executable, str(HERE / "board.py"), "migrate"], capture_output=True, text=True,
                          encoding="utf-8", errors="replace")
    sys.stdout.write(proc.stdout)
    sys.stderr.write(proc.stderr)
    return proc.returncode


# --------------------------------------------------------------------------- time helpers


def utcnow() -> datetime:
    return datetime.now(timezone.utc).replace(microsecond=0)


def iso_utc(dt: datetime) -> str:
    return dt.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def parse_utc(s: Any) -> Optional[datetime]:
    """ISO 8601 time (Z, offset or naive = UTC), or None."""
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s[-1] in "Zz":
        s = s[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(s)
    except ValueError:
        return None
    return dt if dt.tzinfo is not None else dt.replace(tzinfo=timezone.utc)


def log_time(dt: Optional[datetime] = None) -> str:
    return (dt or utcnow()).astimezone(timezone.utc).strftime("%Y-%m-%d %H:%M")


def now_minute() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


# --------------------------------------------------------------------------- write lock


def pid_alive(pid: int) -> bool:
    """Is process pid running on this machine? (Never signals it; Windows asks the kernel.)"""
    if pid <= 0:
        return False
    if os.name == "nt":
        try:
            import ctypes
            k32 = ctypes.windll.kernel32  # type: ignore[attr-defined]
            handle = k32.OpenProcess(0x1000, False, pid)  # PROCESS_QUERY_LIMITED_INFORMATION
            if not handle:
                return k32.GetLastError() == 5  # access denied: it exists
            code = ctypes.c_ulong()
            ok = k32.GetExitCodeProcess(handle, ctypes.byref(code))
            k32.CloseHandle(handle)
            return bool(ok) and code.value == 259  # STILL_ACTIVE
        except Exception:
            return True
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def lock_info() -> Optional[Dict[str, Any]]:
    """The write lock's content plus "_age" (seconds), or None when there is no lock."""
    try:
        text = WRITE_LOCK.read_text(encoding="utf-8")
        age = max(0.0, time.time() - WRITE_LOCK.stat().st_mtime)
    except FileNotFoundError:
        return None
    except OSError:
        return {"_age": 0.0}
    try:
        rec = json.loads(text)
    except ValueError:
        rec = {}
    rec = rec if isinstance(rec, dict) else {}
    rec["_age"] = age
    return rec


def lock_stale(rec: Dict[str, Any]) -> Tuple[bool, str]:
    age = rec.get("_age", 0.0)
    if age > LOCK_STALE_SECONDS:
        return True, f"it is {int(age)} s old"
    pid = rec.get("pid")
    if is_int(pid) and rec.get("host") == socket.gethostname() and not pid_alive(pid):
        return True, f"process {pid} is gone"
    return False, ""


def lock_holder(rec: Optional[Dict[str, Any]]) -> str:
    rec = rec or {}
    return (f"process {rec.get('pid', '?')} on {rec.get('host', '?')} since {rec.get('time', '?')}"
            + (f", running {rec['cmd']}" if isinstance(rec.get("cmd"), str) and rec["cmd"] else ""))


class WriteLock:
    """Exclusive lock for one read-modify-write of tickets.json: kanban/.slate-write.lock created with
    O_CREAT|O_EXCL (works on every OS). Waits up to LOCK_WAIT_SECONDS, then refuses."""

    def __init__(self) -> None:
        self.held = False
        self.body = ""

    def __enter__(self) -> "WriteLock":
        self.body = json.dumps({"pid": os.getpid(), "host": socket.gethostname(), "time": iso_utc(utcnow()),
                                "cmd": RAW_ARGV[0] if RAW_ARGV else ""})
        deadline = time.monotonic() + LOCK_WAIT_SECONDS
        while True:
            try:
                fd = os.open(str(WRITE_LOCK), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
            except (FileExistsError, PermissionError) as e:  # Windows: PermissionError while it is being removed
                if isinstance(e, PermissionError) and not WRITE_LOCK.exists() and time.monotonic() >= deadline:
                    raise Refused(f"kanban/.slate-write.lock: can't create it ({e.strerror or e})",
                                  fix=[ASK + f"board.py can't create files in {HERE}; can you fix the folder's "
                                             "permissions?"])
                if time.monotonic() >= deadline:
                    raise Refused(f"kanban/.slate-write.lock: another board.py command is changing the board "
                                  f"({lock_holder(lock_info())}); waited {int(LOCK_WAIT_SECONDS)} s",
                                  fix=["wait a moment, then run the same command again",
                                       f"{CMD} unlock-write   (remove stale lock: only if it's older than "
                                       f"{int(LOCK_STALE_SECONDS)} s or its process is gone)"])
                time.sleep(0.03 + random.random() * 0.07)
                continue
            except OSError as e:
                raise Refused(f"kanban/.slate-write.lock: can't create it ({e.strerror or e})",
                              fix=[ASK + f"board.py can't create files in {HERE}; can you fix the folder's permissions?"])
            with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
                f.write(self.body + "\n")
            self.held = True
            return self

    def __exit__(self, *exc: Any) -> None:
        if not self.held:
            return
        self.held = False
        try:  # only remove our own lock (unlock-write may have removed it and someone else taken it)
            if WRITE_LOCK.read_text(encoding="utf-8").strip() == self.body:
                WRITE_LOCK.unlink()
        except OSError:
            pass


def cmd_unlock_write(a: argparse.Namespace) -> int:
    rec = lock_info()
    if rec is None:
        print("No write lock (kanban/.slate-write.lock); nothing to remove.")
        return 0
    stale, why = lock_stale(rec)
    if not stale:
        raise Refused(f"kanban/.slate-write.lock: held by {lock_holder(rec)}; it isn't stale "
                      f"(younger than {int(LOCK_STALE_SECONDS)} s and its process is running), so it was kept",
                      fix=["wait for that command to finish, then run yours again",
                           ASK + "is another board.py stuck (another agent or terminal)? If so, stop it, "
                                 f"then run: {CMD} unlock-write"])
    try:
        WRITE_LOCK.unlink()
    except FileNotFoundError:
        pass
    print(f"Removed a stale write lock ({why}; {lock_holder(rec)}).")
    return 0


# --------------------------------------------------------------------------- claims


CLAIM_KEEP = ("in_progress", "review", "user_testing", "merge_ready")  # other statuses clear the claim


def whoami(as_: Optional[str]) -> str:
    """Who is working: --as NAME, else the current git branch, else host-user."""
    if as_ and as_.strip():
        return as_.strip()
    branch = git(["rev-parse", "--abbrev-ref", "HEAD"], HERE)
    if branch and branch != "HEAD":
        return branch
    user = os.environ.get("USER") or os.environ.get("USERNAME") or "user"
    return f"{socket.gethostname()}-{user}"


def claim_of(t: Dict[str, Any]) -> Optional[str]:
    c = t.get("claimed_by")
    return c["by"] if isinstance(c, dict) and isinstance(c.get("by"), str) and c["by"].strip() else None


def claimed_elsewhere(t: Dict[str, Any], me: Optional[str]) -> Optional[str]:
    by = claim_of(t)
    return by if by and by != me else None


def apply_claim(t: Dict[str, Any], status: str, me: Optional[str], took_over: bool = False) -> None:
    """in_progress (or a take-over) claims the ticket for me; review/user_testing/merge_ready keep the
    claim; every other status clears it."""
    if role(status) in CLAIM_KEEP:
        if me and (role(status) == "in_progress" or took_over) and claim_of(t) != me:
            ordered_set(t, "claimed_by", {"by": me, "since": now_minute()})
    else:
        t.pop("claimed_by", None)


def line_on(t: Dict[str, Any]) -> str:
    by = claim_of(t)
    return line(t) + (f"  on: {by}" if by else "")


def handoff_entry(status: Any, note: str) -> Dict[str, Any]:
    """One history entry; changes made from the board page record via: "board page"."""
    e: Dict[str, Any] = {"date": today(), "status": status, "note": note}
    if VIA:
        e["via"] = VIA
    return e


def add_handoff(t: Dict[str, Any], note: str) -> None:
    h = t.get("handoff") if isinstance(t.get("handoff"), list) else []
    h.append(handoff_entry(t.get("status"), note))
    ordered_set(t, "handoff", h)


def cmd_claim(a: argparse.Namespace) -> int:
    doc = load_for_write()
    t = find(doc, a.id)
    me = whoami(a.as_)
    if role(t.get("status")) == "done":
        raise Refused(f"{a.id} status: done; there is nothing to claim", fix=[f"{CMD} next   (pick an open ticket)"])
    other = claimed_elsewhere(t, me)
    if a.take_over is not None and not a.take_over.strip():
        raise Refused(f"{a.id} claimed_by: --take-over needs a reason",
                      fix=[f"{CMD} claim {a.id} --take-over \"why you are taking it over\""])
    if other and a.take_over is None:
        raise Refused(f"{a.id} claimed_by: being worked on by {other} (since {t['claimed_by'].get('since', '?')})",
                      fix=[f"{CMD} next   (pick a ticket nobody is on)",
                           ASK + f"{a.id} is claimed by {other}; should you take it over? If yes: "
                                 f"{CMD} claim {a.id} --take-over \"reason\""])
    if claim_of(t) == me:
        print(f"{a.id} is already claimed by {me}; nothing changed.")
        return 0
    ordered_set(t, "claimed_by", {"by": me, "since": now_minute()})
    if other:
        add_handoff(t, f"Took over from {other}: {a.take_over.strip()}")
    commit(doc)
    print(f"{a.id} claimed by {me}" + (f" (taken over from {other})" if other else "") + ".")
    return 0


def cmd_release(a: argparse.Namespace) -> int:
    doc = load_for_write()
    t = find(doc, a.id)
    by = claim_of(t)
    if by is None and "claimed_by" not in t:
        print(f"{a.id} isn't claimed; nothing changed.")
        return 0
    me = whoami(a.as_)
    if a.take_over is not None and not a.take_over.strip():
        raise Refused(f"{a.id} claimed_by: --take-over needs a reason",
                      fix=[f"{CMD} release {a.id} --take-over \"why\""])
    if by and by != me and a.take_over is None:
        raise Refused(f"{a.id} claimed_by: claimed by {by}, not by {me}",
                      fix=[ASK + f"{a.id} is claimed by {by}; release their claim? If yes: "
                                 f"{CMD} release {a.id} --take-over \"reason\"",
                           f"{CMD} release {a.id} --as {shlex.quote(by)}   (if you ARE {by})"])
    t.pop("claimed_by", None)
    if by and by != me:
        add_handoff(t, f"Released {by}'s claim: {a.take_over.strip()}")
    commit(doc)
    print(f"{a.id} released" + (f" (was claimed by {by})" if by else "") + ".")
    return 0


# --------------------------------------------------------------------------- unlock (one hand edit)


def is_interactive() -> bool:
    """A person at a real terminal (both stdin and stdout). Tests replace this; there is no env override."""
    try:
        return sys.stdin.isatty() and sys.stdout.isatty()
    except (AttributeError, ValueError):
        return False


def read_code(prompt: str) -> str:
    return input(prompt)


def new_code() -> str:
    return "".join(secrets.choice("ABCDEFGHJKLMNPQRSTUVWXYZ") for _ in range(4))


def read_record(path: Path) -> Optional[Dict[str, Any]]:
    """A small JSON object file: None when missing, {} when unreadable or not an object."""
    try:
        rec = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return None
    except (OSError, ValueError):
        return {}
    return rec if isinstance(rec, dict) else {}


def log_entry(event: str, **fields: Any) -> Dict[str, Any]:
    out: Dict[str, Any] = {"date": log_time(), "event": event}
    out.update({k: v for k, v in fields.items() if v is not None})
    return out


def activation_entries(rec: Dict[str, Any]) -> List[Dict[str, Any]]:
    """The guard activates permission-prompt unlocks without touching tickets.json; log that now."""
    if rec.get("approved") != "permission prompt":
        return []
    when = parse_utc(rec.get("activated")) or parse_utc(rec.get("created"))
    e = log_entry("activated", reason=rec.get("reason"), minutes=rec.get("minutes"), until=rec.get("until"),
                  approved="permission prompt", permission_mode=rec.get("permission_mode"))
    if when:
        e["date"] = log_time(when)
    return [e]


def read_pending_log() -> List[Dict[str, Any]]:
    try:
        data = json.loads(UNLOCK_PENDING_LOG.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []
    return [x for x in data if isinstance(x, dict)] if isinstance(data, list) else []


def fold_unlock_records(doc: Dict[str, Any]) -> List[Path]:
    """Move finished unlock records (used, expired, pending log entries) into meta.unlock_log.
    Returns the files to delete once the board has been written."""
    meta = doc.get("meta") if isinstance(doc, dict) else None
    if not isinstance(meta, dict) or ("unlock_log" in meta and not isinstance(meta["unlock_log"], list)):
        return []
    entries: List[Dict[str, Any]] = []
    cleanup: List[Path] = []
    pending = read_pending_log()
    if pending or UNLOCK_PENDING_LOG.exists():
        entries.extend(pending)
        cleanup.append(UNLOCK_PENDING_LOG)
    used = read_record(UNLOCK_USED)
    if used is not None:
        entries.extend(activation_entries(used))
        e = log_entry("used", reason=used.get("reason"), tool=used.get("tool"), approved=used.get("approved"))
        when = parse_utc(used.get("used_at"))
        if when:
            e["date"] = log_time(when)
        entries.append(e)
        cleanup.append(UNLOCK_USED)
    active = read_record(UNLOCK)
    if active is not None:
        until = parse_utc(active.get("until"))
        if until is None or until <= utcnow():
            entries.extend(activation_entries(active))
            entries.append(log_entry("expired", reason=active.get("reason"), until=active.get("until")))
            cleanup.append(UNLOCK)
    if entries:
        log = list(meta.get("unlock_log") or [])
        log.extend(entries)
        ordered_set(meta, "unlock_log", log, META_ORDER)
    return cleanup


def log_unlock(entries: List[Dict[str, Any]]) -> None:
    """Append to meta.unlock_log with a log-only write. Works on a board with errors (the log adds none);
    if the board can't be written at all (not JSON, newer schema), the entries wait in
    kanban/.slate-unlock-log.json and are folded in by the next write."""
    global BASE_ERRORS
    try:
        doc = read_board()
        refuse_if_newer(doc)
        meta = doc.get("meta")
        if not isinstance(meta, dict) or ("unlock_log" in meta and not isinstance(meta["unlock_log"], list)):
            raise Refused("meta can't take the log")
        BASE_ERRORS = validate(doc)[0]
        cleanup = fold_unlock_records(doc)  # older records first, so the log stays in order
        log = list(meta.get("unlock_log") or [])
        log.extend(entries)
        ordered_set(meta, "unlock_log", log, META_ORDER)
        errors = validate(doc)[0]
        if write_blockers(errors, need_fewer=False):
            raise Refused("the log would add errors")
        write_board(doc, errors, report=False, cleanup=cleanup)
    except Refused:
        atomic_write(UNLOCK_PENDING_LOG, dumps(read_pending_log() + entries))


def unlock_state() -> List[str]:
    """Warnings while an unlock is active or a request is pending."""
    out: List[str] = []
    now = utcnow()
    rec = read_record(UNLOCK)
    if rec is not None:
        until = parse_utc(rec.get("until"))
        if until is not None and until > now:
            out.append(f"an unlock is active until {log_time(until)} UTC (reason: {rec.get('reason', '?')}): "
                       "ONE direct edit of kanban/tickets.json is allowed")
    req = read_record(UNLOCK_REQUEST)
    if req is not None:
        created = parse_utc(req.get("created"))
        fresh = created is not None and timedelta(0) <= now - created < REQUEST_FRESH
        out.append(f"an unlock request is {'waiting for approval' if fresh else 'pending but too old to approve'} "
                   f"(reason: {req.get('reason', '?')})")
    return out


def print_unlock_warnings(lines: Sequence[str]) -> None:
    for ln in lines:
        print(f"warning: {ln}")
        print(f"  fix: {CMD} lock   (cancels it if it's no longer needed)")


def cmd_unlock(a: argparse.Namespace) -> int:
    reason = (a.reason or "").strip()
    again = f"{CMD} unlock --reason " + shlex.quote(reason or "why a hand edit is needed") + f" --minutes {a.minutes}"
    if not reason:
        raise Refused("unlock reason: --reason is required (it is shown to the person approving and logged)",
                      fix=[again])
    if not 1 <= a.minutes <= UNLOCK_MAX_MINUTES:
        raise Refused(f"unlock minutes: {a.minutes} must be 1 to {UNLOCK_MAX_MINUTES}",
                      fix=[f"{CMD} unlock --reason {shlex.quote(reason)} --minutes {min(max(a.minutes, 1), UNLOCK_MAX_MINUTES)}"])
    if not TICKETS.exists():
        raise Refused(f"no tickets.json next to board.py ({TICKETS}); there is nothing to unlock",
                      fix=[f"{CMD} init --project NAME --prefix PFX   (or run /slate:init)"])
    now = utcnow()
    if is_interactive():
        code = new_code()
        print(f"Slate unlock: allow ONE direct edit of kanban/tickets.json within {a.minutes} minutes.")
        print(f"Reason: {reason}")
        try:
            typed = read_code(f"Type {code} to approve (anything else cancels): ")
        except (EOFError, KeyboardInterrupt):
            typed = ""
        if typed.strip().upper() != code:
            log_unlock([log_entry("refused", reason=reason, minutes=a.minutes, approved="terminal code",
                                  note="the code didn't match")])
            raise Refused("unlock: the code didn't match, so nothing was unlocked",
                          fix=[again + "   (run it again and type the code it shows)"])
        until = now + timedelta(minutes=a.minutes)
        atomic_write(UNLOCK, dumps({"until": iso_utc(until), "reason": reason, "minutes": a.minutes,
                                    "created": iso_utc(now), "approved": "terminal code"}))
        try:
            UNLOCK_REQUEST.unlink()
        except FileNotFoundError:
            pass
        log_unlock([log_entry("activated", reason=reason, minutes=a.minutes, until=iso_utc(until),
                              approved="terminal code")])
        print(f"Unlocked: ONE direct edit of kanban/tickets.json is allowed until {log_time(until)} UTC.")
        print(f"The guard uses it up on that edit. Cancel it with: {CMD} lock")
        return 0
    req = {"id": secrets.token_hex(4), "reason": reason, "minutes": a.minutes, "created": iso_utc(now)}
    atomic_write(UNLOCK_REQUEST, dumps(req))
    log_unlock([log_entry("requested", reason=reason, minutes=a.minutes, id=req["id"])])
    print("Unlock requested (not active yet). Approve it in Claude Code's permission prompt (shown in")
    print("Manual, Accept edits and Auto modes). In Plan, Bypass or Don't-ask mode, or in another agent tool,")
    print("the user runs this in their own terminal and types the code it shows:")
    print(f"  {CMD} unlock --reason {shlex.quote(reason)} --minutes {a.minutes}")
    return 0


def cmd_lock(a: argparse.Namespace) -> int:
    removed: List[str] = []
    active = read_record(UNLOCK)
    for path, what in ((UNLOCK, "active unlock"), (UNLOCK_REQUEST, "pending request")):
        try:
            path.unlink()
            removed.append(what)
        except FileNotFoundError:
            pass
    log_unlock([log_entry("locked", removed=", ".join(removed) or "nothing",
                          reason=(active or {}).get("reason") if active else None)])
    print("Locked: removed the " + " and the ".join(removed) + "." if removed else
          "Locked: there was no active unlock or pending request.")
    return 0


# --------------------------------------------------------------------------- other boards: load, compare


class _Missing:
    def __repr__(self) -> str:
        return "(none)"

    def __deepcopy__(self, memo: Any) -> "_Missing":
        return self


MISSING: Any = _Missing()
RECORD_LISTS = ("handoff", "commits")
RECORD_MAPS = ("user_checks", "item_checks")


def handoffs_of(t: Dict[str, Any]) -> List[Dict[str, Any]]:
    h = t.get("handoff")
    return [x for x in h if isinstance(x, dict)] if isinstance(h, list) else []


def rec_key(field: str, x: Any) -> Any:
    """Identity of a record-list entry: handoff by (status, note) ignoring the date; commits by sha."""
    if not isinstance(x, dict):
        return json.dumps(x, sort_keys=True, ensure_ascii=False)
    if field == "handoff":
        return (str(x.get("status", "")), " ".join(str(x.get("note", "")).split()))
    if field == "commits":
        return str(x.get("sha", "")).lower()[:7]
    return json.dumps(x, sort_keys=True, ensure_ascii=False)


def as_list(v: Any) -> List[Any]:
    return list(v) if isinstance(v, list) else []


def as_map(v: Any) -> Dict[str, Any]:
    return dict(v) if isinstance(v, dict) else {}


def board_file_in(p: Path) -> Optional[Path]:
    if p.is_file():
        return p
    if p.is_dir():
        for c in (p / "kanban" / "tickets.json", p / "tickets.json"):
            if c.is_file():
                return c
    return None


def load_other(spec: str) -> Tuple[Dict[str, Any], str]:
    """OTHER board: a tickets.json path, a folder holding kanban/tickets.json or tickets.json, or a git
    ref (git show REF:<this board's path>). Returns (doc, label)."""
    p = Path(spec).expanduser()
    if p.exists():
        f = board_file_in(p)
        if f is None:
            raise Refused(f"{spec}: no kanban/tickets.json or tickets.json in that folder",
                          fix=[f"ls {shlex.quote(str(p))}   (find the board, then pass its path)"])
        if f.resolve() == TICKETS.resolve():
            raise Refused(f"{spec}: that is this board itself",
                          fix=[f"{CMD} diff main   (compare with a branch, or another checkout's board)"])
        doc = read_json(f, f"board {f}")
        if not isinstance(doc, dict):
            raise Refused(f"{f}: not a Slate board (must be a JSON object with meta, phases and tickets)",
                          fix=[ASK + f"is {f} really a Slate tickets.json?"])
        return doc, str(f)
    if spec.startswith("-"):
        raise UsageError(f"'{spec}' is not a path or a git ref", fix=[f"{CMD} diff main"])
    if git(["rev-parse", "--show-toplevel"], HERE) is None:
        raise Refused(f"{spec}: no such file or folder (and this isn't a git repository, so it can't be a branch)",
                      fix=[f"{CMD} diff PATH/TO/tickets.json   (or a folder that has kanban/tickets.json)"])
    if git(["rev-parse", "--verify", "--quiet", spec + "^{commit}"], HERE) is None:
        raise Refused(f"{spec}: not a file, a folder, or a git branch, tag or commit here",
                      fix=["git branch -a   (list the branches)", f"{CMD} diff PATH/TO/tickets.json"])
    text = git(["show", f"{spec}:./{TICKETS.name}"], HERE)
    if text is None:
        raise Refused(f"{spec}: has no board at this path (kanban/{TICKETS.name})",
                      fix=[f"git ls-tree -r --name-only {spec} | grep tickets.json   (find it)"])
    try:
        doc = json.loads(text)
    except ValueError as e:
        raise Refused(f"{spec}: its kanban/tickets.json is not valid JSON ({e})",
                      fix=[ASK + f"the board on {spec} is broken; fix it there first?"])
    if not isinstance(doc, dict):
        raise Refused(f"{spec}: its kanban/tickets.json is not a JSON object", fix=[ASK + f"fix the board on {spec} first?"])
    return doc, spec


def ordered_keys(*dicts: Dict[str, Any]) -> List[str]:
    keys: List[str] = [k for k in TICKET_ORDER if any(k in d for d in dicts)]
    for d in dicts:
        for k in d:
            if k not in keys:
                keys.append(k)
    return keys


def ticket_diff(o: Dict[str, Any], t: Dict[str, Any], include_rank: bool = False) -> Dict[str, Any]:
    """Per field: added (only there), removed (only here), changed. unlocks is derived, so ignored;
    rank only with include_rank; handoff and commits compared as records (handoff dates ignored)."""
    out: Dict[str, Dict[str, Any]] = {"added": {}, "removed": {}, "changed": {}}
    for k in ordered_keys(o, t):
        if k in ("id", "unlocks") or (k == "rank" and not include_rank):
            continue
        ov, tv = o.get(k, MISSING), t.get(k, MISSING)
        if k in RECORD_LISTS:
            ok = {rec_key(k, x) for x in as_list(ov)}
            tk = {rec_key(k, x) for x in as_list(tv)}
            only_there = [x for x in as_list(tv) if rec_key(k, x) not in ok]
            only_here = [x for x in as_list(ov) if rec_key(k, x) not in tk]
            if only_here or only_there:
                out["changed"][k] = {"only_here": only_here, "only_there": only_there}
            continue
        if ov == tv:
            continue
        if ov is MISSING:
            out["added"][k] = tv
        elif tv is MISSING:
            out["removed"][k] = ov
        else:
            out["changed"][k] = {"here": ov, "there": tv}
    return {k: v for k, v in out.items() if v}


def board_diff(ours: Dict[str, Any], theirs: Dict[str, Any], include_rank: bool = False) -> Dict[str, Any]:
    o, t = by_id(ours), by_id(theirs)
    added = [{"id": x["id"], "title": x.get("title")} for x in by_rank(t.values()) if x["id"] not in o]
    removed = [{"id": x["id"], "title": x.get("title")} for x in by_rank(o.values()) if x["id"] not in t]
    changed: Dict[str, Any] = {}
    for x in by_rank(o.values()):
        if x["id"] in t:
            d = ticket_diff(x, t[x["id"]], include_rank)
            if d:
                changed[x["id"]] = d
    po = {str(p.get("id")): p for p in phases_of(ours)}
    pt = {str(p.get("id")): p for p in phases_of(theirs)}
    ph_changed: Dict[str, Any] = {}
    for pid, p in po.items():
        if pid in pt and pt[pid] != p:
            ph_changed[pid] = {k: {"here": p.get(k), "there": pt[pid].get(k)}
                               for k in dict.fromkeys(list(p) + list(pt[pid])) if p.get(k) != pt[pid].get(k)}
    common_o = [x for x in po if x in pt]
    common_t = [x for x in pt if x in po]
    phases = {"added": [x for x in pt if x not in po], "removed": [x for x in po if x not in pt],
              "changed": ph_changed, "order_changed": common_o != common_t}
    mo, mt = meta_of(ours), meta_of(theirs)
    meta = {k: {"here": mo.get(k), "there": mt.get(k)} for k in dict.fromkeys(list(mo) + list(mt))
            if k not in ("generated", "unlock_log") and mo.get(k) != mt.get(k)}
    same = not (added or removed or changed or phases["added"] or phases["removed"] or ph_changed
                or phases["order_changed"] or meta)
    return {"added": added, "removed": removed, "changed": changed, "phases": phases, "meta": meta, "same": same}


def fmt_val(v: Any, n: int = 60) -> str:
    if v is MISSING or v is None:
        return "(none)"
    if isinstance(v, str):
        return json.dumps(short(v, n), ensure_ascii=False)
    return short(json.dumps(v, ensure_ascii=False), n)


def diff_lines(d: Dict[str, Any], label: str) -> List[str]:
    out: List[str] = []
    if d["added"]:
        out.append(f"Tickets only in {label} ({len(d['added'])}):")
        out.extend(f"  + {x['id']}  {x.get('title') or ''}" for x in d["added"])
    if d["removed"]:
        out.append(f"Tickets only here ({len(d['removed'])}):")
        out.extend(f"  - {x['id']}  {x.get('title') or ''}" for x in d["removed"])
    if d["changed"]:
        out.append(f"Changed tickets ({len(d['changed'])}), here -> {label}:")
        for tid, c in d["changed"].items():
            out.append(f"  ~ {tid}")
            for k, v in c.get("changed", {}).items():
                if "only_there" in v:
                    what = "notes" if k == "handoff" else "commits"
                    bits = ([f"{len(v['only_there'])} {what} only in {label}"] if v["only_there"] else []) + \
                           ([f"{len(v['only_here'])} only here"] if v["only_here"] else [])
                    out.append(f"      {k}: " + ", ".join(bits))
                else:
                    out.append(f"      {k}: {fmt_val(v['here'])} -> {fmt_val(v['there'])}")
            for k, v in c.get("added", {}).items():
                out.append(f"      {k}: only in {label}: {fmt_val(v)}")
            for k, v in c.get("removed", {}).items():
                out.append(f"      {k}: only here: {fmt_val(v)}")
    ph = d["phases"]
    for pid in ph["added"]:
        out.append(f"Phase {pid}: only in {label}")
    for pid in ph["removed"]:
        out.append(f"Phase {pid}: only here")
    for pid, c in ph["changed"].items():
        out.append(f"Phase {pid}: " + "; ".join(f"{k} {fmt_val(v['here'])} -> {fmt_val(v['there'])}" for k, v in c.items()))
    if ph["order_changed"]:
        out.append("Phase order differs")
    for k, v in d["meta"].items():
        out.append(f"meta.{k}: {fmt_val(v['here'])} -> {fmt_val(v['there'])}")
    return out


def cmd_diff(a: argparse.Namespace) -> int:
    doc = read_board()
    other, label = load_other(a.other)
    d = board_diff(doc, other, a.include_rank)
    if a.json:
        print(json.dumps(dict(d, here=str(TICKETS), other=label), indent=2, ensure_ascii=False))
        return 0
    print(f"This board (kanban/tickets.json) compared with {label}:")
    lines = diff_lines(d, label)
    for ln in lines:
        print(ln)
    if d["same"]:
        print("No differences" + ("" if a.include_rank else " (rank-only changes are hidden; --include-rank shows them)")
              + ".")
    else:
        print(f"\nTo bring {label}'s changes in: {CMD} sync --from {shlex.quote(label)} --dry-run")
    return 0


def lacking(ours: Dict[str, Any], theirs: Dict[str, Any], full: bool = True) -> List[str]:
    """What theirs has that ours lacks: tickets and handoff notes (full: also phases, commits, user test
    results, item ticks, and a status further along)."""
    out: List[str] = []
    o = by_id(ours)
    statuses = statuses_of(ours) or statuses_of(theirs)
    for tid, t in by_id(theirs).items():
        if tid not in o:
            out.append(f"{tid}: a ticket only there ({short(str(t.get('title', '')), 40)})")
            continue
        mine = o[tid]
        mk = {rec_key("handoff", h) for h in handoffs_of(mine)}
        n = sum(1 for h in handoffs_of(t) if rec_key("handoff", h) not in mk)
        if n:
            out.append(f"{tid} handoff: {n} note{'s' if n != 1 else ''} only there")
        if not full:
            continue
        ck = {rec_key("commits", c) for c in as_list(mine.get("commits"))}
        n = sum(1 for c in as_list(t.get("commits")) if rec_key("commits", c) not in ck)
        if n:
            out.append(f"{tid} commits: {n} only there")
        for f in RECORD_MAPS:
            mm, tm = as_map(mine.get(f)), as_map(t.get(f))
            extra = [k for k, v in tm.items() if mm.get(k) != v]
            if extra:
                out.append(f"{tid} {f}: {', '.join(extra)} only there")
        so, st = mine.get("status"), t.get("status")
        if so in statuses and st in statuses and statuses.index(st) > statuses.index(so):
            out.append(f"{tid} status: {st} there, {so} here")
    if full:
        mine_ph = {str(p.get("id")) for p in phases_of(ours)}
        out.extend(f"phase {p.get('id')}: only there" for p in phases_of(theirs) if str(p.get("id")) not in mine_ph)
    return out


# --------------------------------------------------------------------------- board of record (#18)


def git_dir_path(out: str) -> Path:
    p = Path(out)
    return (p if p.is_absolute() else HERE / p).resolve()


def default_branch_ref() -> Optional[str]:
    """origin/HEAD, else a local main or master. Never fetches."""
    ref = git(["symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD"], HERE)
    if ref:
        return ref
    for b in ("main", "master"):
        if git(["rev-parse", "--verify", "--quiet", f"refs/heads/{b}"], HERE) is not None:
            return b
    return None


def board_at_ref(ref: str) -> Optional[Dict[str, Any]]:
    text = git(["show", f"{ref}:./{TICKETS.name}"], HERE)
    if text is None:
        return None
    try:
        doc = json.loads(text)
    except ValueError:
        return None
    return doc if isinstance(doc, dict) else None


def behind_default(doc: Dict[str, Any]) -> Optional[Tuple[str, List[str]]]:
    """(ref, what the default branch's board has that this one lacks: tickets and handoff notes)."""
    ref = default_branch_ref()
    if not ref:
        return None
    other = board_at_ref(ref)
    if other is None:
        return None
    missing = lacking(doc, other, full=False)
    return (ref, missing) if missing else None


def resolve_board_path(raw: str) -> Path:
    p = Path(raw).expanduser()
    f = board_file_in(p)
    return (f or p).resolve()


def board_of_record_problems(doc: Dict[str, Any]) -> List[Tuple[str, List[str]]]:
    out: List[Tuple[str, List[str]]] = []
    env = os.environ.get("SLATE_BOARD_OF_RECORD", "").strip()
    if env:
        target = resolve_board_path(env)
        if target != TICKETS.resolve():
            q = shlex.quote(str(target))
            out.append((f"SLATE_BOARD_OF_RECORD is {target}, not this board ({TICKETS}); this may not be the "
                        "board of record" + ("" if target.exists() else " (and that file doesn't exist)"),
                        [f"{CMD} diff {q}", f"{CMD} sync --from {q}",
                         ASK + "should this change be made on the board of record instead?"]))
    top = git(["rev-parse", "--show-toplevel"], HERE)
    if top is None:
        return out
    gd = git(["rev-parse", "--git-dir"], HERE)
    cd = git(["rev-parse", "--git-common-dir"], HERE)
    if gd and cd and git_dir_path(gd) != git_dir_path(cd):
        wl = git(["worktree", "list", "--porcelain"], HERE) or ""
        main_wt = next((ln[len("worktree "):] for ln in wl.splitlines() if ln.startswith("worktree ")), None)
        main_board: Optional[Path] = None
        if main_wt:
            try:
                main_board = Path(main_wt) / TICKETS.resolve().relative_to(Path(top).resolve())
            except ValueError:
                main_board = None
        where = str(main_board) if main_board else "the main worktree's kanban/tickets.json"
        q = shlex.quote(where)
        out.append((f"this is a secondary git worktree ({top}); the board of record is the main worktree's "
                    f"board: {where}", [f"{CMD} diff {q}", f"{CMD} sync --from {q}"]))
    b = behind_default(doc)
    if b:
        ref, missing = b
        out.append((f"the board on {ref} has changes this board lacks: " + "; ".join(missing[:5])
                    + (f"; +{len(missing) - 5} more" if len(missing) > 5 else ""),
                    [f"{CMD} diff {ref}", f"{CMD} sync --from {ref}"]))
    return out


def warn_board_of_record(doc: Dict[str, Any]) -> None:
    try:
        probs = board_of_record_problems(doc)
    except Exception:  # a warning must never break a write
        return
    for msg, fixes in probs:
        print(f"warning: {msg}", file=sys.stderr)
        for ln in fix_lines(fixes):
            print(ln, file=sys.stderr)


# --------------------------------------------------------------------------- sync, merge driver, copy-to


def further(statuses: Sequence[str], a: Any, b: Any) -> Any:
    """The status further along: by role order when both have a role, else meta.statuses order
    (unknown ones lose; a tie keeps a)."""
    ra, rb = role(a), role(b)
    if ra is not None and rb is not None and ra != rb:
        return b if ROLES.index(rb) > ROLES.index(ra) else a
    ia = statuses.index(a) if a in statuses else -1
    ib = statuses.index(b) if b in statuses else -1
    return b if ib > ia else a


def union_records(field: str, ours: Any, theirs: Any) -> List[Any]:
    """ours plus theirs' entries ours lacks (handoff by status+note, commits by sha), kept in date order."""
    out = [copy.deepcopy(x) for x in as_list(ours)]
    keys = {rec_key(field, x) for x in out}
    added = False
    for x in as_list(theirs):
        k = rec_key(field, x)
        if k not in keys:
            out.append(copy.deepcopy(x))
            keys.add(k)
            added = True
    if added:
        out.sort(key=lambda x: str(x.get("date", "")) if isinstance(x, dict) else "")
    return out


def sort_map(field: str, m: Dict[str, Any]) -> Dict[str, Any]:
    if field == "item_checks":
        return {k: m[k] for k in sorted(m, key=item_sort_key)}
    return {k: m[k] for k in sorted(m, key=lambda k: (0, int(k)) if k.isdigit() else (1, 0))}


def newer_check(a: Any, b: Any) -> Any:
    """Two user test results for the same test: the later date wins, a tie keeps a."""
    da = a.get("date", "") if isinstance(a, dict) else ""
    db = b.get("date", "") if isinstance(b, dict) else ""
    return b if str(db) > str(da) else a


def union_map2(field: str, ours: Any, theirs: Any, prefer: str) -> Dict[str, Any]:
    out = as_map(ours)
    for k, v in as_map(theirs).items():
        if k not in out:
            out[k] = copy.deepcopy(v)
        elif out[k] != v:
            if field == "user_checks":
                out[k] = copy.deepcopy(newer_check(out[k], v) if prefer == "ours" else newer_check(v, out[k]))
            elif prefer == "theirs":
                out[k] = copy.deepcopy(v)
    return sort_map(field, out)


def refresh_unlocks(doc: Dict[str, Any]) -> None:
    """Recompute unlocks on tickets that carry the field (never adds it to older tickets)."""
    for t in tickets_of(doc):
        if "unlocks" in t and isinstance(t.get("id"), str):
            t["unlocks"] = expected_unlocks(doc, t["id"])


def order_deps_first(order: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Stable reorder so every non-draft ticket comes after its non-draft dependencies (cycles: as is)."""
    ids = {t.get("id"): t for t in order if isinstance(t.get("id"), str)}
    placed: Set[int] = set()
    out: List[Dict[str, Any]] = []
    remaining = list(order)
    while remaining:
        pick = 0
        for i, t in enumerate(remaining):
            if role(t.get("status")) == "draft":
                pick = i
                break
            waiting = [d for d in deps_of(t) if d in ids and ids[d] is not t
                       and role(ids[d].get("status")) != "draft" and id(ids[d]) not in placed]
            if not waiting:
                pick = i
                break
        t = remaining.pop(pick)
        placed.add(id(t))
        out.append(t)
    return out


def assign_ranks(order: List[Dict[str, Any]]) -> None:
    """Ranks strictly increasing in this order; a ticket keeps its rank when it still fits."""
    prev = 0
    for t in order:
        r = t.get("rank")
        if is_int(r) and r > prev:
            prev = r
        else:
            prev += 1
            ordered_set(t, "rank", prev)


def insert_after_pred(seq: List[str], new_id: str, ref_order: List[str]) -> None:
    """Insert new_id into seq right after the nearest id that precedes it in ref_order (else first)."""
    pos = ref_order.index(new_id)
    for j in range(pos - 1, -1, -1):
        if ref_order[j] in seq:
            seq.insert(seq.index(ref_order[j]) + 1, new_id)
            return
    seq.insert(0, new_id)


def looks_like_clash(o: Dict[str, Any], t: Dict[str, Any]) -> bool:
    """Same id, different ticket: title and summary (or description) both differ."""
    if o.get("title") == t.get("title"):
        return False
    if "summary" in o or "summary" in t:
        return o.get("summary") != t.get("summary")
    return o.get("description") != t.get("description")


def sync_into(doc: Dict[str, Any], other: Dict[str, Any], only: Sequence[str],
              prefer: str) -> Tuple[List[str], List[Issue]]:
    """Apply other's differences to doc (in memory). Returns (plan lines, id clashes)."""
    lines: List[str] = []
    clashes: List[Issue] = []
    statuses = statuses_of(doc)
    # phases
    if not only:
        mine = {str(p.get("id")): p for p in phases_of(doc)}
        their_order = [str(p.get("id")) for p in phases_of(other)]
        seq = [str(p.get("id")) for p in phases_of(doc)]
        for p in phases_of(other):
            pid = str(p.get("id"))
            if pid not in mine:
                insert_after_pred(seq, pid, their_order)
                mine[pid] = copy.deepcopy(p)
                lines.append(f"+ phase {pid}: {p.get('name', '')}")
            elif mine[pid] != p:
                fields = [k for k in dict.fromkeys(list(p) + list(mine[pid])) if k != "id" and p.get(k) != mine[pid].get(k)]
                if prefer == "theirs":
                    for k in fields:
                        if k in p:
                            ordered_set(mine[pid], k, copy.deepcopy(p[k]), PHASE_ORDER)
                    lines.append(f"~ phase {pid}: {', '.join(fields)} (theirs)")
        if isinstance(doc.get("phases"), list):
            doc["phases"] = [mine[x] for x in seq]
    # tickets
    ours = by_id(doc)
    theirs = by_id(other)
    their_rank_order = [t["id"] for t in by_rank(theirs.values())]
    added: List[str] = []
    for tid in their_rank_order:
        if only and tid not in only:
            continue
        t = theirs[tid]
        if tid not in ours and tid in {x["ticket"].get("id") for x in removed_of(doc)}:
            lines.append(f"skipped {tid}: removed on this board (restore it first if it should come back)")
            continue
        if tid not in ours:
            doc["tickets"].append(copy.deepcopy(t))
            added.append(tid)
            lines.append(f"+ {tid}  {t.get('title', '')}  ({t.get('status')})")
            continue
        o = ours[tid]
        if looks_like_clash(o, t):
            clashes.append(Issue(tid, "id", f"is a different ticket on each board (here: '{short(str(o.get('title', '')), 40)}', "
                                            f"there: '{short(str(t.get('title', '')), 40)}'); two branches probably "
                                            "created the same id",
                                 [ASK + f"{tid} means two different tickets; which one keeps the id? The other has "
                                        "to be re-created with `new` on one board first"]))
            continue
        changed: List[str] = []
        for k in ordered_keys(o, t):
            if k in ("id", "rank", "unlocks") or k not in t:
                continue
            ov, tv = o.get(k, MISSING), t[k]
            if ov == tv:
                continue
            if k in RECORD_LISTS:
                nv: Any = union_records(k, ov, tv)
            elif k in RECORD_MAPS:
                nv = union_map2(k, ov, tv, prefer)
            elif k == "status":
                nv = further(statuses, ov, tv)
            elif ov is MISSING or prefer == "theirs":
                nv = copy.deepcopy(tv)
            else:
                continue
            if nv != ov:
                ordered_set(o, k, nv)
                changed.append(k if k != "status" else f"status {ov} -> {nv}")
        if changed:
            lines.append(f"~ {tid}: " + ", ".join(changed))
    if added:
        order_ids = [t["id"] for t in by_rank(x for x in tickets_of(doc) if x.get("id") not in added)]
        for tid in added:
            insert_after_pred(order_ids, tid, their_rank_order)
        idmap = by_id(doc)
        for tid in added:  # a new ticket gets the next free rank at its place (its old rank meant nothing here)
            idmap[tid]["rank"] = 0
        assign_ranks(order_deps_first([idmap[x] for x in order_ids]))
    else:
        assign_ranks(order_deps_first(by_rank(tickets_of(doc))))
    refresh_unlocks(doc)
    return lines, clashes


def cmd_sync(a: argparse.Namespace) -> int:
    doc = load_for_write()
    other, label = load_other(a.src)
    only = parse_multi(a.only)
    theirs = by_id(other)
    unknown = [x for x in only if x not in theirs]
    if unknown:
        raise Refused(f"{unknown[0]} id: not on {label} (named in --only)",
                      fix=[f"{CMD} diff {shlex.quote(label)}   (see what {label} has)"])
    before = dumps(doc)
    lines, clashes = sync_into(doc, other, only, a.prefer)
    q = shlex.quote(label)
    if clashes:
        rest = [x for x in by_id(other) if x not in {c.where for c in clashes} and (not only or x in only)]
        raise Refused(f"not synced: {len(clashes)} ticket id{'s' if len(clashes) != 1 else ''} clash (nothing was changed):",
                      clashes, fix=[f"{CMD} sync --from {q} --only {','.join(rest)}   (everything but the clashes)"]
                      if rest else [])
    if dumps(doc) == before:
        print(f"Nothing to sync: this board already has everything from {label}.")
        return 0
    errors, _ = validate(doc)
    blocked = write_blockers(errors, need_fewer=False)
    if a.dry_run:
        print(f"Dry run: nothing saved. Syncing from {label} would change:")
        for ln in lines or ["(ranks only)"]:
            print("  " + ln)
        if blocked:
            emit_error(blocked[0] or "the synced board would be invalid:", [], blocked[1])
            return 1
        print(f"Run without --dry-run to apply: {CMD} sync --from {q}" + (f" --only {','.join(only)}" if only else "")
              + (" --prefer ours" if a.prefer == "ours" else ""))
        return 0
    if blocked:
        raise refuse_blocked(blocked, "not synced: the result would be invalid (nothing was changed):")
    write_board(doc, errors)
    print(f"Synced from {label}:")
    for ln in lines or ["(ranks only)"]:
        print("  " + ln)
    return 0


def merge_pick(field: str, b: Any, o: Any, t: Any, statuses: Sequence[str], where: str,
               conflicts: List[str]) -> Any:
    """Three-way merge of one field. Records are unioned, status goes further along, ranks are redone
    later; anything else changed differently on both sides keeps ours and is reported."""
    if o == t:
        return o
    if o == b:
        return t
    if t == b:
        return o
    if field in RECORD_LISTS or field in ("unlock_log", "removed"):
        return union_records(field, [] if o is MISSING else o, [] if t is MISSING else t)
    if field in RECORD_MAPS:
        return merge_map3(field, b, o, t)
    if field == "status":
        return further(statuses, o, t)
    if field in ("rank", "unlocks"):
        return o
    if field == "claimed_by" and isinstance(o, dict) and isinstance(t, dict):
        return t if str(t.get("since", "")) > str(o.get("since", "")) else o
    conflicts.append(f"{where} {field}: changed on both sides; kept ours {fmt_val(o)}, theirs was {fmt_val(t)}")
    return o


def merge_map3(field: str, b: Any, o: Any, t: Any) -> Any:
    bm, om, tm = as_map(b), as_map(o), as_map(t)
    out: Dict[str, Any] = {}
    for k in dict.fromkeys(list(om) + list(tm) + list(bm)):
        bv, ov, tv = bm.get(k, MISSING), om.get(k, MISSING), tm.get(k, MISSING)
        if ov == tv:
            v = ov
        elif ov == bv:
            v = tv
        elif tv == bv:
            v = ov
        elif field == "user_checks" and ov is not MISSING and tv is not MISSING:
            v = newer_check(ov, tv)
        else:
            v = ov if ov is not MISSING else tv
        if v is not MISSING:
            out[k] = copy.deepcopy(v)
    if not out and o is MISSING and t is MISSING:
        return MISSING
    return sort_map(field, out)


def merge_obj3(b: Dict[str, Any], o: Dict[str, Any], t: Dict[str, Any], where: str, statuses: Sequence[str],
               conflicts: List[str], order: Sequence[str] = TICKET_ORDER) -> Dict[str, Any]:
    out = copy.deepcopy(o)
    for k in dict.fromkeys(list(o) + list(t) + list(b)):
        v = merge_pick(k, b.get(k, MISSING), o.get(k, MISSING), t.get(k, MISSING), statuses, where, conflicts)
        if v is MISSING:
            out.pop(k, None)
        else:
            ordered_set(out, k, copy.deepcopy(v), order)
    return out


def merge_boards(base: Dict[str, Any], ours: Dict[str, Any], theirs: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    conflicts: List[str] = []
    statuses = statuses_of(ours) or statuses_of(theirs)
    merged = copy.deepcopy(ours)
    # meta
    if isinstance(ours.get("meta"), dict) and isinstance(theirs.get("meta"), dict):
        merged["meta"] = merge_obj3(meta_of(base), ours["meta"], theirs["meta"], "meta", statuses, conflicts, META_ORDER)
        statuses = statuses_of(merged) or statuses
    # phases
    if isinstance(ours.get("phases"), list) and isinstance(theirs.get("phases"), list):
        bp = {str(p.get("id")): p for p in phases_of(base)}
        op = {str(p.get("id")): p for p in phases_of(ours)}
        tp = {str(p.get("id")): p for p in phases_of(theirs)}
        b_order, o_order, t_order = list(bp), list(op), list(tp)
        result: Dict[str, Dict[str, Any]] = {}
        for pid in dict.fromkeys(o_order + t_order):
            b, o, t = bp.get(pid), op.get(pid), tp.get(pid)
            if o is not None and t is not None:
                result[pid] = merge_obj3(b or {}, o, t, f"phase {pid}", statuses, conflicts, PHASE_ORDER)
            elif o is not None:  # not in theirs: added by us, or deleted by them
                if b is None or b == o:
                    if b is None:
                        result[pid] = copy.deepcopy(o)
                else:
                    conflicts.append(f"phase {pid}: deleted on their side, changed on ours; kept ours")
                    result[pid] = copy.deepcopy(o)
            elif t is not None:
                if b is None:
                    result[pid] = copy.deepcopy(t)
                elif b != t:
                    conflicts.append(f"phase {pid}: deleted on our side, changed on theirs; kept ours (deleted)")
        common = [x for x in b_order if x in op and x in tp]
        o_c, t_c = [x for x in o_order if x in common], [x for x in t_order if x in common]
        lead, follow = (t_order, o_order) if o_c == common and t_c != common else (o_order, t_order)
        seq = [x for x in lead if x in result]
        for x in follow:
            if x in result and x not in seq:
                insert_after_pred(seq, x, follow)
        merged["phases"] = [result[x] for x in seq]
    # tickets
    if isinstance(ours.get("tickets"), list) and isinstance(theirs.get("tickets"), list):
        bt, ot, tt = by_id(base), by_id(ours), by_id(theirs)
        items: List[Tuple[Dict[str, Any], int, int]] = []  # (ticket, side, index)
        for i, (tid, o) in enumerate(ot.items()):
            b, t = bt.get(tid), tt.get(tid)
            if t is None:
                if b is None:
                    items.append((copy.deepcopy(o), 0, i))
                elif b != o:
                    conflicts.append(f"{tid}: deleted on their side, changed on ours; kept ours")
                    items.append((copy.deepcopy(o), 0, i))
                continue
            if b is None and o != t:
                if looks_like_clash(o, t):
                    conflicts.append(f"{tid}: added on both sides as different tickets (same id); kept ours. "
                                     f"Theirs was '{short(str(t.get('title', '')), 50)}'")
                    items.append((copy.deepcopy(o), 0, i))
                    continue
            items.append((merge_obj3(b or {}, o, t, tid, statuses, conflicts), 0, i))
        for i, (tid, t) in enumerate(tt.items()):
            if tid in ot:
                continue
            b = bt.get(tid)
            if b is None:
                items.append((copy.deepcopy(t), 1, i))
            elif b != t:
                conflicts.append(f"{tid}: deleted on our side, changed on theirs; kept ours (deleted)")
        items.sort(key=lambda x: (rank_of(x[0]), x[1], x[2]))
        order = order_deps_first([x[0] for x in items])
        assign_ranks(order)
        # array order: ours' order, then their new tickets (ranks, not the array, set the build order)
        pos = {id(x[0]): n for n, x in enumerate(sorted(items, key=lambda x: (x[1], x[2])))}
        merged["tickets"] = sorted((x[0] for x in items), key=lambda t: pos[id(t)])
        refresh_unlocks(merged)
    return merged, conflicts


def load_side(path: str, allow_empty: bool) -> Optional[Dict[str, Any]]:
    try:
        text = Path(path).read_text(encoding="utf-8")
    except OSError:
        return {} if allow_empty else None
    if not text.strip():
        return {} if allow_empty else None
    try:
        doc = json.loads(text)
    except ValueError:
        return {} if allow_empty else None
    return doc if isinstance(doc, dict) else ({} if allow_empty else None)


def cmd_merge_driver(a: argparse.Namespace) -> int:
    base = load_side(a.base, True)
    ours = load_side(a.ours, False)
    theirs = load_side(a.theirs, False)
    if ours is None or theirs is None or base is None:
        side = "ours" if ours is None else "theirs"
        print(f"slate merge: can't merge kanban/tickets.json: {side} is not a valid board (JSON object); "
              "left ours as it is. Fix it, then run: python3 kanban/board.py check", file=sys.stderr)
        return 1
    use_roles(ours)
    merged, conflicts = merge_boards(base, ours, theirs)
    known = {issue_key(e) for e in validate(ours)[0]} | {issue_key(e) for e in validate(theirs)[0]}
    new_errors = [e for e in validate(merged)[0] if issue_key(e) not in known]
    atomic_write(Path(a.ours), dumps(merged))
    for c in conflicts:
        print(f"slate merge conflict: {c}", file=sys.stderr)
    for e in new_errors:
        print(f"slate merge: the merged board has an error: {e}", file=sys.stderr)
        for ln in fix_lines(e.fix, "    "):
            print(ln, file=sys.stderr)
    if conflicts or new_errors:
        print(f"slate merge: {len(conflicts)} conflict{'s' if len(conflicts) != 1 else ''}, "
              f"{len(new_errors)} new error{'s' if len(new_errors) != 1 else ''}; ours was kept for each conflict. "
              "Check it (python3 kanban/board.py check), fix with board.py, then git add kanban/tickets.json.",
              file=sys.stderr)
        return 1
    return 0


def repo_rel(path: Path, root: Path) -> str:
    return path.resolve().relative_to(root.resolve()).as_posix()


def cmd_install_merge_driver(a: argparse.Namespace) -> int:
    top = git(["rev-parse", "--show-toplevel"], HERE)
    if top is None:
        raise Refused("install-merge-driver: this isn't a git repository (or git isn't installed)",
                      fix=["git init   (if this project should be in git), then run it again"])
    root = Path(top)
    rel_t = repo_rel(TICKETS, root)
    rel_b = repo_rel(HERE / "board.py", root)
    py = (a.python or "").strip() or PY
    attrs = root / ".gitattributes"
    text = attrs.read_text(encoding="utf-8") if attrs.exists() else ""
    have = any(ln.split()[:1] == [rel_t] and "merge=slate" in ln.split() for ln in text.splitlines())
    if not have:
        # eol=lf: board.py always writes \n; without it Windows checkouts (autocrlf) show the whole
        # file as changed after every write
        text = text + ("\n" if text and not text.endswith("\n") else "") + f"{rel_t} merge=slate text eol=lf\n"
        atomic_write(attrs, text)
        print(f"Added to .gitattributes: {rel_t} merge=slate text eol=lf   (commit this)")
    else:
        lines = text.splitlines()
        new = [ln if not (ln.split()[:1] == [rel_t] and "merge=slate" in ln.split() and "eol=lf" not in ln.split())
               else ln.rstrip() + " text eol=lf" for ln in lines]
        if new != lines:  # 0.2.0 adds eol=lf to lines written by older versions
            atomic_write(attrs, "\n".join(new) + "\n")
            print(f"Updated .gitattributes: {rel_t} merge=slate text eol=lf   (commit this)")
        else:
            print(f".gitattributes already has: {rel_t} merge=slate")
    driver = f"{py} {shlex.quote(rel_b)} merge-driver %O %A %B"
    for key, value in (("merge.slate.name", "Slate board merge"), ("merge.slate.driver", driver)):
        if git(["config", key, value], root) is None:
            raise Refused(f"install-merge-driver: git config {key} failed",
                          fix=[f"git config {key} {shlex.quote(value)}"])
    print(f"git config merge.slate.driver = {driver}")
    print("git config merge.slate.name = Slate board merge")
    print("Every clone runs this once (git config isn't committed; .gitattributes is).")
    return 0


def copy_target(p: Path) -> Path:
    if p.is_dir():
        k = p / "kanban"
        if not k.is_dir():
            raise Refused(f"copy-to: {p} has no kanban/ folder (is Slate set up there?)",
                          fix=[f"{CMD} copy-to {shlex.quote(str(p / 'kanban' / 'tickets.json'))}   "
                               "(after creating that folder)", ASK + f"should {p} get a Slate board (/slate:init there)?"])
        return k / "tickets.json"
    if not p.parent.is_dir():
        raise Refused(f"copy-to: folder {p.parent} doesn't exist", fix=[f"ls {shlex.quote(str(p.parent.parent))}"])
    return p


def cmd_copy_to(a: argparse.Namespace) -> int:
    doc = read_board()
    errors, _ = validate(doc)
    if errors:
        raise Refused("not copied: kanban/tickets.json has errors (only a valid board is copied):", errors,
                      fix=[f"{CMD} check   (fix what it lists, then copy again)"])
    target = copy_target(Path(a.path).expanduser())
    q = shlex.quote(str(target))
    if target.exists() and target.resolve() == TICKETS.resolve():
        raise Refused("copy-to: that is this board itself", fix=[f"{CMD} copy-to PATH   (another checkout's folder)"])
    if target.exists() and not a.force:
        try:
            other = json.loads(target.read_text(encoding="utf-8"))
        except (OSError, ValueError) as e:
            raise Refused(f"not copied: {target} exists but isn't a readable board ({e})",
                          fix=[ASK + f"overwrite {target}? If yes: {CMD} copy-to {q} --force"])
        missing = lacking(doc, other if isinstance(other, dict) else {})
        if missing:
            raise Refused(f"not copied: {target} has changes this board lacks (they would be lost):",
                          [Issue(m, "", "") for m in missing],
                          fix=[f"{CMD} diff {q}", f"{CMD} sync --from {q}   (bring them in first, then copy)",
                               ASK + f"overwrite them anyway? If yes: {CMD} copy-to {q} --force"])
    atomic_write(target, dumps(doc))
    print(f"Copied kanban/tickets.json to {target} ({len(tickets_of(doc))} tickets).")
    return 0


