GITIGNORED = (".slate-unlock.json", ".slate-unlock.used.json", ".slate-unlock-request.json",
              ".slate-unlock-log.json", ".slate-write.lock", ".slate-serve.json", ".slate-serve.log")


def web_url(remote: str) -> Optional[str]:
    r = remote.strip()
    m = re.match(r"^(?:ssh://)?git@([^:/]+)(?::\d+)?[:/](.+?)(?:\.git)?/?$", r)
    if m:
        return f"https://{m.group(1)}/{m.group(2)}"
    m = re.match(r"^(https?)://(?:[^@/]+@)?(.+?)(?:\.git)?/?$", r)
    return f"{m.group(1)}://{m.group(2)}" if m else None


def team_settings_problem(project: Path) -> Optional[str]:
    """None when the project's committed .claude/settings.json makes Claude Code load Slate for
    everyone who clones it (slate marketplace declared + slate@slate enabled); else what's missing."""
    path = project / ".claude" / "settings.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    except (OSError, ValueError):
        return ".claude/settings.json isn't valid JSON"
    if not isinstance(data, dict):
        return ".claude/settings.json isn't a JSON object"
    missing = []
    mk = data.get("extraKnownMarketplaces")
    if not (isinstance(mk, dict) and isinstance(mk.get("slate"), dict)):
        missing.append("extraKnownMarketplaces.slate")
    ep = data.get("enabledPlugins")
    if not (isinstance(ep, dict) and ep.get("slate@slate") is True):
        missing.append('enabledPlugins."slate@slate"')
    if not missing:
        return None
    return (".claude/settings.json doesn't load Slate for people who clone this repo (missing "
            + " and ".join(missing) + ")")


def doctor_problems(against: Optional[str], doc: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    """Project health, local checks only. kind: setup (fixed by /slate:upgrade or a command), tickets
    (board content: errors, behind the default branch) or state (write lock, unlock)."""
    probs: List[Dict[str, Any]] = []

    def add(code: str, kind: str, message: str, fix: Sequence[str], **extra: Any) -> None:
        probs.append(dict({"code": code, "kind": kind, "message": message, "fix": list(fix)}, **extra))

    if doc is None:
        try:
            doc = read_board()
        except Refused as e:
            add("board-unreadable", "tickets", e.message, e.fix)
    if doc is not None:
        errors = validate(doc)[0]
        if errors:
            add("board-errors", "tickets", f"kanban/tickets.json has {len(errors)} error{'s' if len(errors) != 1 else ''}",
                [f"{CMD} check   (lists them, each with a fix)"], count=len(errors))
        sv = meta_of(doc).get("schema_version")
        if not is_int(sv) or sv < SCHEMA_VERSION:
            add("schema-outdated", "setup", f"kanban/tickets.json is schema {sv if is_int(sv) else '(none)'}; this board.py "
                                   f"writes schema {SCHEMA_VERSION}", [f"{CMD} migrate", "/slate:upgrade"])
        elif sv > SCHEMA_VERSION:
            add("plugin-outdated", "setup", NEWER_MSG, [NEWER_FIX], ahead=True)
    slate_md = HERE.parent / "SLATE.md"
    team = team_settings_problem(HERE.parent)
    if team:
        add("team-settings-missing", "setup", team,
            ["/slate:upgrade   (adds Slate to .claude/settings.json so everyone who clones the repo gets it)"])
    elif (HERE.parent / ".claude" / "settings.json").is_file() and \
            git(["check-ignore", "-q", ".claude/settings.json"], HERE.parent) is not None:
        add("team-settings-ignored", "setup", ".claude/settings.json is ignored by git, so people who clone this "
                                    "repo won't get Slate automatically",
            [ASK + "commit .claude/settings.json (remove it from .gitignore) so teammates get Slate? Slate never "
                   "edits .gitignore for this"], info=True)
    if against:
        try:
            plugin = plugin_version(against)
            rel = relation(plugin)
            if rel == "behind":
                add("board-files-outdated", "setup", f"the board ({SLATE_VERSION}) is older than the plugin ({plugin})", ["/slate:upgrade"])
            elif rel == "ahead":
                add("plugin-outdated", "setup", f"the board is newer than the plugin ({plugin})",
                    [ASK + "update the Slate plugin (claude plugin marketplace update slate, then claude plugin "
                           "update slate@slate)?"], ahead=True)
        except Refused as e:
            add("plugin-unreadable", "setup", e.message, e.fix)
        template = Path(against) / "templates" / "SLATE.md"
        if template.is_file():
            if not slate_md.is_file():
                add("slate-md-missing", "setup", "SLATE.md is missing", ["/slate:init   (recreates it)"])
            else:
                want = re.findall(r"^## (.+?)\s*$", template.read_text(encoding="utf-8"), re.M)
                have = set(re.findall(r"^## (.+?)\s*$", slate_md.read_text(encoding="utf-8"), re.M))
                gone = [h for h in want if h not in have]
                if gone:
                    add("slate-md-sections", "setup", "SLATE.md lacks sections: " + ", ".join(gone),
                        ["/slate:upgrade   (adds the missing sections)"])
    if slate_md.is_file() and doc is not None:
        stale = workflow_section_stale(doc, slate_md)
        if stale:
            add("slate-md-workflow-stale", "setup", stale,
                [ASK + "SLATE.md's ## Workflow section doesn't match the board's states and rules; regenerate it? "
                       f"If yes, replace that section with the output of: {CMD} workflow --markdown"])
    if slate_md.is_file():
        m = re.search(r"^\s*[-*]?\s*Python:\s*`([^`]+)`", slate_md.read_text(encoding="utf-8"), re.M)
        if not m:
            add("python-cmd-missing", "setup", "SLATE.md doesn't say which command runs Python (a line "
                                               "Python: `python3`)", ["/slate:upgrade   (detects it and writes the line)"])
        elif not shutil.which(m.group(1).split()[0]):
            add("python-cmd-missing", "setup", f"SLATE.md says Python is started with `{m.group(1)}`, but that "
                                               "command isn't found here", ["/slate:upgrade   (detects it again)"])
    top = git(["rev-parse", "--show-toplevel"], HERE)
    if top is not None:
        root = Path(top)
        rel_t = repo_rel(TICKETS, root)
        attr = git(["check-attr", "merge", "--", rel_t], root) or ""
        if not attr.endswith(": slate") or git(["config", "--get", "merge.slate.driver"], root) is None:
            add("merge-driver-missing", "setup", "the Slate merge driver isn't installed in this clone "
                                         "(git would merge tickets.json line by line)", [f"{CMD} install-merge-driver"])
        paths = [repo_rel(HERE / n, root) for n in GITIGNORED]
        ignored = set((git(["check-ignore", "--no-index", "--", *paths], root) or "").splitlines())
        missing = [p for p in paths if p not in ignored]
        if missing:
            add("gitignore-missing", "setup", ".gitignore doesn't cover " + ", ".join(missing),
                ["/slate:upgrade   (adds kanban/.slate-unlock*.json, kanban/.slate-write.lock, "
                 "kanban/.slate-serve.json and kanban/.slate-serve.log to .gitignore)"])
        remotes = (git(["remote"], root) or "").split()
        if remotes and doc is not None and not meta_of(doc).get("repo_url"):
            url = git(["remote", "get-url", "origin" if "origin" in remotes else remotes[0]], root) or ""
            add("repo-url-missing", "setup", "meta.repo_url isn't set, but this repo has a git remote (the board uses it to "
                                     "link commits)", [f"{CMD} set-meta repo_url={web_url(url) or 'https://github.com/OWNER/REPO'}"])
        if doc is not None:
            b = behind_default(doc)
            if b:
                ref, lack = b
                add("board-behind", "tickets", f"the board on {ref} has changes this board lacks: " + "; ".join(lack[:5])
                    + (f"; +{len(lack) - 5} more" if len(lack) > 5 else ""),
                    [f"{CMD} diff {ref}", f"{CMD} sync --from {ref} --dry-run"], ref=ref)
    rec = lock_info()
    if rec is not None:
        stale, why = lock_stale(rec)
        if stale:
            add("write-lock-stale", "setup", f"a stale write lock is left behind ({why}; {lock_holder(rec)})",
                [f"{CMD} unlock-write"])
    for msg in unlock_state():
        add("unlock-active", "setup", msg, [f"{CMD} lock   (cancels it if it's no longer needed)"])
    return probs


OWN_BRIEF = ("plugin-outdated", "write-lock-stale", "unlock-active")  # setup codes /slate:upgrade doesn't fix


def doctor_brief(probs: Sequence[Dict[str, Any]], prefix: str = "Slate: ") -> str:
    parts: List[str] = []
    setup = [p for p in probs if p["kind"] == "setup" and p["code"] not in OWN_BRIEF]
    if setup:
        parts.append(f"{len(setup)} setup issue{'s' if len(setup) != 1 else ''} — run /slate:upgrade")
    for p in probs:
        code = p["code"]
        if code == "plugin-outdated":
            parts.append("board newer than plugin — update the Slate plugin")
        elif code == "board-behind":
            parts.append(f"board behind {p['ref']} — run /slate:sync")
        elif code == "board-errors":
            parts.append(f"board has {p['count']} error{'s' if p['count'] != 1 else ''} — run /slate:sync")
        elif code == "board-unreadable":
            parts.append("tickets.json can't be read — run /slate:sync")
        elif code == "write-lock-stale":
            parts.append(f"stale write lock — run {CMD} unlock-write")
        elif code == "unlock-active":
            parts.append(f"unlock active or requested — {CMD} lock cancels it")
    return prefix + (" · ".join(dict.fromkeys(parts)) if parts else "healthy")


def cmd_doctor(a: argparse.Namespace) -> int:
    found = doctor_problems(a.against)
    notes = [p for p in found if p.get("info")]      # things to know, not problems (e.g. settings ignored by git)
    probs = [p for p in found if not p.get("info")]
    if a.json:
        print(json.dumps({"ok": not probs, "problems": probs, "notes": notes}, indent=2, ensure_ascii=False))
    elif a.brief:
        print(doctor_brief(probs))
    else:
        for p in probs:
            print(f"problem ({p['kind']}): {p['message']}")
            for ln in fix_lines(p["fix"]):
                print(ln)
        for p in notes:
            print(f"note: {p['message']}")
            for ln in fix_lines(p["fix"]):
                print(ln)
        n = len(probs)
        print(f"not ok: {n} problem{'s' if n != 1 else ''}" if n else "ok: no problems found")
    return 1 if probs else 0


# --------------------------------------------------------------------------- statuses: roles, labels, paths

status_text = slabel

# workflow=strict: which roles may come right before each role (moving forward)
STRICT_PREV = {"in_progress": ("backlog", "ready"), "review": ("in_progress",), "user_testing": ("review",),
               "merge_ready": ("user_testing", "review"), "done": ("merge_ready",)}


def status_meta_map(meta: Dict[str, Any], key: str) -> Dict[str, Any]:
    v = meta.get(key)
    return v if isinstance(v, dict) else {}


NOTE_VALUES = ("required", "optional")


def note_default(r: Optional[str]) -> str:
    """A role's own handoff-note rule: required for review, user_testing, merge_ready and done."""
    return "required" if r in HANDOFF_REQUIRED else "optional"


def note_rule(doc: Dict[str, Any], status: str) -> str:
    """required / optional: meta.status_note[status] when set, else from the status's role."""
    v = status_meta_map(meta_of(doc), "status_note").get(status)
    return v if v in NOTE_VALUES else note_default(roles_of(doc).get(status) if status in statuses_of(doc) else role(status))


def note_required(doc: Dict[str, Any], status: str) -> bool:
    return note_rule(doc, status) == "required"


def set_note_rule(meta: Dict[str, Any], name: str, value: Optional[str]) -> None:
    sn = dict(status_meta_map(meta, "status_note"))
    if value is None:
        sn.pop(name, None)
    else:
        sn[name] = value
    if sn:
        ordered_set(meta, "status_note", sn, META_ORDER)
    else:
        meta.pop("status_note", None)


def validate_status_meta(meta: Dict[str, Any], statuses: Sequence[str], err: Any, warn: Any) -> None:
    """meta.status_roles / status_labels / status_from, and the role invariants (as warnings; the
    status commands refuse to break them)."""
    known = set(statuses)
    for key, what in (("status_roles", "{status: role}"), ("status_labels", "{status: \"Label\"}"),
                      ("status_from", "{status: [previous statuses]}"),
                      ("status_note", "{status: \"required\"|\"optional\"}")):
        if key in meta and not isinstance(meta[key], dict):
            err("meta", key, f"must be an object {what}", [restore_fix(f"meta.{key}")])
    for s, r in status_meta_map(meta, "status_roles").items():
        if s not in known:
            err("meta", "status_roles", f"'{s}' is not one of meta.statuses", [restore_fix(f"meta.status_roles.{s}")])
        elif r not in ROLES:
            err("meta", "status_roles", f"{s}: role '{r}' must be one of {', '.join(ROLES)}",
                [f"{CMD} edit-status {s} role=ROLE   (ROLE one of: {', '.join(ROLES)})"])
    for s, lab in status_meta_map(meta, "status_labels").items():
        if s not in known:
            err("meta", "status_labels", f"'{s}' is not one of meta.statuses", [restore_fix(f"meta.status_labels.{s}")])
        elif not isinstance(lab, str):
            err("meta", "status_labels", f"{s}: the label must be text", [f"{CMD} edit-status {s} label=\"...\""])
    for s, v in status_meta_map(meta, "status_note").items():
        if s not in known:
            err("meta", "status_note", f"'{s}' is not one of meta.statuses", [restore_fix(f"meta.status_note.{s}")])
        elif v not in NOTE_VALUES:
            err("meta", "status_note", f"{s}: must be required or optional",
                [f"{CMD} edit-status {s} note=required   (or note=optional)"])
    for s, prev in status_meta_map(meta, "status_from").items():
        if s not in known:
            err("meta", "status_from", f"'{s}' is not one of meta.statuses", [f"{CMD} set-meta workflow=free"])
        elif not (is_str_list(prev) and all(x in known for x in prev)):
            err("meta", "status_from", f"{s}: must be a list of existing statuses",
                [f"{CMD} edit-status {s} from=STATUS,STATUS   (or from= to clear it)"])
    if not statuses:
        return
    sr = status_meta_map(meta, "status_roles")
    rm = {s: (sr.get(s) if sr.get(s) in ROLES else (s if s in ROLES else None)) for s in statuses}
    dones = [s for s in statuses if rm[s] == "done"]
    if not dones:
        warn("meta", "statuses", "no status has the done role, so nothing can be finished",
             [f"{CMD} add-status done --after {statuses[-1]} --like done"])
    elif len(dones) > 1:
        warn("meta", "statuses", f"several statuses have the done role ({', '.join(dones)})",
             [f"{CMD} edit-status {dones[-1]} role=ROLE   (if one of them shouldn't count as done)"])
    if not any(rm[s] in READY_STATUSES for s in statuses):
        warn("meta", "statuses", "no status has the backlog or ready role, so no ticket is ever ready",
             [f"{CMD} add-status backlog --first --like backlog"])


def new_status(doc: Dict[str, Any], as_draft: bool) -> str:
    """The status a new ticket starts in: the first draft-role status, else the first backlog/ready one."""
    s = status_for_role(doc, "draft") if as_draft else status_for_role(doc, "backlog", "ready")
    if s is None:
        if as_draft:
            raise Refused("meta statuses: no status has the draft role, so a draft can't be saved",
                          fix=[f"{CMD} add-status draft --first --like draft",
                               "re-run without --draft / --as-draft (the ticket then needs every field)"])
        raise Refused("meta statuses: no status has the backlog or ready role, so a new ticket has nowhere to go",
                      fix=[f"{CMD} add-status backlog --first --like backlog"])
    return s


def workflow_name(doc: Dict[str, Any]) -> str:
    sf = {k: v for k, v in status_meta_map(meta_of(doc), "status_from").items() if v}
    if not sf:
        return "free"
    return "strict" if sf == strict_rules(doc) else "custom"


def strict_rules(doc: Dict[str, Any]) -> Dict[str, List[str]]:
    rm = roles_of(doc)
    present = {r for r in rm.values() if r}

    def prev_names(r: str, seen: Set[str]) -> List[str]:
        out: List[str] = []
        for pr in STRICT_PREV.get(r, ()):
            if pr in present:
                out.extend(s for s in statuses_of(doc) if rm.get(s) == pr)
            elif pr not in seen:  # a missing step: allow what would have come before it
                out.extend(prev_names(pr, seen | {pr}))
        return list(dict.fromkeys(out))

    rules: Dict[str, List[str]] = {}
    for s in statuses_of(doc):
        r = rm.get(s)
        if r in STRICT_PREV:
            prev = prev_names(r, {r})
            if prev:
                rules[s] = prev
    return rules


def apply_workflow(doc: Dict[str, Any], name: str) -> None:
    meta = doc["meta"]
    if name == "free":
        meta.pop("status_from", None)
    else:
        ordered_set(meta, "status_from", strict_rules(doc), META_ORDER)


def status_setup(doc: Dict[str, Any]) -> Dict[str, Any]:
    rm = roles_of(doc)
    sf = status_meta_map(meta_of(doc), "status_from")
    return {"workflow": workflow_name(doc),
            "statuses": [{"name": s, "role": rm.get(s), "label": slabel(s), "from": sf.get(s) or [],
                          "note": note_rule(doc, s)} for s in statuses_of(doc)]}


def allowed_from(doc: Dict[str, Any], target: str) -> List[str]:
    v = status_meta_map(meta_of(doc), "status_from").get(target)
    return list(v) if is_str_list(v) else []


def move_allowed(doc: Dict[str, Any], prev: str, target: str) -> bool:
    """Path rules only restrict forward moves (later in meta.statuses)."""
    sts = statuses_of(doc)
    if prev == target or prev not in sts or target not in sts or sts.index(target) < sts.index(prev):
        return True
    allowed = allowed_from(doc, target)
    return not allowed or prev in allowed


def next_step(doc: Dict[str, Any], prev: str, target: str) -> Optional[str]:
    """First status on the shortest allowed forward path from prev to target (None if there is none)."""
    sts = statuses_of(doc)
    if prev not in sts or target not in sts:
        return None
    lo, hi = sts.index(prev), sts.index(target)
    frontier = [(prev, None)]
    seen = {prev}
    while frontier:
        nxt = []
        for cur, first in frontier:
            for s in sts[sts.index(cur) + 1: hi + 1]:
                if s in seen or not move_allowed(doc, cur, s) or sts.index(s) <= lo:
                    continue
                f = first or s
                if s == target:
                    return f
                seen.add(s)
                nxt.append((s, f))
        frontier = nxt
    return None


def check_path(doc: Dict[str, Any], t: Dict[str, Any], target: str, note: str) -> None:
    """Enforce meta.status_from for an explicit `set`: forward moves need an allowed previous status;
    backward moves need a handoff note (only while path rules are set)."""
    prev = t.get("status")
    tid = t.get("id")
    sts = statuses_of(doc)
    if not isinstance(prev, str) or prev == target or prev not in sts or target not in sts:
        return
    if not any(status_meta_map(meta_of(doc), "status_from").values()):
        return
    if sts.index(target) < sts.index(prev):
        if not note:
            raise Refused(f"{tid} status: moving back {slabel(prev)} → {slabel(target)} needs a reason",
                          fix=[f"{CMD} set {tid} {target} --handoff \"why it goes back\""])
        return
    if move_allowed(doc, prev, target):
        return
    allowed = allowed_from(doc, target)
    step = next_step(doc, prev, target)
    hq = shlex.quote(note) if note else "\"...\""
    fix = ([f"{CMD} set {tid} {step} --handoff {hq}   (the next allowed step toward {target})"] if step else [])
    fix += [ASK + f"should {tid} skip straight to {target}? If so, change the rule: "
                  f"{CMD} edit-status {target} from={','.join(allowed + [prev])}   (or {CMD} set-meta workflow=free)"]
    raise Refused(f"{tid} status: can't move {slabel(prev)} → {slabel(target)}",
                  [Issue(f"{slabel(target)} can only be reached from: {', '.join(slabel(x) for x in allowed)}", "", "")],
                  fix=fix)


def status_invariants(doc: Dict[str, Any]) -> List[str]:
    rm = roles_of(doc)
    sts = statuses_of(doc)
    out: List[str] = []
    if not any(rm.get(s) == "done" for s in sts):
        out.append("at least one status must keep the done role")
    if not any(rm.get(s) in READY_STATUSES for s in sts):
        out.append("at least one status must keep the backlog or ready role")
    return out


def commit_statuses(doc: Dict[str, Any], what: str) -> None:
    bad = status_invariants(doc)
    if bad:
        raise Refused(f"meta statuses: {what} would leave the board with " + " and ".join(bad).replace(
            "at least one status must keep", "no status with"),
                      fix=[ASK + "which status should take that role instead? Then: "
                                 f"{CMD} edit-status NAME role=ROLE"])
    commit(doc)


def set_role(meta: Dict[str, Any], name: str, r: str) -> None:
    sr = dict(status_meta_map(meta, "status_roles"))
    if r == name and name in ROLES:
        sr.pop(name, None)
    else:
        sr[name] = r
    if sr:
        ordered_set(meta, "status_roles", sr, META_ORDER)
    else:
        meta.pop("status_roles", None)


def set_label(meta: Dict[str, Any], name: str, lab: Optional[str]) -> None:
    sl = dict(status_meta_map(meta, "status_labels"))
    if lab is None or not lab.strip():
        sl.pop(name, None)
    else:
        sl[name] = lab.strip()
    if sl:
        ordered_set(meta, "status_labels", sl, META_ORDER)
    else:
        meta.pop("status_labels", None)


def find_status(doc: Dict[str, Any], name: str) -> str:
    sts = statuses_of(doc)
    if name in sts:
        return name
    close = get_close_matches(name, sts, n=1)
    raise Refused(f"status {name}: not one of meta.statuses ({', '.join(sts)})",
                  fix=([f"{CMD} " + shlex.join([close[0] if x == name else x for x in RAW_ARGV]) + "   (did you mean this?)"]
                       if close and RAW_ARGV else []) + [f"{CMD} export --json --statuses   (lists them with roles)"])


def cmd_add_status(a: argparse.Namespace) -> int:
    doc = load_for_write()
    meta = doc["meta"]
    sts = statuses_of(doc)
    name = a.name.strip()
    if not STATUS_NAME_RE.match(name):
        good = re.sub(r"[^a-z0-9_]", "_", name.lower()).strip("_") or "status"
        good = good if good[0].isalpha() else "s_" + good
        raise Refused(f"status {name}: a name is lowercase letters, digits or _, starting with a letter (up to 30)",
                      fix=[f"{CMD} add-status {good[:30]} --like {a.like}" + (f" --after {a.after}" if a.after else " --first")])
    if name in sts:
        raise Refused(f"status {name}: already exists", fix=[f"{CMD} edit-status {name} label=\"...\"   (to change it)"])
    like = a.like
    r = like if like in ROLES else (roles_of(doc).get(like) if like in sts else None)
    if r is None:
        raise Refused(f"status {name}: --like {like} is neither a role ({', '.join(ROLES)}) nor a status with a role",
                      fix=[f"{CMD} add-status {name} --like in_progress" + (f" --after {a.after}" if a.after else " --first")])
    if a.first:
        pos = 0
    else:
        pos = sts.index(find_status(doc, a.after)) + 1
    note = a.note or (note_rule(doc, like) if like in sts else note_default(r))  # inherited from --like
    new = list(sts)
    new.insert(pos, name)
    meta["statuses"] = new
    set_role(meta, name, r)
    if a.label:
        set_label(meta, name, a.label)
    if a.note or note != note_default(r):
        set_note_rule(meta, name, note)
    use_roles(doc)
    commit_statuses(doc, f"adding {name}")
    print(f"Added status {name} (role {r}" + (f", label {a.label.strip()}" if a.label else "")
          + f", handoff note {note}): " + " → ".join(new))
    return 0


def cmd_rename_status(a: argparse.Namespace) -> int:
    doc = load_for_write()
    meta = doc["meta"]
    old = find_status(doc, a.old)
    new = a.new.strip()
    if not STATUS_NAME_RE.match(new):
        raise Refused(f"status {new}: a name is lowercase letters, digits or _, starting with a letter (up to 30)",
                      fix=[f"{CMD} rename-status {old} {re.sub(r'[^a-z0-9_]', '_', new.lower())[:30] or 'new_name'}"])
    if new == old:
        print(f"Status {old} already has that name; nothing changed.")
        return 0
    if new in statuses_of(doc):
        raise Refused(f"status {new}: already exists",
                      fix=[f"{CMD} remove-status {old} --move-to {new}   (to merge {old} into {new})"])
    r = roles_of(doc).get(old)
    lab = status_meta_map(meta, "status_labels").get(old)
    meta["statuses"] = [new if s == old else s for s in statuses_of(doc)]
    sr = {(new if k == old else k): v for k, v in status_meta_map(meta, "status_roles").items()}
    if sr:
        meta["status_roles"] = sr
    if r:
        set_role(meta, new, r)
    if lab is not None:
        set_label(meta, new, lab)
    sl = {k: v for k, v in status_meta_map(meta, "status_labels").items() if k != old}
    if "status_labels" in meta:
        if sl:
            meta["status_labels"] = sl
        else:
            meta.pop("status_labels")
    sf = status_meta_map(meta, "status_from")
    if sf:
        meta["status_from"] = {(new if k == old else k): [new if x == old else x for x in v] for k, v in sf.items()}
    sn = status_meta_map(meta, "status_note")
    if sn:
        meta["status_note"] = {(new if k == old else k): v for k, v in sn.items()}
    moved = [t for t in tickets_of(doc) if t.get("status") == old]
    for t in moved:
        t["status"] = new
    use_roles(doc)
    commit_statuses(doc, f"renaming {old}")
    print(f"Renamed status {old} to {new}; {len(moved)} ticket{'s' if len(moved) != 1 else ''} moved with it "
          "(history notes keep the old name).")
    return 0


def cmd_edit_status(a: argparse.Namespace) -> int:
    ex = f"{CMD} edit-status {a.name} label=\"In progress\" role=in_progress from=backlog,ready note=optional"
    changes: Dict[str, str] = {}
    for item in a.assignments:
        if "=" not in item:
            raise UsageError(f"edit-status: '{item}' should be label=..., role=..., from=a,b or note=required|optional",
                             fix=[ex])
        k, v = item.split("=", 1)
        if k not in ("label", "role", "from", "note"):
            raise Refused(f"status {a.name} {k}: not a status setting (label, role, from, note)", fix=[ex])
        changes[k] = v
    if not changes:
        raise UsageError("edit-status: give label=..., role=..., from=a,b and/or note=required|optional", fix=[ex])
    if "note" in changes and changes["note"].strip() not in NOTE_VALUES:
        raise Refused(f"status {a.name} note: '{changes['note']}' must be required or optional",
                      fix=[f"{CMD} edit-status {a.name} note=required   (a handoff note is needed to move here)",
                           f"{CMD} edit-status {a.name} note=optional"])
    doc = load_for_write()
    meta = doc["meta"]
    name = find_status(doc, a.name)
    if "role" in changes:
        r = changes["role"].strip()
        if r not in ROLES:
            raise Refused(f"status {name} role: '{r}' must be one of {', '.join(ROLES)}",
                          fix=[f"{CMD} edit-status {name} role=ROLE   (ROLE one of: {', '.join(ROLES)})"])
        set_role(meta, name, r)
    if "label" in changes:
        set_label(meta, name, changes["label"])
    if "note" in changes:
        set_note_rule(meta, name, changes["note"].strip())
    if "from" in changes:
        prev = parse_csv(changes["from"])
        for x in prev:
            find_status(doc, x)
        sf = dict(status_meta_map(meta, "status_from"))
        if prev:
            sf[name] = prev
        else:
            sf.pop(name, None)
        if sf:
            ordered_set(meta, "status_from", sf, META_ORDER)
        else:
            meta.pop("status_from", None)
    use_roles(doc)
    if "role" in changes:
        errors = validate(doc)[0]
        blocked = write_blockers(errors)
        if blocked:
            hit = sorted({e.where for e in blocked[1] if e.where in by_id(doc)})
            raise Refused(f"status {name} role: changing it to {changes['role']} would make "
                          f"{', '.join(hit) or 'the board'} invalid (nothing was changed):", blocked[1],
                          fix=[f"{CMD} set TICKET OTHER_STATUS   (move those tickets out of {name} first)"])
    commit_statuses(doc, f"changing {name}")
    print(f"Status {name}: " + ", ".join(f"{k} = {v or '(cleared)'}" for k, v in changes.items()))
    return 0


def cmd_reorder_statuses(a: argparse.Namespace) -> int:
    doc = load_for_write()
    have = statuses_of(doc)
    given = [x for arg in a.names for x in parse_csv(arg)]
    dups = sorted({x for x in given if given.count(x) > 1})
    unknown = [x for x in given if x not in have]
    missing = [x for x in have if x not in given]
    if dups or unknown or missing:
        problems = ([f"listed twice: {', '.join(dups)}"] if dups else []) \
            + ([f"not a status: {', '.join(unknown)}"] if unknown else []) \
            + ([f"missing: {', '.join(missing)}"] if missing else [])
        order = [x for x in dict.fromkeys(given) if x in have] + missing
        raise Refused(f"meta statuses: list every status exactly once ({'; '.join(problems)})",
                      fix=[f"{CMD} reorder-statuses {' '.join(order)}"])
    doc["meta"]["statuses"] = given
    commit_statuses(doc, "reordering")
    print("Statuses now: " + " → ".join(slabel(s) for s in given))
    return 0


def cmd_remove_status(a: argparse.Namespace) -> int:
    doc = load_for_write()
    meta = doc["meta"]
    name = find_status(doc, a.name)
    users = by_rank(t for t in tickets_of(doc) if t.get("status") == name)
    others = [s for s in statuses_of(doc) if s != name]
    if users and a.move_to is None:
        ids = ", ".join(str(t.get("id")) for t in users[:5]) + (" ..." if len(users) > 5 else "")
        guess = next((s for s in others if roles_of(doc).get(s) == roles_of(doc).get(name)), others[0] if others else "OTHER")
        raise Refused(f"status {name}: {len(users)} ticket{'s are' if len(users) != 1 else ' is'} in it ({ids})",
                      fix=[f"{CMD} remove-status {name} --move-to {guess}   (moves them, then removes it)",
                           ASK + f"tickets are still in {name}; which status should they move to?"])
    if a.move_to is not None:
        target = find_status(doc, a.move_to)
        if target == name:
            raise Refused(f"status {name}: --move-to must name a different status",
                          fix=[f"{CMD} remove-status {name} --move-to OTHER"])
        for t in users:
            t["status"] = target
            apply_claim(t, target, None)
    meta["statuses"] = others
    for key in ("status_roles", "status_labels", "status_note"):
        m = {k: v for k, v in status_meta_map(meta, key).items() if k != name}
        if m:
            meta[key] = m
        else:
            meta.pop(key, None)
    notes: List[str] = []
    sf = status_meta_map(meta, "status_from")
    if sf:
        nsf: Dict[str, Any] = {}
        for k, v in sf.items():
            if k == name:
                continue
            if name in v:
                notes.append(f"dropped {name} from the statuses {k} can be reached from")
            v2 = [x for x in v if x != name]
            if v2:
                nsf[k] = v2
        if nsf:
            meta["status_from"] = nsf
        else:
            meta.pop("status_from")
    use_roles(doc)
    commit_statuses(doc, f"removing {name}")
    print(f"Removed status {name}" + (f"; moved {len(users)} ticket{'s' if len(users) != 1 else ''} to {a.move_to}"
                                      if users else "") + ".")
    for n in notes:
        print(f"  note: {n}")
    if roles_of(doc) and not status_for_role(doc, "draft"):
        print(f"  note: no status has the draft role now; new --draft refuses until one is added "
              f"({CMD} add-status draft --first --like draft)")
    return 0


# --------------------------------------------------------------------------- remove / restore, unlink, note


def cmd_remove(a: argparse.Namespace) -> int:
    ids = split_ids(a.id, "remove")
    reason = (a.reason or "").strip()
    if not reason:
        raise Refused(f"{ids[0]} removed: --reason is required (it is kept with the archived ticket)",
                      fix=[f"{CMD} remove {a.id} --reason \"why it is dropped\""])
    doc = load_for_write()
    live = by_id(doc)
    for tid in ids:
        find(doc, tid)
    problems: List[Issue] = []
    for tid in ids:
        t = live[tid]
        if role(t.get("status")) == "done" and a.force_done is None:
            problems.append(Issue(tid, "status", "is done; removing finished work needs a reason of its own",
                                  [ASK + f"remove the finished ticket {tid}? If yes: "
                                         f"{CMD} remove {a.id} --reason {shlex.quote(reason)} --force-done \"why\""]))
        users = [u["id"] for u in by_rank(live.values()) if tid in deps_of(u) and u["id"] not in ids]
        if users and not a.detach:
            problems.append(Issue(tid, "depends_on", f"{', '.join(users)} depend{'s' if len(users) == 1 else ''} on it",
                                  [f"{CMD} remove {a.id} --reason {shlex.quote(reason)} --detach   "
                                   f"(drops {tid} from their depends_on; noted in their history)",
                                   ASK + f"should {', '.join(users)} still wait for {tid}'s work in another ticket?"]))
    if a.force_done is not None and not a.force_done.strip():
        problems.append(Issue(ids[0], "status", "--force-done needs a reason", [f"{CMD} remove {a.id} --reason "
                                                                               f"{shlex.quote(reason)} --force-done \"why\""]))
    if problems:
        raise Refused(f"nothing was removed ({len(ids)} ticket{'s' if len(ids) != 1 else ''} asked for):", problems)
    archive = removed_of(doc)
    detached: List[str] = []
    for tid in ids:
        t = live[tid]
        for u in tickets_of(doc):
            if u.get("id") not in ids and tid in deps_of(u):
                ordered_set(u, "depends_on", [d for d in deps_of(u) if d != tid])
                add_handoff(u, f"Dependency {tid} was removed: {reason}")
                detached.append(f"{u['id']} no longer waits for {tid}")
        entry: Dict[str, Any] = {"ticket": t, "removed": today(), "reason": reason}
        if a.force_done:
            entry["force_done"] = a.force_done.strip()
        archive.append(entry)
    doc["tickets"] = [t for t in doc["tickets"] if not (isinstance(t, dict) and t.get("id") in ids)]
    ordered_set(doc["meta"], "removed", archive, META_ORDER)
    recompute_unlocks(doc)
    commit(doc)
    print(f"Removed {', '.join(ids)} (archived in meta.removed; bring back with: {CMD} restore ID).")
    for d in detached:
        print(f"  {d}")
    return 0


def cmd_restore(a: argparse.Namespace) -> int:
    doc = load_for_write()
    archive = removed_of(doc)
    hits = [i for i, x in enumerate(archive) if x["ticket"].get("id") == a.id]
    if not hits:
        gone = [str(x["ticket"].get("id")) for x in archive]
        raise Refused(f"{a.id} removed: not in the archive (removed: {', '.join(gone) or 'none'})",
                      fix=[f"{CMD} export --json --removed   (lists removed tickets)"])
    if a.id in by_id(doc):
        raise Refused(f"{a.id} id: a live ticket already has this id", fix=[f"{CMD} show {a.id}"])
    idx = hits[-1]
    entry = archive[idx]
    t = copy.deepcopy(entry["ticket"])
    used = {rank_of(x) for x in tickets_of(doc)}
    if not (is_int(t.get("rank")) and t["rank"] not in used and t["rank"] >= 1):
        t["rank"] = max((r for r in used if r < 10 ** 9), default=0) + 1
    missing = [d for d in deps_of(t) if d not in by_id(doc)]
    if missing:
        raise Refused(f"{a.id} depends_on: needs {', '.join(missing)}, which {'is' if len(missing) == 1 else 'are'} "
                      "not on the board", fix=[f"{CMD} restore {missing[0]}   (restore it first)",
                                               ASK + f"should {a.id} come back without waiting for {', '.join(missing)}?"])
    doc["tickets"].append(t)
    del archive[idx]
    if archive:
        doc["meta"]["removed"] = archive
    else:
        doc["meta"].pop("removed", None)
    add_handoff(t, f"Restored (removed {entry.get('removed', '?')}: {entry.get('reason', '')})")
    recompute_unlocks(doc)
    rerank_after_deps(doc, [a.id])
    commit(doc, header=f"not restored: {a.id} would leave the board invalid:")
    print(line(t))
    print(f"Restored {a.id} at rank {t['rank']}.")
    return 0


def cmd_unlink(a: argparse.Namespace) -> int:
    ids = split_ids(a.id, "unlink")
    if not a.commit and not a.pr:
        raise UsageError("unlink: give --commit SHA_OR_PREFIX (repeatable) and/or --pr",
                         fix=[f"{CMD} unlink {a.id} --commit abc1234", f"{CMD} unlink {a.id} --pr"])
    doc = load_for_write()

    def one(d: Dict[str, Any], tid: str) -> List[str]:
        t = find(d, tid)
        out: List[str] = []
        commits = [c for c in t.get("commits", []) if isinstance(c, dict)] if isinstance(t.get("commits"), list) else []
        for ref in a.commit or []:
            ref = ref.strip().lower()
            hit = [c for c in commits if isinstance(c.get("sha"), str) and len(ref) >= 4 and same_sha(c["sha"], ref)]
            if not hit:
                raise Refused(f"{tid} commits: no linked commit matches '{ref}'",
                              fix=[f"{CMD} show {tid}   (see the linked commits)"])
            if len(hit) > 1:
                raise Refused(f"{tid} commits: '{ref}' matches {len(hit)} commits; give more of the sha",
                              fix=[f"{CMD} unlink {tid} --commit {hit[0]['sha']}"])
            commits = [c for c in commits if c is not hit[0]]
            out.append(f"commit {hit[0]['sha'][:7]}")
        if a.commit:
            if commits:
                ordered_set(t, "commits", commits)
            else:
                t.pop("commits", None)
        if a.pr:
            pr = t.pop("pr", None)
            if not isinstance(pr, dict):
                raise Refused(f"{tid} pr: no pull request is linked", fix=[f"{CMD} show {tid}"])
            out.append(f"PR {pr.get('url')}")
        add_handoff(t, "Unlinked " + ", ".join(out) + (f": {a.reason.strip()}" if a.reason and a.reason.strip() else ""))
        commit(d, write=False)
        return out

    if len(ids) == 1:
        reports = [one(doc, ids[0])]
    else:
        doc, reports = bulk(doc, ids, one, "be unlinked")
    write_board(doc)
    for tid, r in zip(ids, reports):
        print(f"{tid}: unlinked " + ", ".join(r))
    return 0


def cmd_note(a: argparse.Namespace) -> int:
    ids = split_ids(a.id, "note")
    text = (a.text or "").strip()
    if not text:
        raise UsageError("note: give the note text", fix=[f"{CMD} note {a.id} \"what happened\""])
    doc = load_for_write()

    def one(d: Dict[str, Any], tid: str) -> None:
        add_handoff(find(d, tid), text)
        commit(d, write=False)

    if len(ids) == 1:
        one(doc, ids[0])
    else:
        doc, _ = bulk(doc, ids, one, "take a note")
    write_board(doc)
    ts = by_id(doc)
    for tid in ids:
        print(f"{tid} ({ts[tid].get('status')}): noted.")
    return 0


# --------------------------------------------------------------------------- flow: the transitions actually used


FLOW_SUGGEST_SHARE = 0.10  # suggested_from keeps previous states seen in at least this share of moves


def ticket_path(doc: Dict[str, Any], t: Dict[str, Any]) -> List[str]:
    """The statuses one ticket went through, from its handoff history: where it started, every note's
    status, then its current status (repeats, i.e. notes without a move, collapse). It started as a draft
    when its first note is in a backlog/ready status (it was promoted), else in the first backlog/ready
    status. Moves made without a note (e.g. to in_progress) are only seen through the current status."""
    rm = roles_of(doc)
    hs = [str(h["status"]) for h in handoffs_of(t) if isinstance(h.get("status"), str)]
    cur = t.get("status") if isinstance(t.get("status"), str) else None
    first = hs[0] if hs else cur
    draft = status_for_role(doc, "draft")
    start = draft if draft and (first == draft or (hs and rm.get(first) in READY_STATUSES)) \
        else (status_for_role(doc, "backlog", "ready") or "backlog")
    seq: List[str] = []
    for s in [start] + hs + ([cur] if cur else []):
        if not seq or seq[-1] != s:
            seq.append(s)
    return seq


def flow_data(doc: Dict[str, Any]) -> Dict[str, Any]:
    sts = statuses_of(doc)
    counts: Dict[Tuple[str, str], int] = {}
    tickets = tickets_of(doc)
    for t in tickets:
        p = ticket_path(doc, t)
        for x, y in zip(p, p[1:]):
            counts[(x, y)] = counts.get((x, y), 0) + 1

    def pos(s: str) -> int:
        return sts.index(s) if s in sts else len(sts)

    def forward(x: str, y: str) -> bool:
        return x in sts and y in sts and sts.index(y) > sts.index(x)

    order = sorted(counts.items(), key=lambda kv: (-kv[1], pos(kv[0][0]), pos(kv[0][1]), kv[0]))
    into: Dict[str, Dict[str, int]] = {}
    for (x, y), n in counts.items():
        if forward(x, y):
            into.setdefault(y, {})[x] = into.setdefault(y, {}).get(x, 0) + n
    suggested: Dict[str, List[str]] = {}
    for y in sts:
        seen = into.get(y)
        if not seen:
            continue
        total = sum(seen.values())
        keep = [x for x in sts if seen.get(x, 0) and seen[x] / total >= FLOW_SUGGEST_SHARE - 1e-9]
        if keep:
            suggested[y] = keep
    return {"tickets": len(tickets),
            "transitions": [{"from": x, "to": y, "count": n, "backward": not forward(x, y) and x in sts and y in sts}
                            for (x, y), n in order],
            "suggested_from": suggested}


def cmd_flow(a: argparse.Namespace) -> int:
    doc = read_board()
    data = flow_data(doc)
    if a.json:
        print(json.dumps(data, indent=2, ensure_ascii=False))
        return 0
    tr = data["transitions"]
    if not tr:
        print(f"No status changes recorded yet ({data['tickets']} tickets). Moves show up here once tickets "
              "have handoff notes.")
        return 0
    print(f"Status transitions used ({data['tickets']} tickets, from their handoff history):")
    width = max(len(f"{x['from']} → {x['to']}") for x in tr)
    for x in tr:
        arrow = f"{x['from']} → {x['to']}"
        print(f"  {arrow.ljust(width)}  {x['count']}" + ("   (backward)" if x["backward"] else ""))
    sug = data["suggested_from"]
    if sug:
        print(f"\nSuggested rules (previous states seen in at least {int(FLOW_SUGGEST_SHARE * 100)}% of the forward "
              "moves into each state):")
        for s, prev in sug.items():
            print(f"  {s}: from {', '.join(prev)}   ({CMD} edit-status {s} from={','.join(prev)})")
    print("\nMoves made without a note (often into in_progress) only show through each ticket's current status.")
    return 0


# --------------------------------------------------------------------------- workflow: SLATE.md's ## Workflow section


ROLE_MEANING = {
    "draft": "An idea being shaped; not ready to build. `promote` moves it on once every field is filled in.",
    "backlog": "Planned and fully written; waits for its dependencies. `next` offers the lowest-rank ready ticket.",
    "ready": "Approved to start; `next` offers it like the backlog.",
    "in_progress": "Being built. Moving here claims the ticket for the current branch.",
    "review": "Built and tested; the review runs.",
    "user_testing": "Waiting for a person to try the user tests by hand (`usertest ID N pass|fail`).",
    "merge_ready": "Reviewed, required user tests passed, commit and PR linked; waiting for the PR to be merged.",
    "done": "Finished: the PR is merged (or closed without one, with the user's OK).",
}
CUSTOM_MEANING = "A project state with no built-in rules."
WORKFLOW_RE = re.compile(r"^##\s+Workflow\s*$")


def md_cell(s: Any) -> str:
    return " ".join(str(s).split()).replace("|", "\\|")


def slate_md_python(slate_md: Path) -> Optional[str]:
    try:
        text = slate_md.read_text(encoding="utf-8")
    except OSError:
        return None
    m = re.search(r"^\s*[-*]?\s*Python:\s*`([^`]+)`", text, re.M)
    return m.group(1).strip() if m else None


def workflow_markdown(doc: Dict[str, Any]) -> str:
    """SLATE.md's ## Workflow section, generated from the board (and committed git settings) only, so
    every clone generates the same text."""
    use_roles(doc)
    py = slate_md_python(HERE.parent / "SLATE.md") or PY
    cmd = f"{py} kanban/board.py"
    rm = roles_of(doc)
    sts = statuses_of(doc)
    sf = status_meta_map(meta_of(doc), "status_from")
    out = ["## Workflow",
           "<!-- generated by `board.py workflow --markdown`; regenerate it (with the user's OK) after changing "
           "states, rules or phases -->",
           "",
           "| State | Column title | Role | Handoff note | Meaning | Allowed from |",
           "|---|---|---|---|---|---|"]
    for s in sts:
        r = rm.get(s)
        frm = sf.get(s) if is_str_list(sf.get(s)) else []
        out.append(f"| `{s}` | {md_cell(slabel(s))} | {r or '(none)'} | {note_rule(doc, s)} | "
                   f"{ROLE_MEANING.get(r or '', CUSTOM_MEANING)} | "
                   + (", ".join(f"`{x}`" for x in frm) if frm else "any") + " |")
    out.append("")
    wf = workflow_name(doc)
    wf_text = {"free": "no transition rules: any move is allowed",
               "strict": "forward moves follow the usual path (Allowed from above); moving back needs a handoff note",
               "custom": "forward moves follow this project's rules (Allowed from above); moving back needs a "
                         "handoff note"}[wf]
    out.append(f"- Workflow: **{wf}** — {wf_text}. Change it with `{cmd} set-meta workflow=strict|free` or "
               f"`{cmd} edit-status NAME from=A,B`. Always checked: handoff notes (Handoff note above; "
               f"`{cmd} edit-status NAME note=required|optional`), dependencies, required user tests, the merged PR.")
    mr = status_for_role(doc, "merge_ready")
    done = status_for_role(doc, "done") or "done"
    if mr:
        out.append(f"- Merge-ready: after review, required user tests and a linked commit/PR a ticket goes to `{mr}` "
                   f"({md_cell(slabel(mr))}). It becomes `{done}` only once the PR is merged "
                   f"(`{cmd} link ID --pr-state merged`) or the user agrees to `--no-pr \"why\"`.")
    else:
        out.append(f"- Merge-ready: no waiting-for-merge state; `{done}` needs the linked PR merged "
                   f"(`{cmd} link ID --pr-state merged`) or the user's OK for `--no-pr \"why\"`.")
    out.append("- Pull requests: agents open draft PRs and never merge; a person merges, then tells the agent.")
    ut = status_for_role(doc, "user_testing")
    areas = user_test_areas_of(doc)
    out.append("- User tests: "
               + (f"tickets in areas {', '.join(f'`{x}`' for x in areas)} need user tests; " if areas else "")
               + (f"a person tries them in `{ut}` ({md_cell(slabel(ut))}); " if ut else "no user-testing state; ")
               + f"required user tests must pass (`{cmd} usertest ID N pass`) before "
               + (f"`{mr}` / " if mr else "") + f"`{done}`.")
    out.append(f"- Bugs: a bug found in other work becomes its own ticket: `{cmd} new --bug --fixes ID …`; it ranks "
               "just before the ticket it fixes, and that ticket waits for it.")
    later = [str(p.get("id")) for p in phases_display_order(doc) if p.get("unscheduled") is True]
    if later:
        out.append(f"- Unscheduled phases: {', '.join(f'`{x}`' for x in later)} (someday ideas; `next` and `list` "
                   f"skip them; to build one: `{cmd} edit ID phase=PHASE`).")
    else:
        out.append(f"- Unscheduled phases: none (someday ideas go in one: `{cmd} add-phase --id BACKLOG … "
                   "--unscheduled`).")
    top = git(["rev-parse", "--show-toplevel"], HERE)
    if top is None:
        out.append("- Board of record: this folder's `kanban/tickets.json` (not a git repository).")
        out.append("- Merge driver: not a git repository.")
    else:
        ref = default_branch_ref() or "main"
        branch = ref.split("/", 1)[1] if ref.startswith("origin/") else ref
        out.append(f"- Board of record: `kanban/tickets.json` on `{branch}` in the main checkout. Other branches and "
                   f"worktrees compare and bring changes across with `{cmd} diff {branch}` / "
                   f"`{cmd} sync --from {branch}`; `SLATE_BOARD_OF_RECORD` can name another board of record.")
        rel_t = repo_rel(TICKETS, Path(top))
        attr = git(["check-attr", "merge", "--", rel_t], Path(top)) or ""
        if attr.endswith(": slate"):
            out.append(f"- Merge driver: installed (`.gitattributes`: `{rel_t} merge=slate`); every clone runs "
                       f"`{cmd} install-merge-driver` once.")
        else:
            out.append(f"- Merge driver: not installed (`{cmd} install-merge-driver`).")
    out.append(f"- Python: `{py}`")
    out.append(f"- Unlock: hand edits of `kanban/tickets.json` are blocked. When one is truly needed, "
               f"`{cmd} unlock --reason \"…\" --minutes 5` asks the user (approval card in Manual, Accept edits and "
               "Auto mode; otherwise they run it in their own terminal and type the code). One unlock = one edit.")
    return "\n".join(out) + "\n"


def workflow_section(text: str) -> Optional[str]:
    """The ## Workflow section of SLATE.md (heading included, up to the next ## heading), or None."""
    lines = text.splitlines()
    for i, ln in enumerate(lines):
        if WORKFLOW_RE.match(ln):
            end = next((j for j in range(i + 1, len(lines)) if re.match(r"^##\s", lines[j])), len(lines))
            return "\n".join(lines[i:end])
    return None


def workflow_section_stale(doc: Dict[str, Any], slate_md: Path) -> Optional[str]:
    try:
        have = workflow_section(slate_md.read_text(encoding="utf-8"))
    except OSError:
        return None
    if have is None:
        return None
    if " ".join(have.split()) == " ".join(workflow_markdown(doc).split()):
        return None
    return "SLATE.md's ## Workflow section doesn't match the board (states, labels, roles, rules or settings changed)"


def cmd_workflow(a: argparse.Namespace) -> int:
    doc = read_board()
    sys.stdout.write(workflow_markdown(doc))
    return 0


# --------------------------------------------------------------------------- serve: the board page, live


SERVE_FILE = HERE / ".slate-serve.json"   # {pid, host, port, url, started, board_path, slate_version} while running
SERVE_LOG = HERE / ".slate-serve.log"     # output of a background server (serve --ensure)
SERVE_PORT = 8088
SERVE_PORT_TRIES = 20
SERVE_IDLE_HOURS = 8.0
LOOPBACK_NAMES = ("127.0.0.1", "localhost", "::1")
DOCTOR_CACHE_SECONDS = 30.0
VIA_PAGE = "board page"


class NeedsHandoff(Refused):
    code = "needs_handoff"


def board_path_str() -> str:
    return os.path.normcase(str(TICKETS.resolve()))


def is_loopback(host: str) -> bool:
    return host in LOOPBACK_NAMES or host.startswith("127.")


def connect_host(host: str) -> str:
    return "127.0.0.1" if host in ("", "0.0.0.0") else ("::1" if host == "::" else host)


def url_for(host: str, port: int) -> str:
    h = connect_host(host)
    return f"http://[{h}]:{port}/" if ":" in h else f"http://{h}:{port}/"


def can_bind(host: str, port: int) -> bool:
    """Is host:port free right now? Binding is instant everywhere (a refused connect can take
    ~2 s on Windows, which made free ports look busy)."""
    s = socket.socket(socket.AF_INET6 if ":" in (host or "") else socket.AF_INET)
    try:
        if os.name == "nt" and hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
            s.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)  # type: ignore[attr-defined]
        s.bind((host or "127.0.0.1", port))
        return True
    except OSError:
        return False
    finally:
        s.close()


def speaks_http(host: str, port: int, timeout: float = 3.0) -> bool:
    """Does something on host:port answer a plain HTTP request? (Raw socket, no proxies.)"""
    try:
        with socket.create_connection((host if host not in ("", "0.0.0.0", "::") else "127.0.0.1", port),
                                      timeout=timeout) as s:
            s.sendall(b"HEAD / HTTP/1.0\r\nHost: localhost\r\n\r\n")
            return s.recv(16).startswith(b"HTTP/")
    except OSError:
        return False


def probe(url: str, timeout: float = 1.5) -> Tuple[str, Optional[Dict[str, Any]]]:
    """What answers at url: ("slate", info) a Slate board server, ("http", None) some other web server,
    ("busy", None) something that isn't HTTP (or too slow), ("none", None) nothing listening."""
    import http.client
    import urllib.error
    import urllib.request
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        with opener.open(url.rstrip("/") + "/api/info", timeout=timeout) as r:
            body = r.read(2_000_000)
    except urllib.error.HTTPError:
        return "http", None
    except urllib.error.URLError as e:
        reason = e.reason
        if isinstance(reason, ConnectionRefusedError) or getattr(reason, "errno", None) in (61, 111, 10061):
            return "none", None
        return "busy", None
    except ConnectionRefusedError:
        return "none", None
    except (OSError, http.client.HTTPException, ValueError):
        return "busy", None
    try:
        data = json.loads(body.decode("utf-8"))
    except ValueError:
        return "http", None
    if isinstance(data, dict) and data.get("slate") is True:
        return "slate", data
    return "http", None


def same_board(info: Optional[Dict[str, Any]]) -> bool:
    return bool(info) and isinstance(info.get("board_path"), str) \
        and os.path.normcase(info["board_path"]) == board_path_str()


def running_server() -> Optional[Dict[str, Any]]:
    """The runtime file when its process is alive and it serves this board (no network check)."""
    rec = read_record(SERVE_FILE)
    if not rec or not is_int(rec.get("pid")) or not isinstance(rec.get("url"), str):
        return None
    if not isinstance(rec.get("board_path"), str) or os.path.normcase(rec["board_path"]) != board_path_str():
        return None
    return rec if pid_alive(rec["pid"]) else None


def live_server(rec: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """rec when its pid is alive AND /api/info at its url answers for this board."""
    if not rec or not is_int(rec.get("pid")) or not isinstance(rec.get("url"), str) or not pid_alive(rec["pid"]):
        return None
    kind, info = probe(rec["url"])
    return rec if kind == "slate" and same_board(info) else None


def remove_serve_file(pid: Optional[int] = None) -> None:
    """Remove the runtime file (only when it names pid, if given)."""
    if pid is not None:
        rec = read_record(SERVE_FILE)
        if not rec or rec.get("pid") != pid:
            return
    try:
        SERVE_FILE.unlink()
    except OSError:
        pass


def warn_exposed(host: str, port: int) -> None:
    if is_loopback(host):
        return
    bar = "!" * 72
    print(f"{bar}\nWARNING: serving the board on {host}, not 127.0.0.1. Anyone who can reach this machine on port "
          f"{port} can open the board page and CHANGE TICKETS (the page hands out the write token).\n"
          f"  fix: {CMD} serve --host 127.0.0.1   (and from another machine: ssh -L {port}:localhost:{port} HOST)\n"
          f"{bar}", file=sys.stderr, flush=True)


def split_issue_text(text: str) -> Tuple[str, str, str]:
    """"ACME-001 handoff: needs a note" -> (id, field, message); anything else -> ("", "", text)."""
    m = re.match(r"^(\S+) ([A-Za-z_][\w.\[\]:-]*): (.+)$", text, re.S)
    if m and not m.group(1).endswith(":"):
        return m.group(1), m.group(2), m.group(3)
    return "", "", text


def refusal_errors(e: Exception) -> List[Dict[str, Any]]:
    """A Refused / UsageError as the API's errors list: [{id, field, message, fix: [...]}, ...]."""
    tid, field, message = split_issue_text(getattr(e, "message", str(e)))
    out = [{"id": tid, "field": field, "message": message, "fix": list(getattr(e, "fix", []))}]
    for i in getattr(e, "issues", []):
        if i.field or i.message:
            out.append(i.as_dict())
        else:
            tid, field, message = split_issue_text(i.where)
            out.append({"id": tid, "field": field, "message": message, "fix": list(i.fix)})
    return out


def note_needed(doc: Dict[str, Any], t: Dict[str, Any], target: str) -> Optional[str]:
    """Why a move to target needs a handoff note, or None."""
    prev = t.get("status")
    if note_required(doc, target):
        return f"moving to {slabel(target)} needs a note"
    sts = statuses_of(doc)
    if isinstance(prev, str) and prev in sts and target in sts and sts.index(target) < sts.index(prev) \
            and any(status_meta_map(meta_of(doc), "status_from").values()):
        return f"moving back {slabel(prev)} → {slabel(target)} needs a reason"
    return None


def api_set(body: Dict[str, Any]) -> None:
    """POST /api/set: the same checks as `set` (a dry run first, so a missing note is only asked for when
    the move would otherwise go through)."""
    tid, status = body["id"], body["status"]
    handoff = body.get("handoff")
    doc = load_for_write()
    me = whoami(body.get("as"))
    take_over = body.get("take_over")
    if not (handoff or "").strip():
        set_status(copy.deepcopy(doc), tid, status, "...", save=False, me=me, take_over=take_over)
        why = note_needed(doc, find(doc, tid), status)
        if why:
            raise NeedsHandoff(f"{tid} handoff: {why}",
                               fix=[f"{CMD} set {tid} {status} --handoff \"what was done, what was verified, follow-ups\""])
    t, warnings = set_status(doc, tid, status, handoff, me=me, take_over=take_over)
    print(line(t))
    for w in warnings:
        print(f"warning: {w}")


def api_allowed(tid: str, as_: Optional[str]) -> Dict[str, Any]:
    """GET /api/allowed: every status a `set` would accept right now (a handoff note assumed), and why the
    others would be refused. Nothing is written."""
    global BASE_ERRORS
    doc = read_board()
    t = find(doc, tid)
    cur = t.get("status")
    allowed: List[str] = []
    reasons: Dict[str, str] = {}
    try:
        refuse_if_newer(doc)
    except Refused as e:
        return {"allowed": [], "reasons": {s: e.message for s in statuses_of(doc) if s != cur}}
    BASE_ERRORS = validate(doc)[0]
    me = whoami(as_)
    for s in statuses_of(doc):
        if s == cur:
            continue
        try:
            set_status(copy.deepcopy(doc), tid, s, "...", save=False, me=me)
        except Refused as e:
            errs = refusal_errors(e)
            first = errs[0]["message"]
            more = [(f"{x['id']} {x['field']}: " if x["field"] else "") + x["message"] for x in errs[1:2]]
            reasons[s] = (first.rstrip(":") + ": " + more[0]) if more and first.endswith(":") else \
                "; ".join([first] + more)
            continue
        allowed.append(s)
    return {"allowed": allowed, "reasons": reasons}


def api_info(token: str, cache: Dict[str, Any]) -> Dict[str, Any]:
    try:
        doc: Optional[Dict[str, Any]] = read_board()
    except Refused:
        doc = None
    now = time.monotonic()
    if cache.get("at") is None or now - cache["at"] > DOCTOR_CACHE_SECONDS or cache.get("doc") != doc:
        try:
            probs = [p for p in doctor_problems(None, doc) if not p.get("info")]
        except Exception as e:  # never break the page over a health check
            probs = [{"code": "doctor-failed", "kind": "setup", "message": str(e), "fix": [f"{CMD} doctor"]}]
        cache.update(at=now, doc=copy.deepcopy(doc), issues=[
            {"code": p["code"], "kind": p["kind"], "message": p["message"], "fix": p.get("fix", [])} for p in probs])
    if doc is not None:
        use_roles(doc)
    rec = read_record(UNLOCK)
    until = parse_utc(rec.get("until")) if rec else None
    unlock = {"until": rec.get("until"), "reason": rec.get("reason")} if rec and until and until > utcnow() else None
    return {"slate": True, "version": SLATE_VERSION, "board_path": board_path_str(), "token": token,
            "workflow": workflow_name(doc) if doc is not None else "free",
            "statuses": status_setup(doc)["statuses"] if doc is not None else [],
            "unlock_active": unlock, "doctor": {"issues": cache["issues"]},
            "pid": os.getpid(), "me": whoami(None)}


def body_str(body: Dict[str, Any], key: str, required: bool = True) -> Optional[str]:
    v = body.get(key)
    if v is None and not required:
        return None
    if not isinstance(v, str) or (required and not v.strip()):
        raise UsageError(f"{key}: must be {'non-empty ' if required else ''}text")
    return v


def body_int(body: Dict[str, Any], key: str) -> int:
    v = body.get(key)
    if isinstance(v, str) and v.strip().lstrip("-").isdigit():
        v = int(v)
    if not is_int(v):
        raise UsageError(f"{key}: must be a whole number")
    return v


def api_action(path: str, body: Dict[str, Any]) -> Tuple[List[str], Any]:
    """(the equivalent CLI arguments, a function running the CLI's own code) for one POST endpoint.
    Raises UsageError for a malformed body and KeyError for an unknown endpoint."""
    tid = body_str(body, "id") or ""
    tid = tid.strip()
    if "," in tid or not tid:
        raise UsageError("id: one ticket id")
    body["id"] = tid
    ns = argparse.Namespace
    if path == "/api/set":
        status = (body_str(body, "status") or "").strip()
        body["status"] = status
        for k in ("handoff", "as", "take_over"):
            body_str(body, k, required=False)
        argv = ["set", tid, status] + (["--handoff", body["handoff"]] if body.get("handoff") else [])
        return argv, lambda: api_set(body)
    if path in ("/api/check-item", "/api/uncheck-item"):
        kind = body_str(body, "kind")
        if kind not in ITEM_KINDS:
            raise UsageError("kind: must be acceptance or test")
        index = body_int(body, "index")
        name = path[len("/api/"):]
        evidence = body_str(body, "evidence", required=False) if name == "check-item" else None
        argv = [name, tid, str(kind), str(index)] + (["--evidence", evidence] if evidence else [])
        return argv, lambda: cmd_check_item(ns(cmd=name, id=tid, kind=kind, index=index, evidence=evidence))
    if path == "/api/usertest":
        index = body_int(body, "index")
        result = body_str(body, "result")
        if result not in ("pass", "fail", "reset"):
            raise UsageError("result: must be pass, fail or reset")
        note = body_str(body, "note", required=False)
        argv = ["usertest", tid, str(index), str(result)] + (["--note", note] if note else [])
        return argv, lambda: cmd_usertest(ns(id=tid, index=index, result=result, note=note))
    if path == "/api/note":
        text = body_str(body, "text") or ""
        return ["note", tid, text], lambda: cmd_note(ns(id=tid, text=text))
    if path == "/api/promote":
        handoff = body_str(body, "handoff", required=False)
        return ["promote", tid], lambda: cmd_promote(ns(id=tid, handoff=handoff))
    if path in ("/api/claim", "/api/release"):
        as_ = body_str(body, "as", required=False)
        take_over = body_str(body, "take_over", required=False)
        name = path[len("/api/"):]
        argv = [name, tid] + (["--as", as_] if as_ else []) + (["--take-over", take_over] if take_over else [])
        fn = cmd_claim if name == "claim" else cmd_release
        return argv, lambda: fn(ns(id=tid, as_=as_, take_over=take_over))
    raise KeyError(path)


def run_api_write(argv: List[str], fn: Any) -> Tuple[int, Dict[str, Any]]:
    """Run one board change the way main() runs a CLI write: write lock held, board read after it, the
    whole board validated; history entries record via: "board page". Caller holds the API lock."""
    import contextlib
    import io
    global VIA, BASE_ERRORS
    RAW_ARGV[:] = argv
    BASE_ERRORS = []
    VIA = VIA_PAGE
    out, err = io.StringIO(), io.StringIO()
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            with WriteLock():
                fn()
    except NeedsHandoff as e:
        errs = refusal_errors(e)
        errs[0]["code"] = e.code
        return 409, {"ok": False, "code": e.code, "errors": errs}
    except Refused as e:
        return 409, {"ok": False, "errors": refusal_errors(e)}
    except UsageError as e:
        return 400, {"ok": False, "errors": refusal_errors(e)}
    finally:
        VIA = None
        BASE_ERRORS = []
        RAW_ARGV[:] = []
    return 200, {"ok": True, "message": out.getvalue().strip(),
                 "warnings": [ln for ln in err.getvalue().splitlines() if ln.strip()]}


def make_server(host: str, port: int, token: str, idle_seconds: float) -> Any:
    import http.server
    import socketserver
    import threading
    import urllib.parse

    api_lock = threading.Lock()
    info_cache: Dict[str, Any] = {}
    base = os.path.realpath(str(HERE))
    loopback = is_loopback(host)

    class Server(http.server.ThreadingHTTPServer):
        daemon_threads = True
        allow_reuse_address = os.name != "nt"
        address_family = socket.AF_INET6 if ":" in host else socket.AF_INET
        last_request = time.monotonic()

        def server_bind(self) -> None:  # skip HTTPServer's getfqdn (slow reverse DNS on some machines)
            socketserver.TCPServer.server_bind(self)
            self.server_name = host
            self.server_port = self.server_address[1]

    class Handler(http.server.SimpleHTTPRequestHandler):
        server_version = f"Slate/{SLATE_VERSION}"
        protocol_version = "HTTP/1.0"

        def __init__(self, *args: Any, **kwargs: Any) -> None:
            super().__init__(*args, directory=str(HERE), **kwargs)

        def log_request(self, code: Any = "-", size: Any = "-") -> None:
            try:
                n = int(code)
            except (TypeError, ValueError):
                n = 0
            if self.command == "POST" or n >= 400:
                super().log_request(code, size)

        def log_message(self, format: str, *args: Any) -> None:
            sys.stderr.write(f"[{log_time()} UTC] {self.address_string()} {format % args}\n")
            sys.stderr.flush()

        def end_headers(self) -> None:
            self.send_header("Cache-Control", "no-cache")
            self.send_header("X-Content-Type-Options", "nosniff")
            super().end_headers()

        def host_ok(self) -> bool:
            """Loopback server: the Host (and Origin, if any) must name this machine, so a web page on another
            site can't reach the API through DNS rebinding."""
            if not loopback:
                return True
            names = set(LOOPBACK_NAMES) | {host}

            def name_of(netloc: str) -> str:
                netloc = netloc.strip().lower()
                if netloc.startswith("["):
                    return netloc[1:netloc.find("]")] if "]" in netloc else netloc
                return netloc.rsplit(":", 1)[0] if netloc.count(":") == 1 else netloc

            if name_of(self.headers.get("Host", "")) not in names:
                return False
            origin = self.headers.get("Origin")
            if origin and origin != "null":
                return name_of(urllib.parse.urlsplit(origin).netloc) in names
            return True

        def send_json(self, code: int, obj: Any) -> None:
            data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(data)

        def refuse(self, code: int, field: str, message: str, fix: Sequence[str] = ()) -> None:
            self.send_json(code, {"ok": False, "errors": [{"id": "", "field": field, "message": message,
                                                           "fix": list(fix)}]})

        def touch(self) -> bool:
            Server.last_request = time.monotonic()
            if not self.host_ok():
                self.refuse(403, "host", "requests must come from this machine's board page "
                                         f"(open {url_for(host, self.server.server_port)})")
                return False
            return True

        # ---- files: only inside the kanban folder, no dotfiles (but the unlock record), no directory listings
        def send_head(self) -> Any:
            rel = urllib.parse.unquote(urllib.parse.urlsplit(self.path).path)
            parts = [p for p in re.split(r"[/\\]", rel) if p]
            if any(p.startswith(".") for p in parts) and parts != [UNLOCK.name]:
                self.send_error(404, "Not found")
                return None
            real = os.path.realpath(self.translate_path(self.path))
            if real != base and not real.startswith(base.rstrip(os.sep) + os.sep):
                self.send_error(404, "Not found")
                return None
            page = os.path.join(real, "index.html") if os.path.isdir(real) and rel.endswith("/") else real
            if page == os.path.join(base, "index.html") and os.path.isfile(page):
                return self.send_page(page)
            return super().send_head()

        def send_page(self, path: str) -> Any:
            """index.html with <meta name="slate-token"> added (Last-Modified / If-Modified-Since as for files)."""
            import email.utils
            import io
            mtime = os.stat(path).st_mtime
            ims = self.headers.get("If-Modified-Since")
            if ims and "If-None-Match" not in self.headers:
                try:
                    when = email.utils.parsedate_to_datetime(ims)
                    if when.tzinfo is None:
                        when = when.replace(tzinfo=timezone.utc)
                    if int(mtime) <= when.timestamp():
                        self.send_response(304)
                        self.end_headers()
                        return None
                except (TypeError, ValueError, IndexError, OverflowError):
                    pass
            with open(path, "rb") as f:
                data = f.read()
            tag = f'<meta name="slate-token" content="{token}">'.encode("ascii")
            m = re.search(rb"<head[^>]*>", data, re.I)
            data = data[:m.end()] + tag + data[m.end():] if m else tag + data
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Last-Modified", email.utils.formatdate(mtime, usegmt=True))
            self.end_headers()
            return io.BytesIO(data)

        def list_directory(self, path: Any) -> Any:
            self.send_error(404, "Not found")
            return None

        def do_HEAD(self) -> None:
            if not self.touch():
                return
            if urllib.parse.urlsplit(self.path).path.startswith("/api/"):
                self.send_error(405, "Use GET or POST")
                return
            super().do_HEAD()

        def do_GET(self) -> None:
            if not self.touch():
                return
            parsed = urllib.parse.urlsplit(self.path)
            if parsed.path == "/preview.json" and not PREVIEW.exists():
                # no preview: answer "none" instead of a 404 the page's polling would log every 5 s
                self.send_json(200, {"preview": False})
                return
            if not parsed.path.startswith("/api/"):
                super().do_GET()
                return
            q = urllib.parse.parse_qs(parsed.query)
            with api_lock:
                try:
                    if parsed.path == "/api/info":
                        self.send_json(200, api_info(token, info_cache))
                    elif parsed.path == "/api/allowed":
                        tid = (q.get("id") or [""])[0].strip()
                        if not tid:
                            self.refuse(400, "id", "give ?id=TICKET_ID")
                            return
                        self.send_json(200, api_allowed(tid, (q.get("as") or [None])[0]))
                    else:
                        self.refuse(404, "path", f"no such API: {parsed.path}")
                except Refused as e:
                    self.send_json(409, {"ok": False, "errors": refusal_errors(e)})

        def do_POST(self) -> None:
            if not self.touch():
                return
            path = urllib.parse.urlsplit(self.path).path
            try:
                length = int(self.headers.get("Content-Length") or 0)
            except ValueError:
                length = -1
            if length < 0 or length > 1_000_000:
                self.refuse(413 if length > 0 else 400, "body", "the request body must be JSON under 1 MB")
                return
            raw = self.rfile.read(length) if length else b""
            if not secrets.compare_digest(self.headers.get("X-Slate-Token", "").encode("utf-8"),
                                          token.encode("utf-8")):
                self.refuse(403, "token", "missing or wrong X-Slate-Token (the board server was restarted?)",
                            ["reload the board page"])
                return
            try:
                body = json.loads(raw.decode("utf-8") or "{}")
            except (ValueError, UnicodeDecodeError):
                self.refuse(400, "body", "the request body must be a JSON object")
                return
            if not isinstance(body, dict):
                self.refuse(400, "body", "the request body must be a JSON object")
                return
            try:
                argv, fn = api_action(path, body)
            except KeyError:
                self.refuse(404, "path", f"no such API: {path}")
                return
            except UsageError as e:
                self.send_json(400, {"ok": False, "errors": refusal_errors(e)})
                return
            with api_lock:
                code, payload = run_api_write(argv, fn)
            self.send_json(code, payload)

    srv = Server((host, port), Handler)
    srv.idle_seconds = idle_seconds
    return srv


def port_candidates(port: int, strict: bool) -> List[int]:
    return [port] if strict else [p for p in range(port, port + SERVE_PORT_TRIES) if p <= 65535]


def serve_foreground(a: argparse.Namespace) -> int:
    import signal
    import threading
    read_board()  # fail early (with the usual fix) when there is no readable board
    rec = live_server(read_record(SERVE_FILE))
    if rec:
        raise Refused(f"serve: a board server for this board is already running at {rec['url']} (pid {rec['pid']})",
                      fix=[f"open {rec['url']}", f"{CMD} serve --stop   (then start it again)"])
    host = a.host
    srv = None
    skipped: List[int] = []
    for p in port_candidates(a.port, a.strict_port):
        if not can_bind(host, p):
            skipped.append(p)
            continue
        try:
            srv = make_server(host, p, secrets.token_urlsafe(24), a.idle_exit * 3600.0)
            break
        except OSError:
            skipped.append(p)
    if srv is None:
        if a.strict_port:
            raise Refused(f"serve: port {a.port} is taken on {host} (--strict-port)",
                          fix=[f"{CMD} serve --port {a.port + 1}", f"{CMD} serve   (without --strict-port: the next free port)"])
        raise Refused(f"serve: no free port from {a.port} to {a.port + SERVE_PORT_TRIES - 1} on {host}",
                      fix=[f"{CMD} serve --port 9000"])
    port = srv.server_address[1]
    url = url_for(host, port)
    atomic_write(SERVE_FILE, dumps({"pid": os.getpid(), "host": host, "port": port, "url": url,
                                    "started": iso_utc(utcnow()), "board_path": board_path_str(),
                                    "slate_version": SLATE_VERSION}))
    warn_exposed(host, port)
    if skipped:
        print(f"Port {skipped[0]} is taken; using {port}.")
    print(f"Slate board page (live: changes save to the board): {url}", flush=True)
    print(f"Stop it with Ctrl+C or: {CMD} serve --stop" + (f"; it stops by itself after {a.idle_exit:g} h without "
                                                           "a request" if a.idle_exit > 0 else ""), flush=True)
    stop = threading.Event()

    def watchdog() -> None:
        idle = srv.idle_seconds
        step = max(0.2, min(30.0, idle / 4))
        while not stop.wait(step):
            if time.monotonic() - type(srv).last_request > idle:
                print(f"[{log_time()} UTC] no request for {a.idle_exit:g} h; stopping", file=sys.stderr, flush=True)
                srv.shutdown()
                return

    if a.idle_exit > 0:
        threading.Thread(target=watchdog, daemon=True).start()

    def on_term(signum: int, frame: Any) -> None:
        raise SystemExit(0)

    try:
        signal.signal(signal.SIGTERM, on_term)
    except (ValueError, OSError, AttributeError):
        pass
    if a.open:
        import webbrowser
        webbrowser.open(url)
    try:
        srv.serve_forever(poll_interval=0.25)
    except (KeyboardInterrupt, SystemExit):
        pass
    finally:
        stop.set()
        srv.server_close()
        remove_serve_file(os.getpid())
    return 0


def start_background(host: str, port: int, idle: float) -> Any:
    args = [sys.executable, str(HERE / "board.py"), "serve", "--port", str(port), "--strict-port",
            "--host", host, "--idle-exit", f"{idle:g}"]
    env = dict(os.environ, PYTHONUNBUFFERED="1")
    kw: Dict[str, Any] = {"stdin": subprocess.DEVNULL, "stderr": subprocess.STDOUT, "cwd": str(HERE),
                          "close_fds": True, "env": env}
    if os.name == "nt":
        kw["creationflags"] = 0x00000008 | 0x00000200  # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    else:
        kw["start_new_session"] = True
    with open(SERVE_LOG, "w", encoding="utf-8", newline="\n") as log:
        return subprocess.Popen(args, stdout=log, **kw)


def log_tail(n: int = 6) -> str:
    try:
        lines = SERVE_LOG.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return ""
    return " | ".join(ln.strip() for ln in lines[-n:] if ln.strip())


def serve_ensure(a: argparse.Namespace) -> int:
    read_board()
    host = a.host
    rec = read_record(SERVE_FILE)
    if rec is not None:
        live = live_server(rec)
        if not live and is_int(rec.get("pid")) and pid_alive(rec["pid"]):
            started = parse_utc(rec.get("started"))
            if started and utcnow() - started < timedelta(seconds=15):  # still starting up: give it a moment
                for _ in range(20):
                    time.sleep(0.25)
                    live = live_server(rec)
                    if live:
                        break
        if live:
            print(f"Slate board page (live): {live['url']}   (already running, pid {live['pid']})")
            return open_url(a, live["url"])
        why = (f"process {rec.get('pid')} isn't running" if not (is_int(rec.get("pid")) and pid_alive(rec["pid"]))
               else f"process {rec.get('pid')} doesn't answer as this board's server")
        remove_serve_file()
        print(f"Removed a stale kanban/.slate-serve.json ({why}).")
    warn_exposed(host, a.port)
    foreign: List[int] = []
    tried: Set[int] = set()
    for _attempt in range(3):
        chosen = None
        for p in port_candidates(a.port, a.strict_port):
            if p in tried:
                continue
            if can_bind(host, p):
                chosen = p
                break
            kind, info = probe(url_for(host, p), timeout=1.0)
            if kind == "busy":  # slow machines: give a real web server time to answer before judging
                for _retry in range(3):
                    time.sleep(0.5)
                    kind, info = probe(url_for(host, p), timeout=3.0)
                    if kind != "busy":
                        break
                if kind == "busy" and speaks_http(host, p):
                    kind = "http"
            if kind == "slate" and same_board(info):
                print(f"Slate board page (live): {url_for(host, p)}   (already running, pid {info.get('pid', '?')})")
                return open_url(a, url_for(host, p))
            if kind == "none":
                chosen = p
                break
            tried.add(p)
            if kind == "http" and p not in foreign:
                foreign.append(p)
        if chosen is None:
            if a.strict_port:
                raise Refused(f"serve: port {a.port} is taken on {host} (--strict-port)"
                              + ("; it answers but isn't a Slate server" if foreign else ""),
                              fix=[f"{CMD} serve --ensure --port {a.port + 1}",
                                   f"{CMD} serve --ensure --port {a.port}   (without --strict-port: the next free port)"])
            raise Refused(f"serve: no free port from {a.port} to {a.port + SERVE_PORT_TRIES - 1} on {host}",
                          fix=[f"{CMD} serve --ensure --port 9000"])
        tried.add(chosen)
        proc = start_background(host, chosen, a.idle_exit)
        deadline = time.monotonic() + 15.0
        while time.monotonic() < deadline:
            time.sleep(0.1)
            cur = read_record(SERVE_FILE)
            if cur and cur.get("pid") == proc.pid:
                live = live_server(cur)
                if live:
                    url = live["url"]
                    if foreign:
                        print(f"Port {foreign[0]} answers but isn't a Slate server: the board is open there in "
                              f"view-only mode; live mode at {url}")
                    elif chosen != a.port:
                        print(f"Port {a.port} is taken; using {chosen}.")
                    print(f"Slate board page (live): {url}   (started in the background, pid {proc.pid}; "
                          f"log: kanban/.slate-serve.log; stop: {CMD} serve --stop)")
                    return open_url(a, url)
            if proc.poll() is not None:
                other = live_server(read_record(SERVE_FILE))  # another --ensure won the race
                if other:
                    print(f"Slate board page (live): {other['url']}   (already running, pid {other['pid']})")
                    return open_url(a, other["url"])
                break
        else:
            raise Refused(f"serve: the background server didn't answer within 15 s (pid {proc.pid})",
                          fix=["cat kanban/.slate-serve.log   (what it printed)", f"{CMD} serve --stop",
                               f"{CMD} serve --port {chosen}   (run it in the foreground to see what happens)"])
        if a.strict_port:
            break
    raise Refused("serve: the background server stopped right after starting"
                  + (f": {log_tail()}" if log_tail() else ""),
                  fix=["cat kanban/.slate-serve.log", f"{CMD} serve --port {a.port}   (in the foreground, to see why)"])


def open_url(a: argparse.Namespace, url: str) -> int:
    if a.open:
        import webbrowser
        webbrowser.open(url)
    return 0


def serve_status(a: argparse.Namespace) -> int:
    rec = read_record(SERVE_FILE)
    if rec is None:
        print("No board server is running for this board (no kanban/.slate-serve.json).")
        print(f"  start one: {CMD} serve --ensure")
        return 0
    live = live_server(rec)
    if live:
        print(f"Board server running: {live['url']}   (pid {live['pid']}, since {live.get('started', '?')}, "
              f"Slate {live.get('slate_version', '?')})")
        return 0
    print(f"kanban/.slate-serve.json is stale (pid {rec.get('pid', '?')} "
          + ("isn't running" if not (is_int(rec.get("pid")) and pid_alive(rec["pid"])) else "doesn't answer as this board's server")
          + ").")
    print(f"  fix: {CMD} serve --ensure   (cleans it up and starts a server)")
    return 0


def serve_stop(a: argparse.Namespace) -> int:
    import signal
    rec = read_record(SERVE_FILE)
    if rec is None:
        print("No board server recorded (no kanban/.slate-serve.json); nothing to stop.")
        return 0
    pid = rec.get("pid")
    alive = is_int(pid) and pid_alive(pid)
    kind, info = probe(rec["url"]) if alive and isinstance(rec.get("url"), str) else ("none", None)
    if alive and kind == "slate" and same_board(info) and info.get("pid") in (pid, None):
        try:
            os.kill(pid, signal.SIGTERM)
        except OSError as e:
            raise Refused(f"serve: can't stop process {pid} ({e.strerror or e})",
                          fix=[ASK + f"can you stop process {pid} (the board server at {rec.get('url')})?"])
        deadline = time.monotonic() + 5.0
        while time.monotonic() < deadline and probe(rec["url"], timeout=0.3)[0] == "slate":
            time.sleep(0.1)
        remove_serve_file()
        print(f"Stopped the board server at {rec.get('url')} (pid {pid}).")
        return 0
    remove_serve_file()
    if alive:
        print(f"Process {pid} is running but doesn't answer as this board's server, so it was left alone; "
              "removed the stale kanban/.slate-serve.json.")
    else:
        print(f"The recorded server (pid {pid}) wasn't running; removed the stale kanban/.slate-serve.json.")
    return 0


def slate_md_port() -> Optional[int]:
    """SLATE.md's `Board port: N` line (the project's default port), if any."""
    try:
        text = (HERE.parent / "SLATE.md").read_text(encoding="utf-8")
    except OSError:
        return None
    m = re.search(r"^\s*[-*]?\s*Board port:\s*`?(\d{1,5})`?", text, re.M | re.I)
    return int(m.group(1)) if m else None


def cmd_serve(a: argparse.Namespace) -> int:
    if a.port is None:
        a.port = slate_md_port() or SERVE_PORT
    if a.port < 1 or a.port > 65535:
        raise UsageError(f"serve: --port {a.port} must be 1-65535", fix=[f"{CMD} serve --port {SERVE_PORT}"])
    if a.idle_exit < 0:
        raise UsageError("serve: --idle-exit must be 0 (never) or more hours", fix=[f"{CMD} serve --idle-exit 8"])
    if a.status:
        return serve_status(a)
    if a.stop:
        return serve_stop(a)
    if a.ensure:
        return serve_ensure(a)
    return serve_foreground(a)


# --------------------------------------------------------------------------- CLI


class Parser(argparse.ArgumentParser):
    def error(self, message: str) -> None:  # type: ignore[override]
        self.print_usage(sys.stderr)
        print(f"{self.prog}: usage error: {message}", file=sys.stderr)
        sub = "".join(" " + w for w in self.prog.split()[1:])
        print(f"  fix: {CMD}{sub} --help   (shows the right arguments)", file=sys.stderr)
        raise SystemExit(2)


def build_parser() -> argparse.ArgumentParser:
    p = Parser(prog="board.py", description=f"Slate board v{SLATE_VERSION}: the only way to change kanban/tickets.json.")
    sub = p.add_subparsers(dest="cmd", parser_class=Parser, metavar="COMMAND")

    s = sub.add_parser("init", help="create tickets.json for a project")
    s.add_argument("--project", required=True)
    s.add_argument("--prefix", required=True, help="ticket id prefix, e.g. ACME")
    s.add_argument("--areas", help="comma list, default backend,frontend,infra")
    s.add_argument("--repo-url", dest="repo_url", metavar="URL", help="repository web address, for commit links")
    s.set_defaults(func=cmd_init)

    s = sub.add_parser("version", help="print board, schema and tickets.json versions")
    s.add_argument("--against", metavar="PLUGIN_ROOT")
    s.add_argument("--json", action="store_true")
    s.set_defaults(func=cmd_version)

    s = sub.add_parser("next", help="what to work on next (open tickets first)")
    s.add_argument("--brief", action="store_true")
    s.add_argument("--json", action="store_true")
    s.add_argument("--against", metavar="PLUGIN_ROOT")
    s.add_argument("--as", dest="as_", metavar="NAME", help="who you are for claims (default: the git branch)")
    s.set_defaults(func=cmd_next)

    s = sub.add_parser("list", help="next N ready tickets (unscheduled phases are skipped)")
    s.add_argument("n", nargs="?", type=int, default=5, metavar="N")
    s.add_argument("--json", action="store_true")
    s.add_argument("--as", dest="as_", metavar="NAME", help="who you are for claims (default: the git branch)")
    add_filter_args(s)
    s.set_defaults(func=cmd_list)

    s = sub.add_parser("export", help="full tickets as JSON, filtered (drafts left out unless --drafts)")
    s.add_argument("--json", action="store_true", help="JSON output (the only format)")
    s.add_argument("--drafts", action="store_true", help="include draft tickets")
    s.add_argument("--removed", action="store_true", help="list removed (archived) tickets instead")
    s.add_argument("--statuses", action="store_true", help="print the status setup (roles, labels, rules) instead")
    add_filter_args(s)
    s.set_defaults(func=cmd_export)

    s = sub.add_parser("show", help="one ticket in full, in plain text")
    s.add_argument("id", metavar="ID")
    s.add_argument("--json", action="store_true")
    s.set_defaults(func=cmd_show)

    s = sub.add_parser("status", help="progress per phase and status")
    s.add_argument("--json", action="store_true")
    add_filter_args(s)
    s.set_defaults(func=cmd_status)

    s = sub.add_parser("check", help="validate the board (exit 1 on errors)")
    s.add_argument("--json", action="store_true")
    s.add_argument("--quiet-optional", dest="quiet_optional", action="store_true",
                   help="hide optional-field warnings (missing visual/technical); also meta.check_quiet_optional")
    s.set_defaults(func=cmd_check)

    s = sub.add_parser("new", help="create one ticket from flags")
    s.add_argument("--title", required=True)
    s.add_argument("--summary", required=True)
    s.add_argument("--phase", required=True)
    s.add_argument("--draft", action="store_true", help="save as a draft (not ready to work)")
    s.add_argument("--story")
    s.add_argument("--description")
    s.add_argument("--acceptance", action="append", metavar="TEXT")
    s.add_argument("--test", action="append", metavar="TEXT", help="automated test scenario")
    s.add_argument("--priority", default="P2")
    s.add_argument("--areas", action="append", metavar="a,b", help="repeatable; comma lists allowed")
    s.add_argument("--depends", action="append", metavar="ID,...", help="repeatable; comma lists allowed")
    s.add_argument("--estimate", default="1d")
    s.add_argument("--visual")
    s.add_argument("--technical")
    s.add_argument("--plan-doc", dest="plan_doc")
    s.add_argument("--labels", action="append", metavar="a,b", help="repeatable; comma lists allowed")
    s.add_argument("--user-test-json", dest="user_test_json", action="append", metavar="JSON")
    s.add_argument("--after", metavar="ID")
    s.add_argument("--bug", action="store_true", help="label the ticket bug")
    s.add_argument("--fixes", action="append", metavar="ID,...",
                   help="the tickets this bug is in: they wait for it; it is ranked right before them")
    s.add_argument("--reopen", action="store_true",
                   help="with --fixes: move fixed tickets that are done / merge_ready back to in_progress")
    s.add_argument("--dry-run", dest="dry_run", action="store_true")
    s.set_defaults(func=cmd_new)

    s = sub.add_parser("add", help="add tickets from a batch file")
    s.add_argument("--file", required=True, metavar="BATCH")
    s.add_argument("--after", metavar="ID")
    s.add_argument("--dry-run", dest="dry_run", action="store_true")
    s.add_argument("--as-draft", dest="as_draft", action="store_true")
    s.set_defaults(func=cmd_add)

    s = sub.add_parser("batch-check", help="validate a batch file on its own")
    s.add_argument("--file", required=True, metavar="BATCH")
    s.add_argument("--as-draft", dest="as_draft", action="store_true")
    s.add_argument("--json", action="store_true")
    s.set_defaults(func=cmd_batch_check)

    s = sub.add_parser("discard-preview", help="remove kanban/preview.json")
    s.set_defaults(func=cmd_discard_preview)

    s = sub.add_parser("set", help="change a ticket's status (ID1,ID2 for several: all or nothing)")
    s.add_argument("id", metavar="ID[,ID...]")
    s.add_argument("status", metavar="STATUS")
    s.add_argument("--handoff", metavar="NOTE")
    s.add_argument("--ignore-deps", dest="ignore_deps", metavar="REASON",
                   help="start before dependencies are done (in_progress, review, user_testing only)")
    g = s.add_mutually_exclusive_group()
    g.add_argument("--no-code", dest="no_code", metavar="REASON",
                   help="done without any commit (skips the commit and PR checks)")
    g.add_argument("--no-pr", dest="no_pr", metavar="REASON", help="merge_ready / done without a pull request")
    s.add_argument("--as", dest="as_", metavar="NAME", help="who is working, for the claim (default: the git branch)")
    s.add_argument("--take-over", dest="take_over", metavar="REASON",
                   help="move a ticket claimed by someone else (the reason goes in the handoff note)")
    s.set_defaults(func=cmd_set)

    s = sub.add_parser("edit", help="change ticket fields: key=value, key+=text (append) or key:=JSON")
    s.add_argument("id", metavar="ID")
