    s.add_argument("--file", metavar="PATCH.json")
    s.add_argument("--rerank", action="store_true",
                   help="move the ticket right after its latest dependency if it sits before it")
    s.set_defaults(func=cmd_edit)

    s = sub.add_parser("rerank", help="move a ticket in the build order")
    s.add_argument("id", metavar="ID")
    g = s.add_mutually_exclusive_group(required=True)
    g.add_argument("--after", metavar="OTHER")
    g.add_argument("--first", action="store_true")
    s.set_defaults(func=cmd_rerank)

    s = sub.add_parser("promote", help="turn a draft into a backlog ticket")
    s.add_argument("id", metavar="ID")
    s.add_argument("--handoff", metavar="NOTE")
    s.set_defaults(func=cmd_promote)

    s = sub.add_parser("add-phase", help="append a phase")
    s.add_argument("--id", required=True, help="letters, digits, - or _, starting with a letter (e.g. P3, BACKLOG)")
    s.add_argument("--name", required=True)
    s.add_argument("--goal", required=True)
    s.add_argument("--demo", required=True)
    s.add_argument("--unscheduled", action="store_true", help="a someday phase: next and list skip its tickets")
    s.set_defaults(func=cmd_add_phase)

    s = sub.add_parser("edit-phase", help="change a phase: name=, goal=, demo=, unscheduled:=true|false")
    s.add_argument("id", metavar="ID")
    s.add_argument("assignments", nargs="*", metavar="key=value")
    s.set_defaults(func=cmd_edit_phase)

    s = sub.add_parser("rename-phase", help="change a phase id; its tickets move with it")
    s.add_argument("old", metavar="OLD")
    s.add_argument("new", metavar="NEW")
    s.set_defaults(func=cmd_rename_phase)

    s = sub.add_parser("remove-phase", help="remove a phase (--move-to OTHER when tickets use it)")
    s.add_argument("id", metavar="ID")
    s.add_argument("--move-to", dest="move_to", metavar="OTHER")
    s.set_defaults(func=cmd_remove_phase)

    s = sub.add_parser("reorder-phases", help="set the phase display order; list every phase once")
    s.add_argument("ids", nargs="+", metavar="ID")
    s.set_defaults(func=cmd_reorder_phases)

    s = sub.add_parser("usertest", help="record a user test result")
    s.add_argument("id", metavar="ID")
    s.add_argument("index", type=int, metavar="INDEX")
    s.add_argument("result", choices=["pass", "fail", "reset"], help="reset clears a recorded result")
    s.add_argument("--note")
    s.set_defaults(func=cmd_usertest)

    s = sub.add_parser("link", help="record the commits and pull request that built a ticket (ID1,ID2 ok)")
    s.add_argument("id", metavar="ID[,ID...]")
    s.add_argument("--commit", action="append", metavar="SHA_OR_REF", help="repeatable; a sha or git ref like HEAD")
    s.add_argument("--message", help="commit subject, used when git can't look the sha up")
    s.add_argument("--pr", metavar="URL", help="pull / merge request link")
    s.add_argument("--pr-state", dest="pr_state", choices=list(PR_STATES))
    s.add_argument("--pr-title", dest="pr_title", metavar="TITLE")
